bool bridge_profile_enabled() {
    static const bool enabled = [] {
        char value[8]{};
        return GetEnvironmentVariableA("EI_RENDERER_BRIDGE_PROFILE", value, sizeof(value)) &&
               value[0] == '1';
    }();
    return enabled || InterlockedCompareExchange(&g_bridge_runtime_profile, 0, 0) != 0;
}
