thread_local OuterFrameTimingState g_outer_frame_timing{};
thread_local std::uint32_t g_outer_direct_timing_depth = 0;

enum class VisualUnitUpdateProfilePhase : std::uint8_t {
    inactive,
    unassigned,
    original,
    finish,
};

struct NativeTickOwnedPauseToken {
    NativeTickOwnedCallback owner = NativeTickOwnedCallback::count;
    bool active = false;
};
NativeTickOwnedPauseToken native_tick_owned_pause_begin() noexcept;
void native_tick_owned_pause_end(NativeTickOwnedPauseToken& token) noexcept;

struct VisualUnitUpdateProfileContext {
    VisualUnitUpdateProfilePhase parent =
        VisualUnitUpdateProfilePhase::inactive;
    bool active = false;
    NativeTickOwnedPauseToken owned_pause{};
};

thread_local VisualUnitUpdateProfilePhase g_visual_unit_update_profile_phase =
    VisualUnitUpdateProfilePhase::inactive;
thread_local std::int64_t g_visual_unit_update_profile_phase_begin = 0;
thread_local OuterFrameVisualFinishSample* g_visual_unit_update_finish_sample =
    nullptr;

bool outer_frame_timing_active() noexcept {
    return InterlockedCompareExchange(
        &g_outer_frame_timing_active, 0, 0) != 0;
}

void visual_unit_update_profile_reset() noexcept {
    g_visual_unit_update_profile_phase =
        VisualUnitUpdateProfilePhase::inactive;
    g_visual_unit_update_profile_phase_begin = 0;
    g_visual_unit_update_finish_sample = nullptr;
}

template<std::size_t Capacity>
bool copy_outer_frame_timing_text(
    std::array<char, Capacity>& destination, const char* source) noexcept {
    destination.fill('\0');
    if (!source) return true;
    if (!Capacity) return false;
    const auto length = strnlen_s(source, Capacity);
    if (length >= Capacity) return false;
    std::memcpy(destination.data(), source, length + 1u);
    return true;
}

std::int64_t visual_unit_update_finish_operation_begin() noexcept {
    return g_visual_unit_update_finish_sample &&
        g_visual_unit_update_profile_phase ==
            VisualUnitUpdateProfilePhase::finish ? bridge_now() : 0;
}

void visual_unit_update_finish_selected_clip_end_at(
    OuterFrameVisualFinishSample* sample,
    std::int64_t begin, std::int64_t end) noexcept {
    if (!sample) return;
    ++sample->selected_clip_calls;
    if (begin <= 0 || end < begin) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    sample->selected_clip_ticks += end - begin;
}

void visual_unit_update_finish_outer_unit_values_end_at(
    OuterFrameVisualFinishSample* sample,
    std::int64_t begin, std::int64_t end) noexcept {
    if (!sample) return;
    ++sample->outer_unit_values_calls;
    if (begin <= 0 || end < begin) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    sample->outer_unit_values_ticks += end - begin;
}

void visual_unit_update_finish_appearance_end_at(
    OuterFrameVisualFinishSample* sample,
    std::int64_t begin, std::int64_t selected_clip_ticks_at_begin,
    std::int64_t end) noexcept {
    if (!sample) return;
    ++sample->appearance_calls;
    if (begin <= 0 || end < begin ||
        sample->selected_clip_ticks < selected_clip_ticks_at_begin) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    const auto elapsed = end - begin;
    const auto nested_selected_clip_ticks =
        sample->selected_clip_ticks - selected_clip_ticks_at_begin;
    if (nested_selected_clip_ticks > elapsed) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    sample->appearance_ticks += elapsed - nested_selected_clip_ticks;
}

void visual_unit_update_profile_record_finish_at(
    OuterFrameVisualFinishSample sample,
    std::int64_t begin, std::int64_t end) noexcept {
    if (begin <= 0 || end < begin) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    sample.finish_ticks = end - begin;
    if (sample.appearance_ticks < 0 || sample.selected_clip_ticks < 0 ||
        sample.outer_unit_values_ticks < 0 ||
        sample.appearance_ticks > sample.finish_ticks ||
        sample.selected_clip_ticks >
            sample.finish_ticks - sample.appearance_ticks ||
        sample.outer_unit_values_ticks >
            sample.finish_ticks - sample.appearance_ticks -
                sample.selected_clip_ticks) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    g_outer_frame_timing.visual_unit_update_finish_appearance_ticks +=
        sample.appearance_ticks;
    g_outer_frame_timing.visual_unit_update_finish_selected_clip_ticks +=
        sample.selected_clip_ticks;
    g_outer_frame_timing.visual_unit_update_finish_outer_unit_values_ticks +=
        sample.outer_unit_values_ticks;
    g_outer_frame_timing.visual_unit_update_finish_appearance_calls +=
        sample.appearance_calls;
    g_outer_frame_timing.visual_unit_update_finish_selected_clip_calls +=
        sample.selected_clip_calls;
    g_outer_frame_timing.visual_unit_update_finish_outer_unit_values_calls +=
        sample.outer_unit_values_calls;
    if (sample.finish_ticks >
        g_outer_frame_timing.slowest_visual_unit_update_finish.finish_ticks)
        g_outer_frame_timing.slowest_visual_unit_update_finish = sample;
}

void visual_unit_update_profile_transition_at(
    VisualUnitUpdateProfilePhase next, std::int64_t now) noexcept {
    const auto previous = g_visual_unit_update_profile_phase;
    if (previous != VisualUnitUpdateProfilePhase::inactive) {
        if (now <= 0 || g_visual_unit_update_profile_phase_begin <= 0 ||
            now < g_visual_unit_update_profile_phase_begin) {
            g_outer_frame_timing.invalid = true;
        } else {
            const auto elapsed =
                now - g_visual_unit_update_profile_phase_begin;
            if (previous == VisualUnitUpdateProfilePhase::original)
                g_outer_frame_timing.visual_unit_update_original_ticks +=
                    elapsed;
            else if (previous == VisualUnitUpdateProfilePhase::finish)
                g_outer_frame_timing.visual_unit_update_finish_ticks +=
                    elapsed;
        }
    } else if (next != VisualUnitUpdateProfilePhase::inactive && now <= 0) {
        g_outer_frame_timing.invalid = true;
    }
    g_visual_unit_update_profile_phase = next;
    g_visual_unit_update_profile_phase_begin =
        next == VisualUnitUpdateProfilePhase::inactive ? 0 : now;
}

void visual_unit_update_profile_enter_at(
    VisualUnitUpdateProfileContext& context, std::int64_t now) noexcept {
    context = {};
    if (!outer_frame_timing_active() ||
        !g_outer_frame_timing.count_time_profile_active)
        return;
    context.parent = g_visual_unit_update_profile_phase;
    context.active = true;
    // The wrapper's original/finish already have child timers. Leave its
    // unassigned prefix in the native remainder rather than the parent owner.
    context.owned_pause = native_tick_owned_pause_begin();
    if (context.parent == VisualUnitUpdateProfilePhase::inactive)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::unassigned, now);
}

void visual_unit_update_profile_original_begin_at(
    VisualUnitUpdateProfileContext& context, std::int64_t now) noexcept {
    if (!context.active) return;
    if (g_visual_unit_update_profile_phase !=
        VisualUnitUpdateProfilePhase::unassigned)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::original, now);
    ++g_outer_frame_timing.visual_unit_update_original_calls;
}

void visual_unit_update_profile_original_end_at(
    VisualUnitUpdateProfileContext& context, std::int64_t now) noexcept {
    if (!context.active) return;
    if (g_visual_unit_update_profile_phase !=
        VisualUnitUpdateProfilePhase::original)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::unassigned, now);
}

void visual_unit_update_profile_finish_begin_at(
    VisualUnitUpdateProfileContext& context, std::int64_t now) noexcept {
    if (!context.active) return;
    if (g_visual_unit_update_profile_phase !=
        VisualUnitUpdateProfilePhase::unassigned)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::finish, now);
    ++g_outer_frame_timing.visual_unit_update_finish_calls;
}

void visual_unit_update_profile_finish_end_at(
    VisualUnitUpdateProfileContext& context, std::int64_t now) noexcept {
    if (!context.active) return;
    if (g_visual_unit_update_profile_phase !=
        VisualUnitUpdateProfilePhase::finish)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::unassigned, now);
}

void visual_unit_update_profile_leave_at(
    VisualUnitUpdateProfileContext& context, std::int64_t now) noexcept {
    if (!context.active) return;
    if (!outer_frame_timing_active() ||
        !g_outer_frame_timing.count_time_profile_active) {
        context = {};
        return;
    }
    if (g_visual_unit_update_profile_phase !=
        VisualUnitUpdateProfilePhase::unassigned)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(context.parent, now);
    native_tick_owned_pause_end(context.owned_pause);
    context = {};
}

void visual_unit_update_profile_enter(
    VisualUnitUpdateProfileContext& context) noexcept {
    if (!outer_frame_timing_active() ||
        !g_outer_frame_timing.count_time_profile_active) {
        context = {};
        return;
    }
    visual_unit_update_profile_enter_at(context, bridge_now());
}

void visual_unit_update_profile_original_begin(
    VisualUnitUpdateProfileContext& context) noexcept {
    if (context.active)
        visual_unit_update_profile_original_begin_at(context, bridge_now());
}

void visual_unit_update_profile_original_end(
    VisualUnitUpdateProfileContext& context) noexcept {
    if (context.active)
        visual_unit_update_profile_original_end_at(context, bridge_now());
}

std::int64_t visual_unit_update_profile_finish_begin(
    VisualUnitUpdateProfileContext& context) noexcept {
    if (!context.active) return 0;
    const auto now = bridge_now();
    visual_unit_update_profile_finish_begin_at(context, now);
    return now;
}

std::int64_t visual_unit_update_profile_finish_end(
    VisualUnitUpdateProfileContext& context) noexcept {
    if (!context.active) return 0;
    const auto now = bridge_now();
    visual_unit_update_profile_finish_end_at(context, now);
    return now;
}

void visual_unit_update_profile_leave(
    VisualUnitUpdateProfileContext& context) noexcept {
    if (context.active)
        visual_unit_update_profile_leave_at(context, bridge_now());
}

void outer_frame_count_time_profile_end(std::int64_t now) noexcept {
    if (!outer_frame_timing_active() ||
        !g_outer_frame_timing.count_time_profile_active)
        return;
    if (g_visual_unit_update_profile_phase !=
        VisualUnitUpdateProfilePhase::unassigned)
        g_outer_frame_timing.invalid = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::inactive, now);
    g_outer_frame_timing.count_time_profile_active = false;
}

void outer_frame_count_time_begin(std::int64_t now) noexcept {
    if (!outer_frame_timing_active()) return;
    if (now <= 0 || g_outer_frame_timing.count_time_begin != 0 ||
        g_outer_frame_timing.count_time_profile_active ||
        g_visual_unit_update_profile_phase !=
            VisualUnitUpdateProfilePhase::inactive)
        g_outer_frame_timing.invalid = true;
    g_outer_frame_timing.count_time_begin = now;
    g_outer_frame_timing.count_time_profile_active = true;
    visual_unit_update_profile_transition_at(
        VisualUnitUpdateProfilePhase::unassigned, now);
}

void outer_frame_interface_on_idle(
    std::int64_t begin, std::int64_t end) noexcept {
    if (!outer_frame_timing_active()) return;
    outer_frame_count_time_profile_end(begin);
    if (begin <= 0 || end < begin ||
        g_outer_frame_timing.count_time_begin <= 0 ||
        begin < g_outer_frame_timing.count_time_begin) {
        g_outer_frame_timing.invalid = true;
    } else {
        g_outer_frame_timing.count_time_ticks +=
            begin - g_outer_frame_timing.count_time_begin;
        g_outer_frame_timing.interface_on_idle_ticks += end - begin;
        ++g_outer_frame_timing.count_time_calls;
        ++g_outer_frame_timing.interface_on_idle_calls;
    }
    g_outer_frame_timing.count_time_begin = 0;
}

void outer_frame_message_handled(
    std::int64_t begin, std::int64_t end) noexcept {
    if (!outer_frame_timing_active()) return;
    if (begin <= 0 || end < begin) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    g_outer_frame_timing.message_handling_ticks += end - begin;
    ++g_outer_frame_timing.message_handler_calls;
}

void outer_frame_begin(std::uint64_t bridge_frame) noexcept {
    if (!outer_frame_timing_active()) return;
    if (!bridge_frame || g_outer_frame_timing.frame_begun)
        g_outer_frame_timing.invalid = true;
    g_outer_frame_timing.bridge_frame = bridge_frame;
    g_outer_frame_timing.frame_begun = true;
}

void outer_frame_end(std::uint64_t bridge_frame,
                     std::int64_t now) noexcept {
    if (!outer_frame_timing_active()) return;
    if (!g_outer_frame_timing.frame_begun ||
        g_outer_frame_timing.frame_ended ||
        bridge_frame != g_outer_frame_timing.bridge_frame || now <= 0)
        g_outer_frame_timing.invalid = true;
    g_outer_frame_timing.end_frame_return = now;
    g_outer_frame_timing.frame_ended = true;
}
