struct NativeTickOwnedTimingToken {
    NativeTickOwnedCallback kind = NativeTickOwnedCallback::count;
    NativeTickOwnedCallback parent = NativeTickOwnedCallback::count;
    std::uint32_t depth = 0;
    bool active = false;
};

NativeTickOwnedTimingToken native_tick_owned_begin(
    NativeTickOwnedCallback kind) noexcept {
    NativeTickOwnedTimingToken token{};
    if (!g_native_tick_original_profile_active || g_lifecycle_tick_depth != 1 ||
        g_outer_direct_timing_depth || g_native_tick_owned_pause_depth ||
        !outer_frame_timing_active() ||
        !g_outer_frame_timing.count_time_profile_active ||
        g_visual_unit_update_profile_phase != VisualUnitUpdateProfilePhase::unassigned)
        return token;
    const auto now = bridge_now();
    if (now <= 0 || g_native_tick_owned_depth == UINT32_MAX) {
        g_outer_frame_timing.invalid = true;
        return token;
    }
    token.kind = kind;
    token.parent = g_native_tick_owned_current;
    token.depth = ++g_native_tick_owned_depth;
    token.active = true;
    if (token.parent != NativeTickOwnedCallback::count) {
        if (g_native_tick_owned_begin <= 0 || now < g_native_tick_owned_begin)
            g_outer_frame_timing.invalid = true;
        else g_outer_frame_timing.native_tick_owned_callbacks[
            static_cast<std::size_t>(token.parent)].exclusive_ticks +=
                now-g_native_tick_owned_begin;
    }
    g_native_tick_owned_current = kind;
    g_native_tick_owned_begin = now;
    ++g_outer_frame_timing.native_tick_owned_callbacks[
        static_cast<std::size_t>(kind)].calls;
    return token;
}

void native_tick_owned_end(NativeTickOwnedTimingToken& token) noexcept {
    if (!token.active) return;
    const auto now = bridge_now();
    if (!g_native_tick_original_profile_active ||
        g_native_tick_owned_depth != token.depth ||
        g_native_tick_owned_pause_depth ||
        g_native_tick_owned_current != token.kind ||
        g_visual_unit_update_profile_phase != VisualUnitUpdateProfilePhase::unassigned ||
        now <= 0 || g_native_tick_owned_begin <= 0 || now < g_native_tick_owned_begin)
        g_outer_frame_timing.invalid = true;
    else g_outer_frame_timing.native_tick_owned_callbacks[
        static_cast<std::size_t>(token.kind)].exclusive_ticks +=
            now-g_native_tick_owned_begin;
    g_native_tick_owned_depth = token.depth-1;
    g_native_tick_owned_current = token.parent;
    g_native_tick_owned_begin = token.parent == NativeTickOwnedCallback::count ? 0 : now;
    token.active = false;
}

struct NativeTickOwnedTimingScope {
    NativeTickOwnedTimingToken token;
    explicit NativeTickOwnedTimingScope(NativeTickOwnedCallback kind) noexcept :
        token(native_tick_owned_begin(kind)) {}
    ~NativeTickOwnedTimingScope() { native_tick_owned_end(token); }
};

bool visual_event_recording() noexcept {
    return outer_frame_timing_active() &&
        g_outer_frame_timing.count_time_profile_active &&
        g_native_tick_original_profile_active && g_lifecycle_tick_depth == 1;
}

OuterFrameVisualEvent* reserve_visual_event(OuterFrameVisualEventKind kind) noexcept {
    if (!visual_event_recording()) return nullptr;
    const auto sequence = ++g_outer_frame_timing.visual_event_sequence;
    if (g_outer_frame_timing.visual_event_count == kOuterFrameVisualEventCapacity) {
        ++g_outer_frame_timing.visual_event_overflow;
        return nullptr;
    }
    auto& event = g_outer_frame_timing.visual_events[g_outer_frame_timing.visual_event_count++];
    event = {};
    event.sequence = sequence;
    event.kind = kind;
    event.phase = g_visual_unit_update_profile_phase == VisualUnitUpdateProfilePhase::original ? 1 :
        g_visual_unit_update_profile_phase == VisualUnitUpdateProfilePhase::finish ? 2 : 0;
    return &event;
}

void record_visual_resource_event(OuterFrameVisualEventKind kind,
    VisualResourceIncarnation resource, bool assembly_before,
    bool assembly_after, bool succeeded) noexcept {
    if (auto* event = reserve_visual_event(kind)) {
        event->signed_id = resource.signed_id;
        event->serial = resource.serial;
        event->assembly_before = assembly_before;
        event->assembly_after = assembly_after;
        event->succeeded = succeeded;
    }
}

NativeTickOwnedPauseToken native_tick_owned_pause_begin() noexcept {
    NativeTickOwnedPauseToken token{};
    if (!g_native_tick_original_profile_active ||
        (!g_native_tick_owned_pause_depth &&
            g_native_tick_owned_current == NativeTickOwnedCallback::count))
        return token;
    token.active = true;
    if (g_native_tick_owned_pause_depth++ == 0) {
        token.owner = g_native_tick_owned_current;
        const auto now = bridge_now();
        if (now <= 0 || g_native_tick_owned_begin <= 0 ||
            now < g_native_tick_owned_begin)
            g_outer_frame_timing.invalid = true;
        else g_outer_frame_timing.native_tick_owned_callbacks[
            static_cast<std::size_t>(token.owner)].exclusive_ticks +=
                now-g_native_tick_owned_begin;
        g_native_tick_owned_current = NativeTickOwnedCallback::count;
        g_native_tick_owned_begin = 0;
    }
    return token;
}

void native_tick_owned_pause_end(NativeTickOwnedPauseToken& token) noexcept {
    if (!token.active) return;
    if (!g_native_tick_owned_pause_depth) {
        g_outer_frame_timing.invalid = true;
    } else if (--g_native_tick_owned_pause_depth == 0) {
        if (g_native_tick_owned_current != NativeTickOwnedCallback::count)
            g_outer_frame_timing.invalid = true;
        g_native_tick_owned_current = token.owner;
        g_native_tick_owned_begin = bridge_now();
    }
    token.active = false;
}

struct NativeTickOwnedPauseScope {
    NativeTickOwnedPauseToken token = native_tick_owned_pause_begin();
    ~NativeTickOwnedPauseScope() { native_tick_owned_pause_end(token); }
};
