const std::uint8_t* game_image_base() noexcept {
    return reinterpret_cast<const std::uint8_t*>(GetModuleHandleW(nullptr));
}
// The game camera's anchor height for the close shadow band (#196). CCamera
// is the static object at 0x79B2A8 and its anchor point sits at +0xE0 (x, y, z;
// SetAnchorPoint 0040F5C0 stores the point and then takes its height from the
// terrain): the same object and fields the test harness reads, behind the
// same verified site group. NaN when those sites do not verify.
float game_camera_anchor_z() noexcept {
    if (!game_sites_ok(GameSiteGroup::harness)) return NAN;
    constexpr std::uintptr_t kCameraObjectRva = 0x0039b2a8, kCameraAnchorZ = 0xe0 + 8;
    const float z = *reinterpret_cast<const float*>(game_image_base() + kCameraObjectRva + kCameraAnchorZ);
    return std::isfinite(z) ? z : NAN;
}

std::size_t game_image_size() noexcept {
    static const std::size_t size = [] {
        const auto* base = game_image_base();
        if (!base) return std::size_t{0};
        const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE) return std::size_t{0};
        const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS32*>(base + dos->e_lfanew);
        return nt->Signature == IMAGE_NT_SIGNATURE ?
            static_cast<std::size_t>(nt->OptionalHeader.SizeOfImage) : std::size_t{0};
    }();
    return size;
}

bool game_image_contains(const void* address) noexcept {
    const auto* base = game_image_base();
    const auto* at = static_cast<const std::uint8_t*>(address);
    return base && at >= base && at < base + game_image_size();
}
#endif // !EID3D11_EMBEDDED

// A world draw completed through our hook (the ownership check point).
std::atomic<bool> g_ownership_world_seen{false};

// Observe-only detour entries (game.exe RVAs): each handler only reads the
// call (and renderer state) and continues it with the same arguments and
// result, and needs nothing from hooks nested inside the stock body (audit
// 2026-10-19). A raw replacement jump into another module at one of these is
// forwarded to like an addon chain instead of turning the feature off
// (Dejavu 2026-10-17 plugin.dll replaced 0050F1E0). Not listed: detours that
// modify the call, replace it, or rely on nested hooks or return addresses.
constexpr std::array<std::uint32_t, 47> kObserverEntryRvas{{
    0x1641f0, 0x1647e0, 0x164be0, 0x164e70,                     // lifecycle tick, add, remove, reset
    0x1164b0, 0x1167e0, 0x117700,                               // object plan figures, complection
    0x196030, 0x1927c0,                                         // retained parser, admission
    0x16afe0,                                                   // scene 3D draw bracket
    0x2c3c80,                                                   // terrain free
    0x235e60, 0x235e00, 0x291500, 0x1aa510,                     // HUD deactivate, destroy, managers
    0x275050, 0x1aa360, 0x275200, 0x275340, 0x274f40,           // resource add, close, destroy
    0x1f4990, 0x1f4f90, 0x1e29e0,                               // character pane init/fini, chat draw
    0x116080, 0x115f70, 0x1c67d0, 0x10ca50, 0x10cba0,           // visual publication observers
    0x1341a0, 0x11cca0, 0x268c50, 0x1352b0, 0x116650,
    0x117500, 0x11b630, 0x11c9f0, 0x116da0, 0x117110,
    0x291630, 0x18dcd0, 0x26e130, 0x18b750,                     // camp texture destroy, close diagnostics
    0x10e9f0, 0x10f1e0, 0x10f2d0, 0x10f5b0,                     // server object change writers
    0x293180}};                                                 // stock ComposeTexture (material layers)

#if !defined(EID3D11_EMBEDDED)
bool observer_entry_forwarded(const void* entry, const void* target, const wchar_t* module) noexcept {
    const auto* image = game_image_base();
    const auto* at = static_cast<const std::uint8_t*>(entry);
    if (!image || at < image) return false;
    const auto rva = static_cast<std::uint32_t>(at - image);
    const auto found = std::find(kObserverEntryRvas.begin(), kObserverEntryRvas.end(), rva);
    if (found == kObserverEntryRvas.end()) return false;
    static std::array<std::atomic<bool>, kObserverEntryRvas.size()> logged{};
    if (!logged[std::size_t(found - kObserverEntryRvas.begin())].exchange(true)) {
        char detail[160];
        std::snprintf(detail, sizeof(detail), "entry_rva=%08x owner=%ls target=%p forwarded",
                      static_cast<unsigned>(rva), module, target);
        append_bridge_event("observer_entry_chained", detail, true);
    }
    return true;
}
const bool g_observer_entry_check_registered = (set_observer_entry_check(&observer_entry_forwarded), true);
#endif

// Ownership of a game entry the bridge detours: stock bytes, or the addon's
// hook-framework chain (forward through its dispatcher, which stays owned by
// the addon and is never freed; uninstall restores the addon's entry bytes).
// Anything else is rejected and named once in the bridge log.
#if !defined(EID3D11_EMBEDDED)
EntryResolution resolve_hook_entry(const std::uint8_t* entry,
                                   const std::uint8_t* stock,
                                   std::size_t stock_bytes,
                                   std::size_t hook_bytes) noexcept {
    const EntryResolution result = resolve_entry_owner(
        entry, stock, stock_bytes, hook_bytes, &addon_module_contains);
    if (result.owner == EntryOwner::rejected) {
        static std::array<std::uintptr_t, 64> logged{};
        static std::size_t logged_count = 0;
        const auto key = reinterpret_cast<std::uintptr_t>(entry);
        if (std::find(logged.begin(), logged.begin() + logged_count, key) ==
            logged.begin() + logged_count) {
            if (logged_count < logged.size()) logged[logged_count++] = key;
            const auto* image = reinterpret_cast<const std::uint8_t*>(GetModuleHandleW(nullptr));
            char detail[96];
            std::snprintf(detail, sizeof(detail), "entry_rva=%08x reason=%s",
                          static_cast<unsigned>(entry - image), result.reason);
            append_bridge_event("entry_owner_rejected", detail, true);
            note_foreign_entry(entry, "install", result.reason);
        }
    }
    return result;
}
#endif // !EID3D11_EMBEDDED

// A fully replaced entry never calls its previous owner, so only stock bytes
// are accepted. An addon hook-framework chain there would be silently
// dropped by our jump; it stays installed and the feature is rejected
// visibly instead (any other foreign owner is named by resolve_hook_entry).
#if !defined(EID3D11_EMBEDDED)
bool replaced_entry_is_stock(std::uint8_t* entry, const std::uint8_t* stock,
                             std::size_t stock_bytes) noexcept {
    const auto owner = resolve_hook_entry(entry, stock, stock_bytes, 5);
    if (owner.owner == EntryOwner::framework_chain)
        note_foreign_entry(entry, "install", "addon_hook_on_fully_replaced_entry");
    return owner.owner == EntryOwner::stock;
}

bool hook_entry_usable(const std::uint8_t* entry, const std::uint8_t* stock,
                       std::size_t stock_bytes, std::size_t hook_bytes) noexcept {
    return resolve_hook_entry(entry, stock, stock_bytes, hook_bytes).owner !=
        EntryOwner::rejected;
}
#endif // !EID3D11_EMBEDDED

