void complete_owned_visual_diagnostic(bool completed) noexcept {
    const auto& frame=g_owned_visual_world_frame;
    auto& output=g_bridge_sample.owned_visual;
    output={};
    if (!g_bridge_sample.active || !bridge_profile_enabled() || !frame.diagnostic.profile_frame ||
        frame.diagnostic.profile_frame!=g_bridge_sample.frame) return;
    output=frame.diagnostic; output.completed=completed;
    output.world_serial=frame.serial; output.active=frame.active;
    output.shadow_ready=frame.shadow_ready; output.color_submitted=frame.color_submitted;
    output.considered=frame.considered; output.eligible=frame.eligible;
    output.submitted_parts=frame.submitted_parts;
    output.shadow_considered=frame.shadow_considered; output.shadow_eligible=frame.shadow_eligible;
    output.shadow_submitted=frame.shadow_submitted;
}
