std::size_t owned_visual_frame_index(const LifecycleIdentity& identity) noexcept {
    const auto& frame = g_owned_visual_world_frame;
    if(!frame.values)return 0;
    if (!frame.active) return frame.values->entities.size();
    const auto& entities = frame.values->entities;
    const auto found = std::lower_bound(entities.begin(),entities.end(),identity.id,
        [](const RetainedVisualSample& item,std::int32_t id) { return item.lifecycle.id < id; });
    if (found == entities.end() || found->lifecycle.id != identity.id ||
        found->lifecycle.generation != identity.generation ||
        found->lifecycle.positive_world_epoch != identity.positive_world_epoch)
        return entities.size();
    return static_cast<std::size_t>(found-entities.begin());
}

#if !defined(EID3D11_EMBEDDED)
std::uintptr_t active_wound_surface_interface(
    const std::uint8_t* const* render_state_manager_slot,
    const std::uint8_t* object) noexcept {
    if (!render_state_manager_slot || !object) return 0;
    __try {
        const auto* render_state_manager = *render_state_manager_slot;
        const auto* object_specific =
            *reinterpret_cast<const std::uint8_t* const*>(
                object + kObjectSpecificOffset);
        if (!render_state_manager || !object_specific ||
            *reinterpret_cast<const void* const*>(
                object_specific + kObjectSpecificOwnerOffset) != object)
            return 0;
        const auto* descriptor =
            *reinterpret_cast<const void* const*>(
                object_specific + kObjectWoundDescriptorOffset);
        const auto* active_descriptor =
            *reinterpret_cast<const void* const*>(
                render_state_manager +
                object_frame_contract().active_descriptor_offset);
        if (!descriptor || active_descriptor != descriptor) return 0;
        const auto* texture =
            *reinterpret_cast<const std::uint8_t* const*>(
                object_specific + kObjectWoundTextureOffset);
        const auto* wrapper = texture
            ? *reinterpret_cast<const std::uint8_t* const*>(
                  texture + kTextureSurfaceWrapperOffset)
            : nullptr;
        const auto* surface = wrapper
            ? *reinterpret_cast<const void* const*>(
                  wrapper + kSurfaceWrapperInterfaceOffset)
            : nullptr;
        return reinterpret_cast<std::uintptr_t>(surface);
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return 0;
    }
}
#endif // !EID3D11_EMBEDDED

HudAtlasProducerContext hud_atlas_producer_context(
    HudAtlasProducerKind kind, void* destination_texture, int atlas_width,
    int destination_x, int destination_y, int copy_width, int copy_height,
    DWORD expected_lock_flags) noexcept {
    HudAtlasProducerContext context{};
    const auto right = static_cast<std::int64_t>(destination_x) + copy_width;
    const auto bottom = static_cast<std::int64_t>(destination_y) + copy_height;
    if (!destination_texture || atlas_width <= 0 || destination_x < 0 ||
        destination_y < 0 || copy_width <= 0 || copy_height <= 0 ||
        right > (std::numeric_limits<LONG>::max)() ||
        bottom > (std::numeric_limits<LONG>::max)())
        return context;
    context.kind = kind;
    context.destination_texture = destination_texture;
    context.window.atlas_width = atlas_width;
    context.window.rect = {
        destination_x, destination_y, static_cast<LONG>(right),
        static_cast<LONG>(bottom)};
    context.window.expected_lock_flags = expected_lock_flags;
    return context;
}

#if !defined(EID3D11_EMBEDDED)
IDirectDrawSurface7* current_texture_surface(void* texture) noexcept {
    if (!texture) return nullptr;
    __try {
        const auto* bytes = static_cast<const std::uint8_t*>(texture);
        const auto* wrapper =
            *reinterpret_cast<const std::uint8_t* const*>(
                bytes + kTextureSurfaceWrapperOffset);
        return wrapper ? *reinterpret_cast<IDirectDrawSurface7* const*>(
                             wrapper + kSurfaceWrapperInterfaceOffset)
                       : nullptr;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

bool __stdcall hook_addon_hud_atlas_producer(
    void* destination_texture, const char* resource_name, int atlas_width,
    int source_width, int source_height, int copy_width, int copy_height,
    int destination_x, int destination_y, std::uintptr_t unused_x,
    std::uintptr_t unused_y) {
    const HudAtlasProducerContext previous = g_hud_atlas_producer;
    const bool previous_pending = g_addon_hud_atlas_lock_pending;
    g_hud_atlas_producer = hud_atlas_producer_context(
        HudAtlasProducerKind::addon, destination_texture, atlas_width,
        destination_x, destination_y, copy_width, copy_height, 0x821u);
    g_addon_hud_atlas_lock_pending = false;
    bool result = false;
    __try {
        result = g_addon_hud_atlas_producer(
            destination_texture, resource_name, atlas_width, source_width,
            source_height, copy_width, copy_height, destination_x,
            destination_y, unused_x, unused_y);
    } __finally {
        g_hud_atlas_producer = previous;
        g_addon_hud_atlas_lock_pending = previous_pending;
    }
    return result;
}
#endif // !EID3D11_EMBEDDED

