void repaint_hud_skill_icon(const char* resource_name, int source_width, int source_height,
                            int copy_width, int copy_height, int destination_x,
                            int destination_y, int source_x, int source_y) noexcept {
    // Same placement contract as the stock lane producer capture.
    const HudIconPlacement placement{
        256u, static_cast<std::uint32_t>(source_width),
        static_cast<std::uint32_t>(source_height),
        static_cast<std::uint32_t>(copy_width),
        static_cast<std::uint32_t>(copy_height),
        static_cast<std::uint32_t>(destination_x),
        static_cast<std::uint32_t>(destination_y),
        static_cast<std::uint32_t>(source_x),
        static_cast<std::uint32_t>(source_y), 0u};
    try {
        std::string canonical = resource_name;
        canonical += ".mmp";
        if (!g_hud_visuals.repaint_icon(HudVisualLane::skill, canonical.c_str(), placement))
            diagnose_hud_visual_once(3u, "skill_icon_repaint_unmatched");
    } catch (...) {
        diagnose_hud_visual_once(3u, "skill_icon_repaint_unmatched");
    }
}

#if !defined(EID3D11_EMBEDDED)
bool __fastcall hook_stock_hud_atlas_producer(
    void* self, void*, void* destination_texture, const char* resource_name,
    int source_width, int source_height, int copy_width, int copy_height,
    int destination_x, int destination_y, int source_x, int source_y) {
    // The addon repaints one published skill icon in place at run time (its
    // camp action between available and disabled art). Outside a lane rebuild
    // a paste into the active skill lane's atlas updates that cell's slot.
    const bool repaint = !g_hud_visuals.capturing_lane() && !g_hud_visual_capture_suspended &&
        self && resource_name && *resource_name && destination_texture &&
        hud_draw_receiver(self, HudVisualLane::skill) &&
        destination_texture == hud_lane_atlas(self) &&
        g_hud_visuals.claims_lane(HudVisualLane::skill) &&
        source_width > 0 && source_height > 0 && copy_width > 0 && copy_height > 0 &&
        destination_x >= 0 && destination_y >= 0 && source_x >= 0 && source_y >= 0;
    const HudAtlasProducerContext previous = g_hud_atlas_producer;
    const bool previous_pending = g_addon_hud_atlas_lock_pending;
    g_hud_atlas_producer = hud_atlas_producer_context(
        HudAtlasProducerKind::stock, destination_texture, 256,
        destination_x, destination_y, copy_width, copy_height, 0u);
    g_addon_hud_atlas_lock_pending = false;
    bool result = false;
    __try {
        result = g_stock_hud_atlas_producer(
            self, destination_texture, resource_name, source_width,
            source_height, copy_width, copy_height, destination_x,
            destination_y, source_x, source_y);
    } __finally {
        g_hud_atlas_producer = previous;
        g_addon_hud_atlas_lock_pending = previous_pending;
    }
    if (repaint && result) repaint_hud_skill_icon(resource_name, source_width, source_height,
        copy_width, copy_height, destination_x, destination_y, source_x, source_y);
    return result;
}

bool safe_copy_hud_resource(std::uint8_t* destination,
                            const std::uint8_t* source,
                            std::size_t bytes) noexcept {
    if (!destination || !source || !bytes) return false;
    __try {
        std::memcpy(destination, source, bytes);
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}
#endif // !EID3D11_EMBEDDED

std::size_t hud_lane_index(HudVisualLane lane) noexcept {
    const auto value = static_cast<std::uint8_t>(lane);
    return value >= static_cast<std::uint8_t>(HudVisualLane::weapon) &&
            value <= static_cast<std::uint8_t>(HudVisualLane::skill)
        ? static_cast<std::size_t>(value - 1u) : 4u;
}

void* hud_lane_atlas(void* receiver) noexcept;

#if !defined(EID3D11_EMBEDDED)
void* hud_lane_receiver(void* screen, HudVisualLane lane) noexcept {
    const auto index = hud_lane_index(lane);
    if (!screen || index >= kHudLaneMemberOffsets.size()) return nullptr;
    __try {
        return *reinterpret_cast<void**>(
            static_cast<std::uint8_t*>(screen) + kHudLaneMemberOffsets[index]);
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

bool hud_activation_lane_state(
    void* screen, std::array<std::uint32_t, 4>& counts) noexcept {
    counts = {};
    if (!screen) return false;
    for (std::size_t index = 0; index < kHudLaneMemberOffsets.size(); ++index) {
        void* receiver = hud_lane_receiver(
            screen, static_cast<HudVisualLane>(index + 1u));
        if (!receiver || !hud_lane_atlas(receiver)) return false;
        __try {
            const auto count = *reinterpret_cast<const std::int32_t*>(
                static_cast<const std::uint8_t*>(receiver) + 0x10cu);
            if (count < 0) return false;
            counts[index] = static_cast<std::uint32_t>(count);
        } __except(EXCEPTION_EXECUTE_HANDLER) {
            return false;
        }
    }
    return true;
}

bool hud_capture_receiver(void* receiver, HudVisualLane lane) noexcept {
    void* screen = g_hud_provisional_screen ? g_hud_provisional_screen :
                                               g_hud_active_screen;
    return receiver && hud_lane_receiver(screen, lane) == receiver;
}

bool hud_draw_receiver(void* receiver, HudVisualLane lane) noexcept {
    return receiver && g_hud_active_screen &&
        hud_lane_receiver(g_hud_active_screen, lane) == receiver;
}

void* hud_lane_carrier_at(void* receiver, std::uint32_t ordinal) noexcept {
    if (!receiver ||
        ordinal > static_cast<std::uint32_t>((std::numeric_limits<std::int32_t>::max)())) {
        return nullptr;
    }
    __try {
        const auto* bytes = static_cast<const std::uint8_t*>(receiver);
        const auto count = *reinterpret_cast<const std::int32_t*>(bytes + 0x10cu);
        auto* const* carriers = *reinterpret_cast<void* const* const*>(
            bytes + 0x108u);
        return count > 0 && ordinal < static_cast<std::uint32_t>(count) && carriers
            ? carriers[ordinal] : nullptr;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}

void* hud_manager_for_role(HudResourceRole role) noexcept {
    if (!g_hud_visual_game_image) return nullptr;
    void* manager = nullptr;
    __try {
        const std::uint32_t slot = role == HudResourceRole::texture ?
            resource_manager_contract().texture_slot : resource_manager_contract().figure_slot;
        manager = *reinterpret_cast<void**>(g_hud_visual_game_image + slot);
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
    return manager;
}

bool hud_manager_role_ready(HudResourceRole role) noexcept {
    void* manager = hud_manager_for_role(role);
    if (!manager || !g_hud_visual_game_image) return false;
    __try {
        const auto expected = g_hud_visual_game_image +
            (role == HudResourceRole::texture ? resource_manager_contract().texture_table :
                                                resource_manager_contract().figure_table);
        return *reinterpret_cast<void**>(manager) == expected;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool hud_manager_functions(HudResourceRole role, void* manager,
                           ResourceGetFn& get,
                           ResourceReleaseFn& release,
                           ResourceCloseAllFilesFn& close_all) noexcept {
    get = nullptr;
    release = nullptr;
    close_all = nullptr;
    if (!manager) return false;
    __try {
        auto** table = *reinterpret_cast<void***>(manager);
        if (!table) return false;
        get = reinterpret_cast<ResourceGetFn>(table[0x4c / sizeof(void*)]);
        if (role == HudResourceRole::figure)
            release = reinterpret_cast<ResourceReleaseFn>(
                table[0x50 / sizeof(void*)]);
        else
            close_all = reinterpret_cast<ResourceCloseAllFilesFn>(
                table[0x58 / sizeof(void*)]);
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
    return get && (role == HudResourceRole::figure ? release != nullptr :
                                                     close_all != nullptr);
}

bool resolve_hud_resource(void*, HudResourceRole role,
                          const char* canonical_name,
                          ResourceBlob& blob,
                          HudPublicationFailureStage& failure_stage,
                          ResourceFailureCode& failure_code) {
    blob = {};
    failure_stage = HudPublicationFailureStage::none;
    failure_code = ResourceFailureCode::none;
    if (!canonical_name || !*canonical_name) {
        failure_stage = HudPublicationFailureStage::resolver;
        failure_code = ResourceFailureCode::invalid_name;
        return false;
    }
    void* manager = hud_manager_for_role(role);
    ResourceGetFn get = nullptr;
    ResourceReleaseFn release = nullptr;
    ResourceCloseAllFilesFn close_all = nullptr;
    if (!hud_manager_functions(role, manager, get, release, close_all)) {
        failure_stage = HudPublicationFailureStage::resolver_unavailable;
        failure_code = ResourceFailureCode::not_found;
        return false;
    }

    DWORD size = 0;
    std::uint8_t* selected = get(manager, canonical_name, &size);
    if (!selected) {
        if (role == HudResourceRole::texture) close_all(manager);
        failure_stage = HudPublicationFailureStage::resolver;
        failure_code = ResourceFailureCode::not_found;
        return false;
    }
    bool copied = false;
    constexpr DWORD kMaximumHudMemberBytes = 64u * 1024u * 1024u;
    try {
        if (size != 0 && size <= kMaximumHudMemberBytes) {
            auto bytes = std::make_shared<std::vector<std::uint8_t>>(size);
            copied = safe_copy_hud_resource(bytes->data(), selected, size);
            if (copied) {
                blob.bytes = std::move(bytes);
            }
        } else {
            failure_stage = HudPublicationFailureStage::size;
            failure_code = ResourceFailureCode::archive_bounds;
        }
    } catch (...) {
        failure_stage = HudPublicationFailureStage::budget;
        if (role == HudResourceRole::texture) close_all(manager);
        else release(manager, selected);
        throw;
    }
    // Preserve each native manager's exact producer cleanup: texture resolution
    // closes all open member streams, while figure resolution releases the one
    // selected member. Cleanup also runs before propagating an allocation error.
    if (role == HudResourceRole::texture) close_all(manager);
    else if (!release(manager, selected)) copied = false;
    if (!copied) {
        blob = {};
        if (failure_stage == HudPublicationFailureStage::none) {
            failure_stage = HudPublicationFailureStage::copy;
            failure_code = ResourceFailureCode::file_read;
        }
    }
    return copied;
}

bool read_hud_overlay_variant(std::uint32_t& variant) noexcept {
    variant = 0;
    // The stock panels have only the base icon set (variant 0), as the stock
    // producer lane already assumes.
    if (g_hud_visual_native) return true;
    if (!g_hud_visual_addon_image || !g_addon.layout.hud_visual.variant) return false;
    __try {
        variant = *reinterpret_cast<const std::uint32_t*>(
            g_hud_visual_addon_image + g_addon.layout.hud_visual.variant) ? 1u : 0u;
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void* hud_lane_atlas(void* receiver) noexcept {
    if (!receiver) return nullptr;
    __try {
        auto** textures = *reinterpret_cast<void***>(
            static_cast<std::uint8_t*>(receiver) + 0xf8u);
        return textures ? textures[0] : nullptr;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
}
#endif // !EID3D11_EMBEDDED

void finish_hud_lane_after_call(bool armed, bool completed) noexcept;

void close_hud_auto_capture() noexcept {
    if (!g_hud_auto_capture) return;
    g_hud_auto_capture = false;
    g_hud_capture_lane_receiver = nullptr;
    finish_hud_lane_after_call(g_hud_visuals.capturing_lane_id() == HudVisualLane::skill, true);
}

// The first AddSkill of a rebuild (no skills yet) on the active, published
// skill lane, with no capture open, starts an automatic lane capture.
#if !defined(EID3D11_EMBEDDED)
void open_hud_auto_capture(void* self) noexcept {
    if (g_hud_auto_capture || g_hud_visuals.capturing_lane() || g_hud_visual_capture_suspended ||
        !hud_draw_receiver(self, HudVisualLane::skill) ||
        !g_hud_visuals.claims_lane(HudVisualLane::skill))
        return;
    int skills = -1;
    __try {
        skills = *reinterpret_cast<const int*>(static_cast<const std::uint8_t*>(self) + 0x14cu);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return;
    }
    if (skills != 0 || !g_hud_visuals.begin_lane(HudVisualLane::skill)) return;
    g_hud_auto_capture = true;
    g_hud_capture_lane_receiver = self;
}

bool begin_hud_lane_capture(void* self, HudVisualLane lane) noexcept {
    close_hud_auto_capture();
    if (g_hud_visual_capture_suspended) return false;
    if (g_hud_visuals.capturing_lane()) {
        // A nested same-lane rebuild can mutate the carrier array underneath the
        // outer invocation. Retire the outer transaction and run the nested call
        // normally; its lane remains visibly unowned rather than mis-paired.
        g_hud_visuals.invalidate_open_lane();
        return false;
    }
    return hud_capture_receiver(self, lane) && g_hud_visuals.begin_lane(lane);
}
#endif // !EID3D11_EMBEDDED

void finish_hud_lane_after_call(bool armed, bool completed) noexcept {
    const auto lane=g_hud_visuals.capturing_lane_id();
    if (armed) g_hud_visuals.finish_lane(completed);
    if(!armed || !completed)return;
    const auto panel=lane==HudVisualLane::weapon?HudPanel::weapons:lane==HudVisualLane::item?HudPanel::items:
        lane==HudVisualLane::spell?HudPanel::spells:HudPanel::abilities;
    if(!widescreen_hud_fade_enabled(panel))return;
    try {
        std::vector<std::uint64_t> values;
        for(unsigned ordinal=0;;++ordinal) {
            const auto* slot=g_hud_visuals.find(lane,ordinal);if(!slot)break;
            values.insert(values.end(),{slot->ordinal,slot->geometry_identity,slot->texture_identity,std::uint64_t(slot->visible)});
            const auto& p=slot->placement;
            values.insert(values.end(),{p.atlas_width,p.source_width,p.source_height,p.copy_width,p.copy_height,
                p.destination_x,p.destination_y,p.source_x,p.source_y,p.variant});
        }
        widescreen_hud_content_values(panel,values);
    } catch(const std::bad_alloc&) {widescreen_hud_activity(panel);}
}

void diagnose_hud_visual_once(std::uint32_t bit, const char* detail) noexcept {
    const LONG mask = static_cast<LONG>(1u << bit);
    if ((InterlockedOr(&g_hud_visual_diagnostic_mask, mask) & mask) == 0)
        append_bridge_event("hud_visual_omitted", detail,
                            EngineBridge::instance().sites_verified());
}

const char* hud_failure_lane_name(HudVisualLane lane) noexcept {
    switch (lane) {
    case HudVisualLane::weapon: return "weapon";
    case HudVisualLane::item: return "item";
    case HudVisualLane::spell: return "spell";
    case HudVisualLane::skill: return "skill";
    default: return "none";
    }
}

void diagnose_hud_publication_failure_once(
    const HudPublicationFailure& failure) noexcept {
    constexpr LONG mask = 1l << 1u;
    if ((InterlockedOr(&g_hud_visual_diagnostic_mask, mask) & mask) != 0)
        return;
    char escaped_member[kHudFailureMemberBytes * 2u + 1u]{};
    std::size_t output = 0;
    for (std::size_t index = 0;
         index < failure.logical_member_bytes &&
         output + 1u < sizeof(escaped_member); ++index) {
        const unsigned char value = static_cast<unsigned char>(
            failure.logical_member[index]);
        if (value == '\\' || value == '"') {
            if (output + 2u >= sizeof(escaped_member)) break;
            escaped_member[output++] = '\\';
            escaped_member[output++] = static_cast<char>(value);
        } else {
            escaped_member[output++] =
                value < 0x20u || value == 0x7fu ? '?' :
                                                    static_cast<char>(value);
        }
    }
    if (!output) escaped_member[0] = '-';
    char detail[512]{};
    std::snprintf(
        detail, sizeof(detail),
        "lane=%s ordinal=%u member=%s stage=%s code=%s",
        hud_failure_lane_name(failure.lane), failure.ordinal,
        escaped_member,
        hud_publication_failure_stage_name(failure.stage),
        resource_failure_code_name(failure.resource_failure));
    append_bridge_event("hud_visual_omitted", detail,
                        EngineBridge::instance().sites_verified());
}

