void __fastcall hook_hud_item_set_unit(void* self, void*, void* unit) {
    const bool armed = begin_hud_lane_capture(self, HudVisualLane::item);
    const bool previous_suspended = g_hud_visual_capture_suspended;
    void* const previous_receiver = g_hud_capture_lane_receiver;
    if (!armed) g_hud_visual_capture_suspended = true;
    else g_hud_capture_lane_receiver = self;
    bool completed = false;
    __try {
        g_hud_item_set_unit(self, unit);
        completed = true;
    } __finally {
        g_hud_visual_capture_suspended = previous_suspended;
        g_hud_capture_lane_receiver = previous_receiver;
        finish_hud_lane_after_call(armed, completed);
    }
}

