void __fastcall hook_hud_autocast_box(
    void* self, void*, const char* figure_name, const char* texture_name,
    int spell_index, int spell_count) {
    const HudAutocastContext previous = g_hud_autocast;
    const bool armed = !previous.active &&
        !g_hud_visual_capture_suspended &&
        g_hud_visuals.capturing_lane_id() == HudVisualLane::spell &&
        g_hud_capture_lane_receiver == self;
    g_hud_autocast = {};
    if (armed) {
        g_hud_autocast.receiver = self;
        g_hud_autocast.active = true;
        g_hud_autocast.visible = spell_index >= 0;
    }
    __try {
        g_hud_autocast_box(
            self, figure_name, texture_name, spell_index, spell_count);
    } __finally {
        g_hud_autocast = previous;
    }
}

