void report_object_suffix_cut_failure(const char* stage) noexcept {
    static volatile LONG reported = 0;
    if (InterlockedCompareExchange(&reported, 1, 0) == 0)
        append_bridge_event("object_suffix_cut_first_failure",
                            stage ? stage : "unknown", true);
}

