const char* semantic_name(SemanticKind kind) {
    switch (kind) {
    case SemanticKind::frame: return "frame";
    case SemanticKind::simple_geometry: return "simple_geometry";
    case SemanticKind::figure: return "figure";
    case SemanticKind::particles: return "particles";
    case SemanticKind::ui: return "ui";
    default: return "unknown";
    }
}

void bridge_profile_semantic_enter(SemanticKind kind, std::uint32_t outer_rva) {
    if (!bridge_profile_enabled() || !g_bridge_sample.active) return;
    const auto now = bridge_now();
    if (g_previous_semantic_exit > 0 && now >= g_previous_semantic_exit) {
        BridgeFrameSample::SemanticGap candidate{};
        candidate.ticks = now - g_previous_semantic_exit;
        candidate.from_kind = g_previous_semantic_kind;
        candidate.to_kind = semantic_name(kind);
        candidate.from_outer_rva = g_previous_semantic_outer_rva;
        candidate.to_outer_rva = outer_rva;
        auto& gaps = g_bridge_sample.largest_semantic_gaps;
        auto position = gaps.begin();
        while (position != gaps.end() && position->ticks >= candidate.ticks) ++position;
        if (position != gaps.end()) {
            std::move_backward(position, gaps.end() - 1, gaps.end());
            *position = candidate;
        }
    }
}

void bridge_profile_semantic_exit(SemanticKind kind, std::uint32_t outer_rva) {
    if (!bridge_profile_enabled()) return;
    g_previous_semantic_exit = bridge_now();
    g_previous_semantic_kind = semantic_name(kind);
    g_previous_semantic_outer_rva = outer_rva;
}

struct SemanticScope {
    SemanticContext previous{};
    SemanticKind kind = SemanticKind::unknown;
    std::uint32_t outer_rva = 0;
    SemanticScope(SemanticKind kind, const void* caller, const void* outer_caller = nullptr)
        : previous(g_semantic) {
        this->kind = kind;
        g_semantic.kind = kind;
        g_semantic.caller_rva = EngineBridge::instance().image_rva(caller);
        outer_rva = EngineBridge::instance().image_rva(outer_caller);
        bridge_profile_semantic_enter(kind, outer_rva);
    }
    ~SemanticScope() {
        bridge_profile_semantic_exit(kind, outer_rva);
        g_semantic = previous;
    }
};

void attribute_named_phase_ticks(std::int64_t ticks) {
    if (!g_bridge_sample.active || ticks <= 0) return;
    if (g_world_draw_depth) g_bridge_sample.world_named_ticks += ticks;
    if (g_scene_3d_depth) g_bridge_sample.scene_3d_named_ticks += ticks;
}

