#if !defined(EID3D11_EMBEDDED)
bool lifecycle_read_signed_id(const void* object, std::int32_t& id) noexcept {
    if (!object) return false;
    __try {
        id = *reinterpret_cast<const std::int32_t*>(
            static_cast<const std::uint8_t*>(object) + 0x0c);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool lifecycle_read_draw_signed_id(const void* drawable, std::int32_t& id) noexcept {
    if (!drawable) return false;
    __try {
        const auto* object = *reinterpret_cast<const std::uint8_t* const*>(
            static_cast<const std::uint8_t*>(drawable) + 0x1c);
        if (!object) return false;
        id = *reinterpret_cast<const std::int32_t*>(object + 0x0c);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool lifecycle_lookup_signed_id(void* self, std::int32_t id,
                                bool& present) noexcept {
    if (!self) return false;
    __try {
        if (running_game_sites().report.engine == GameEngine::lia) {
            // Native Add4d71ff scans the circular list at world+B8, using
            // node+8's signed object ID at +C. Borrow only during this call.
            const auto* sentinel=*reinterpret_cast<const std::uint8_t* const*>(
                static_cast<const std::uint8_t*>(self)+0xb8);
            if (!sentinel) return false;
            auto* node=*reinterpret_cast<const std::uint8_t* const*>(sentinel);
            present=false;
            for (;node!=sentinel;node=*reinterpret_cast<const std::uint8_t* const*>(node)) {
                const auto* object=*reinterpret_cast<const std::uint8_t* const*>(node+8);
                if (*reinterpret_cast<const std::int32_t*>(object+0x0c)==id) {
                    present=true;
                    break;
                }
            }
        } else {
            if (!g_lifecycle_has_object) return false;
            present = g_lifecycle_has_object(self, id) != FALSE;
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}
#endif // !EID3D11_EMBEDDED

void fail_lifecycle_contract() noexcept {
    g_lifecycle_draw_oracle.store(false, std::memory_order_release);
    g_lifecycle_observing.store(false, std::memory_order_release);
    g_object_render_plans.clear();
    g_resolved_figure_geometry.clear();
    lifecycle_observer().fail_closed(LifecycleValidation::contract_fault);
}

void lifecycle_note_mutation_nesting() noexcept {
    if (!g_lifecycle_observing.load(std::memory_order_acquire)) return;
    if (g_lifecycle_tick_depth != 0)
        lifecycle_observer().record_tick_nested_mutation();
    if (g_lifecycle_mutation_depth != 0)
        lifecycle_observer().record_mutation_reentrant_event();
}

