void reject_unscoped_visual_appearance(void* object) noexcept {
    // Keep failure propagation to an enclosing real mutation even when this
    // already-loaded call needed no artificial appearance scope.
    VisualAppearanceChanges changes;
    publish_visual_appearance_changes(object, changes, false);
}

BOOL __fastcall hook_visual_final_data(void* self, void*) {
    std::uint8_t flags = 0;
    // Verified 51751B -> 517535: bit 80 at +8 returns TRUE immediately.
    // A failed read is not proof of that branch. Nested semantic writers keep
    // their own scopes and can still merge into an existing outer mutation.
    const bool already_loaded = g_visual_publication_active &&
        visual_read(self, 8, flags) && (flags & 0x80u) != 0;
    auto* scope = already_loaded ? nullptr : begin_visual_appearance(self, true, false,
        OuterFrameAppearanceCallback::final_data);
    if (scope) scope->changes.textures = true;
    BOOL result = FALSE;
    // Observe an original promotion if the game needs it for its own work.
    // No owned consumer invokes this function to make geometry available.
    const bool traced = g_scene_3d_depth && startup_begin(StartupStage::appearance_native);
    __try { result = g_visual_final_data(self); }
    __finally {
        if (AbnormalTermination() || !result) fail_visual_appearance(scope, "final_data.original_failed");
        startup_end(StartupStage::appearance_native, traced,
            AbnormalTermination() ? "unwind" : result ? "true" : "false");
        const bool completed = !AbnormalTermination() && result != FALSE;
        finish_visual_appearance(scope, completed);
        if (already_loaded && !completed) reject_unscoped_visual_appearance(self);
    }
    return result;
}

BOOL __fastcall hook_visual_load_textures(void* self, void*, const char* primary, const char* secondary) {
    void* object = nullptr;
    visual_read(self,0x1c,object);
    auto* scope = begin_visual_appearance(object, false, false,
        OuterFrameAppearanceCallback::load_textures);
    if (scope) {
        scope->changes.textures = true;
        scope->changes.completed_textures = true;
    }
    BOOL result = FALSE;
    __try { result = g_visual_load_textures(self, primary, secondary); }
    __finally {
        if (AbnormalTermination() || !result) fail_visual_appearance(scope, "textures.original_failed"); finish_visual_appearance(scope, !AbnormalTermination() && result != FALSE); }
    return result;
}

BOOL invoke_visual_refresh_textures(void* self, VisualCreateFn original) {
    void* object = nullptr;
    std::uint32_t type = 0;
    // Both verified native entries return without changing non-heroes.
    if (!visual_read(self,0x1c,object) || !visual_read(object,0x10,type) || type != 50)
        return original(self);
    auto* scope = begin_visual_appearance(object, false, false,
        OuterFrameAppearanceCallback::load_textures);
    if (scope) {
        scope->changes.textures = true;
        scope->changes.completed_textures = true;
    }
    BOOL result = FALSE;
    __try { result = original(self); }
    __finally {
        if (AbnormalTermination() || !result) fail_visual_appearance(scope, "texture_refresh.original_failed");
        finish_visual_appearance(scope, !AbnormalTermination() && result != FALSE);
    }
    return result;
}

