void report_retained_static_failure(const char* stage) noexcept {
    static volatile LONG reported = 0;
    if (InterlockedCompareExchange(&reported, 1, 0) == 0)
        append_bridge_event("retained_static_scene_first_failure",
                            stage ? stage : "unknown", true);
}

