BOOL __fastcall hook_begin_frame(void* self, void*) {
    const auto caller = _ReturnAddress();
    SemanticScope scope(SemanticKind::frame, caller);
    // Supported DrawFrame entry: 45807D E8 BE BE 0A 00 -> 503F40.
    // Finish queued output under its original UI epoch, then restore owned
    // world targets before the engine clears them. Saves can draw again
    // without an intervening Present; a nested D3D scene is not this boundary.
    frame_acct::set_root(frame_acct::game_draw);
    // LiA: patch_slots owns its direct outer begin call, verified to target
    // the same begin-frame entry; it is the same per-frame boundary.
    const bool outer_begin =
        (g_engine_frame_begin_image &&
         caller == g_engine_frame_begin_image + kOuterBeginFrameCallRva + 5) ||
        (g_visual_game_image && running_game_sites().report.engine == GameEngine::lia &&
         caller == g_visual_game_image + renderer_boundary_contract().begin_call_rva + 5);
    if (outer_begin) {
        bool sink_ok = false;
        {
            const frame_acct::Scope sink_scope(frame_acct::ours_frame_begin);
            sink_ok = g_engine_frame_begin_sink &&
                g_engine_frame_begin_sink(g_engine_frame_begin_context);
        }
        if (!sink_ok) {
            static bool reported = false;
            if (!reported) {
                reported = true;
                bridge_report_event("owned_frame_begin_failed",
                    "Active device could not finish queued output and restore world targets; frame omitted before native clear.");
            }
            return FALSE;
        }
        ++g_preview_frame_serial;
    }
    // Coalesced unit appearances a frame without the world seam (camp and
    // other screens) did not publish go out now, at the frame boundary.
    publish_pending_unit_appearances_without_seam();
    const bool profile_was_active = g_bridge_sample.active;
    bridge_profile_begin_frame();
    outer_frame_begin(!profile_was_active && g_bridge_sample.active
                          ? g_bridge_sample.frame : 0);
    return g_begin_frame ? g_begin_frame(self) : FALSE;
}

BOOL __fastcall hook_end_frame(void* self, void*) {
    SemanticScope scope(SemanticKind::frame, _ReturnAddress());
    const std::uint64_t expected_profile_frame =
        g_bridge_sample.active ? g_bridge_sample.frame : 0;
    BOOL result = FALSE;
    {
        const frame_acct::Scope end_scope(frame_acct::game_end_frame);
        result = g_end_frame ? g_end_frame(self) : FALSE;
    }
    frame_acct::set_root(frame_acct::game_loop);
    bridge_profile_end_frame();
    const auto* published_profile = bridge_latest_profile();
    const std::uint64_t completed_profile_frame =
        result != FALSE && expected_profile_frame != 0 &&
            !g_bridge_sample.active && published_profile &&
            published_profile->frame == expected_profile_frame
        ? expected_profile_frame
        : 0;
    outer_frame_end(completed_profile_frame, bridge_now());
    return result;
}

BOOL __fastcall hook_simple_geometry(void* self, void*, void* vertices, int vertex_count,
                                     WORD* indices, int index_count) {
    SemanticScope scope(SemanticKind::simple_geometry, _ReturnAddress());
    const auto begin = bridge_profile_enabled() ? bridge_now() : 0;
    const BOOL result = g_simple_geometry ? g_simple_geometry(self, vertices, vertex_count, indices, index_count) : FALSE;
    if (begin && g_bridge_sample.active) {
        const auto elapsed = bridge_now() - begin;
        g_bridge_sample.simple_ticks += elapsed;
        attribute_named_phase_ticks(elapsed);
        ++g_bridge_sample.simple_calls;
        g_bridge_sample.simple_vertices += std::max(0, vertex_count);
        g_bridge_sample.simple_indices += std::max(0, index_count);
        const auto caller_rva = EngineBridge::instance().image_rva(_ReturnAddress());
        auto caller = std::find_if(g_bridge_sample.simple_callers.begin(),
                                   g_bridge_sample.simple_callers.end(),
                                   [&](const auto& item) { return item.rva == caller_rva; });
        if (caller == g_bridge_sample.simple_callers.end())
            caller = std::find_if(g_bridge_sample.simple_callers.begin(),
                                  g_bridge_sample.simple_callers.end(),
                                  [](const auto& item) { return item.rva == 0; });
        if (caller != g_bridge_sample.simple_callers.end()) {
            caller->rva = caller_rva;
            ++caller->calls;
            caller->vertices += std::max(0, vertex_count);
            caller->indices += std::max(0, index_count);
        }
    }
    return result;
}

// The magenta diagnostic of a portrait the owned path could not draw: the
// face figure's own default-colour state for the one call, restored after.
bool set_portrait_diagnostic_colour(void* figure, std::uint32_t& flags, std::uint32_t& diffuse) noexcept {
    __try {
        auto* bytes = static_cast<std::uint8_t*>(figure);
        flags = *reinterpret_cast<std::uint32_t*>(bytes + 0x08);
        diffuse = *reinterpret_cast<std::uint32_t*>(bytes + kFigureDefaultDiffuseOffset);
        *reinterpret_cast<std::uint32_t*>(bytes + 0x08) = flags | kFigureUseDefaultColors;
        *reinterpret_cast<std::uint32_t*>(bytes + kFigureDefaultDiffuseOffset) = 0xffff00ffu;
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER) { return false; }
}
void restore_portrait_diagnostic_colour(void* figure, std::uint32_t flags, std::uint32_t diffuse) noexcept {
    __try {
        auto* bytes = static_cast<std::uint8_t*>(figure);
        *reinterpret_cast<std::uint32_t*>(bytes + 0x08) = flags;
        *reinterpret_cast<std::uint32_t*>(bytes + kFigureDefaultDiffuseOffset) = diffuse;
    } __except(EXCEPTION_EXECUTE_HANDLER) {}
}
BOOL hook_figure_placed_body(void* self, void* figure, const void* rotation,
                             const void* position, void* material, BYTE fog, void* rect,
                             const void* return_address, const std::uintptr_t* return_slot);

BOOL __fastcall hook_figure_placed(void* self, void*, void* figure, const void* rotation,
                                   const void* position, void* material, BYTE fog, void* rect) {
    if (g_portrait_face_active && figure == g_portrait_carrier && !g_portrait_diagnostic) {
        // Owned portrait: the member's real head replaces the baked face. A
        // failure draws the face figure magenta (logged), never the baked face.
        const char* reason = rect ? "extents_requested" : nullptr;
        if (!rect && submit_owned_portrait(self, figure, material, fog, g_portrait_face, reason)) return TRUE;
        report_owned_portrait_failure(reason ? reason : "unknown");
        std::uint32_t flags = 0, diffuse = 0;
        const bool coloured = set_portrait_diagnostic_colour(figure, flags, diffuse);
        g_portrait_diagnostic = true;
        const BOOL result = hook_figure_placed_body(self, figure, rotation, position, material, fog, rect,
            _ReturnAddress(), reinterpret_cast<const std::uintptr_t*>(_AddressOfReturnAddress()));
        g_portrait_diagnostic = false;
        if (coloured) restore_portrait_diagnostic_colour(figure, flags, diffuse);
        return result;
    }
    return hook_figure_placed_body(self, figure, rotation, position, material, fog, rect,
        _ReturnAddress(), reinterpret_cast<const std::uintptr_t*>(_AddressOfReturnAddress()));
}

BOOL hook_figure_placed_body(void* self, void* figure, const void* rotation,
                             const void* position, void* material, BYTE fog, void* rect,
                             const void* return_address, const std::uintptr_t* return_slot) {
    if(g_map_preview_draw.section>=0 && !g_map_preview_draw.consumed &&
       g_map_preview_draw.carrier==figure &&
       g_map_preview_image && return_address==g_map_preview_image+0x1e6f35 &&
       submit_map_preview_placed(self,figure)) {
        g_map_preview_draw.consumed=true;
        // Native CI3DFigure::Draw must execute its two matrix-stack pops.
        return TRUE;
    }
    // The verified placed-figure wrapper at RVA 0x001e5d90 has a fixed frame:
    // its caller's return address is 0x88 bytes above this table-call return.
    // Read only that fail-closed stack slot; this replaces unreliable x86 stack
    // unwinding and is active only in the opt-in profiler build path.
    const void* outer_caller = nullptr;
    if (bridge_profile_enabled() &&
        running_game_sites().report.engine == GameEngine::base) {
        // return_slot: the hook frame's own return-address slot (passed in).
        outer_caller = reinterpret_cast<const void*>(return_slot[0x88 / sizeof(std::uintptr_t)]);
    }
    SemanticScope scope(SemanticKind::figure, return_address, outer_caller);
    const frame_acct::Part accounted_outer = frame_acct::current();
    const frame_acct::Scope accounted(frame_acct::ours_figure_hooks);
    const auto begin = bridge_profile_enabled() ? bridge_now() : 0;
    if (g_hud_draw.claimed && g_hud_draw.carrier_active &&
        !g_hud_draw.placed_consumed &&
        g_hud_draw.lane != HudVisualLane::none && g_hud_draw.receiver &&
        figure == g_hud_draw.current_carrier) {
        g_hud_draw.placed_consumed = true;
        const std::uint32_t ordinal = g_hud_draw.current_ordinal;
        const bool current_receiver =
            hud_draw_receiver(g_hud_draw.receiver, g_hud_draw.lane);
        const bool current = g_hud_visuals.owns_active_screen() &&
            g_hud_visuals.active_screen_generation() ==
                g_hud_draw.screen_generation &&
            current_receiver &&
            g_hud_visuals.claims_lane(g_hud_draw.lane);
        const HudPublishedVisual* published = current ?
            g_hud_visuals.find(g_hud_draw.lane, ordinal) : nullptr;
        const BOOL owned_result = published
            ? submit_hud_visual(self, figure, material, fog, rect, *published)
            : FALSE;
        if (!published) {
            diagnose_hud_publication_failure_once(
                g_hud_visuals.classify_missing(
                    g_hud_draw.lane, ordinal,
                    g_hud_draw.screen_generation, current_receiver));
        } else if (!owned_result) {
            diagnose_hud_visual_once(2u,
                "owned_hud_submission_failed");
        }
        if (begin && g_bridge_sample.active) {
            g_bridge_sample.figure_placed_ticks += bridge_now() - begin;
            ++g_bridge_sample.figure_placed_calls;
        }
        // This exact HUD call is owned even when its descriptor is unavailable
        // or submission fails.  Returning FALSE would route the verified
        // CI3DFigure::Draw caller around its two matrix-stack pops; keep the
        // omission visible and diagnosed, but report the call as processed.
        return TRUE;
    }
    const NativeFigureContext previous_context = g_native_figure;
    const std::uint32_t previous_lower_calls = g_native_lower_calls;
    g_native_lower_calls = 0;
    NativeFigureContext owned_context{};
    std::int32_t original_morph_count = 0;
    FigureFallbackReason fallback_reason = build_native_placed_context(figure, owned_context);
    bool owns_figure = fallback_reason == FigureFallbackReason::none;
    if (owns_figure && !suppress_cpu_morph(figure, original_morph_count)) {
        owns_figure = false;
        fallback_reason = FigureFallbackReason::state_write;
    }
    if (owns_figure) {
        g_native_figure = owned_context;
    }
    BOOL result = FALSE;
    {
        const frame_acct::Scope original(accounted_outer);
        result = g_figure_placed ? g_figure_placed(self, figure, rotation, position, material, fog, rect) : FALSE;
    }
    const std::uint32_t lower_calls = g_native_lower_calls;
    if (owns_figure) {
        const bool submitted = g_native_figure.submitted;
        restore_cpu_morph(figure, original_morph_count);
        if (g_bridge_sample.active) {
            ++g_bridge_sample.figure_gpu_owned_calls;
            g_bridge_sample.figure_gpu_morph_vertices += owned_context.morph_count;
            if (!submitted && lower_calls)
                ++g_bridge_sample.figure_gpu_submit_failures;
            else if (!submitted)
                ++g_bridge_sample.figure_gpu_culled_calls;
        }
    } else if (g_bridge_sample.active) {
        ++g_bridge_sample.figure_cpu_fallback_calls;
        ++g_bridge_sample.figure_fallback_reasons[static_cast<std::size_t>(fallback_reason)];
    }
    g_native_figure = previous_context;
    g_native_lower_calls = previous_lower_calls;
    if (begin && g_bridge_sample.active) {
        const auto elapsed = bridge_now() - begin;
        g_bridge_sample.figure_placed_ticks += elapsed;
        attribute_named_phase_ticks(elapsed);
        ++g_bridge_sample.figure_placed_calls;
    }
    return result;
}

BOOL __fastcall hook_figure_lights(void* self, void*, void* figure, void* lights,
                                   void* material, BYTE fog, void* rect, void* texture0,
                                   void* texture1) {
    SemanticScope scope(SemanticKind::figure, _ReturnAddress());
    const frame_acct::Part accounted_outer = frame_acct::current();
    const frame_acct::Scope accounted(frame_acct::ours_figure_hooks);
    const auto begin = bridge_profile_enabled() ? bridge_now() : 0;
    const NativeFigureContext previous_context = g_native_figure;
    const std::uint32_t previous_lower_calls = g_native_lower_calls;
    g_native_lower_calls = 0;
    NativeFigureContext owned_context{};
    std::uint32_t original_flags = 0;
    std::int32_t original_morph_count = 0;
    FigureFallbackReason fallback_reason =
        build_native_figure_context(
            self, figure, material, owned_context);
    bool owns_figure = fallback_reason == FigureFallbackReason::none;
    if (owns_figure && g_bridge_sample.active) {
        const float alpha = owned_context.lighting.material_alpha;
        if (alpha <= (0.5f / 255.0f)) ++g_bridge_sample.figure_alpha_zero_calls;
        else if (alpha >= (254.5f / 255.0f)) ++g_bridge_sample.figure_alpha_opaque_calls;
        else ++g_bridge_sample.figure_alpha_partial_calls;
        if (owned_context.morph_count) ++g_bridge_sample.figure_morphed_calls;
        if (texture0) ++g_bridge_sample.figure_texture0_calls;
        if (texture1) ++g_bridge_sample.figure_texture1_calls;
        if (texture0 && texture1) ++g_bridge_sample.figure_multitexture_calls;
    }
    BOOL result = FALSE;
    bool direct_owned = false;
    bool lower_owned = false;
    bool owned_submitted = false;
    bool original_called = false;
    int direct_render_result = 0;
    FigureExtentContractViolation contract_violation =
        FigureExtentContractViolation::none;
    FigureExtentRecord extent_record{};
    // The supported object draw publishes the primary wound descriptor on its
    // separate render-state manager immediately before this call and clears it
    // for the secondary set. Carry that one borrowed surface with the direct
    // GPU packet; the high texture arguments do not contain this state.
    if (owns_figure && !texture1) {
        extent_record = inspect_figure_extent_record(figure);
        if (extent_record.violation != FigureExtentContractViolation::none)
            fail_figure_extent_contract(extent_record.violation);
        direct_owned = set_owned_figure_state(
            figure, owned_context.uses_default_colors,
            original_flags, original_morph_count);
        if (direct_owned) {
            g_native_figure = owned_context;
            direct_owned = submit_resolved_figure_geometry(
                self, figure, material, fog, rect, extent_record,
                owned_context, direct_render_result, contract_violation);
            if (contract_violation != FigureExtentContractViolation::none)
                fail_figure_extent_contract(contract_violation);
            if (!direct_owned) {
                direct_owned = render_owned_figure_geometry(
                    self, figure, material, rect, extent_record,
                    owned_context, direct_render_result, contract_violation);
                if (contract_violation != FigureExtentContractViolation::none)
                    fail_figure_extent_contract(contract_violation);
            }
            owned_submitted = g_native_figure.submitted;
            restore_owned_figure_state(figure, original_flags, original_morph_count);
        }
        if (direct_owned && owned_submitted) {
            result = direct_render_result != 0;
        } else {
            direct_owned = false;
            owns_figure = false;
            fallback_reason = FigureFallbackReason::direct_submit;
            if (g_bridge_sample.active) ++g_bridge_sample.figure_gpu_submit_failures;
            g_native_figure = previous_context;
            {
                const frame_acct::Scope original(accounted_outer);
                result = g_figure_lights
                    ? g_figure_lights(self, figure, lights, material, fog, rect,
                                      texture0, texture1)
                    : FALSE;
            }
            original_called = true;
        }
    } else if (owns_figure) {
        lower_owned = set_owned_figure_state(
            figure, owned_context.uses_default_colors,
            original_flags, original_morph_count);
        if (lower_owned) {
            g_native_figure = owned_context;
        } else {
            owns_figure = false;
            fallback_reason = FigureFallbackReason::state_write;
        }
    }
    if (!direct_owned && !original_called) {
        const frame_acct::Scope original(accounted_outer);
        result = g_figure_lights
            ? g_figure_lights(self, figure, lights, material, fog, rect, texture0, texture1)
            : FALSE;
    }
    const std::uint32_t lower_calls = g_native_lower_calls;
    if (lower_owned) {
        const bool submitted = g_native_figure.submitted;
        restore_owned_figure_state(figure, original_flags, original_morph_count);
        if (g_bridge_sample.active) {
            ++g_bridge_sample.figure_gpu_owned_calls;
            g_bridge_sample.figure_gpu_morph_vertices += owned_context.morph_count;
            if (!submitted && lower_calls) {
                ++g_bridge_sample.figure_gpu_submit_failures;
                if (texture0 && texture1)
                    ++g_bridge_sample.figure_multitexture_submit_failures;
                else
                    ++g_bridge_sample.figure_single_submit_failures;
            } else if (!submitted) ++g_bridge_sample.figure_gpu_culled_calls;
        }
    } else if (direct_owned) {
        if (g_bridge_sample.active) {
            ++g_bridge_sample.figure_gpu_owned_calls;
            g_bridge_sample.figure_gpu_morph_vertices += owned_context.morph_count;
            if (direct_render_result == 2) ++g_bridge_sample.figure_gpu_culled_calls;
        }
    } else if (g_bridge_sample.active) {
        ++g_bridge_sample.figure_cpu_fallback_calls;
        ++g_bridge_sample.figure_fallback_reasons[static_cast<std::size_t>(fallback_reason)];
    }
    const bool accepted = direct_owned || lower_owned;
    g_native_figure = previous_context;
    g_native_lower_calls = previous_lower_calls;
    if (begin && g_bridge_sample.active) {
        const auto elapsed = bridge_now() - begin;
        g_bridge_sample.figure_lit_ticks += elapsed;
        if (accepted && owned_context.morph_count) {
            g_bridge_sample.figure_lit_morphed_ticks += elapsed;
            ++g_bridge_sample.figure_lit_morphed_calls;
        } else {
            g_bridge_sample.figure_lit_rigid_ticks += elapsed;
            ++g_bridge_sample.figure_lit_rigid_calls;
        }
        attribute_named_phase_ticks(elapsed);
        ++g_bridge_sample.figure_lit_calls;
    }
    return result;
}

bool extract_native_transform(void* renderer, std::array<float, 16>& transform,
                              std::uint32_t& default_diffuse) {
    if (!renderer) return false;
    __try {
        const auto* renderer_bytes = static_cast<const std::uint8_t*>(renderer);
        const auto* geometry = *reinterpret_cast<const std::uint8_t* const*>(renderer_bytes + 0xac);
        if (!geometry) return false;
        const auto* matrices = *reinterpret_cast<const float* const*>(geometry + 0x24);
        const std::uint32_t count = *reinterpret_cast<const std::uint32_t*>(geometry + 0x28);
        if (!matrices || count == 0 || count > 16) return false;
        std::memcpy(transform.data(), matrices + (count - 1u) * 16u,
                    transform.size() * sizeof(float));
        default_diffuse = *reinterpret_cast<const std::uint32_t*>(renderer_bytes + direct_renderer_layout().diffuse);
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool publish_native_screen_extents(void* renderer, const RECT& extents) {
    if (!renderer) return false;
    __try {
        std::memcpy(static_cast<std::uint8_t*>(renderer) +
                        direct_renderer_layout().screen_extents,
                    &extents, sizeof(extents));
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}


bool extract_terrain_transform(void* renderer, std::array<float, 16>& transform) {
    if (!renderer) return false;
    __try {
        const auto* processor = *reinterpret_cast<const std::uint8_t* const*>(
            static_cast<const std::uint8_t*>(renderer) + 0x08);
        const auto* matrices = processor
            ? *reinterpret_cast<const float* const*>(processor + 0x24) : nullptr;
        const std::uint32_t count = processor
            ? *reinterpret_cast<const std::uint32_t*>(processor + 0x28) : 0;
        if (!matrices || count == 0 || count > 16) return false;
        std::memcpy(transform.data(), matrices + (count - 1u) * 16u,
                    transform.size() * sizeof(float));
        return finite_vector(transform.data(), transform.size());
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}
