bool sha256_file(const char* path, std::array<std::uint8_t, 32>& digest) {
    BCRYPT_ALG_HANDLE algorithm = nullptr;
    BCRYPT_HASH_HANDLE hash = nullptr;
    DWORD object_size = 0;
    DWORD result_size = 0;
    std::vector<std::uint8_t> object;
    HANDLE file = INVALID_HANDLE_VALUE;
    bool ok = false;
    do {
        if (BCryptOpenAlgorithmProvider(&algorithm, BCRYPT_SHA256_ALGORITHM, nullptr, 0) < 0) break;
        if (BCryptGetProperty(algorithm, BCRYPT_OBJECT_LENGTH,
                              reinterpret_cast<PUCHAR>(&object_size), sizeof(object_size),
                              &result_size, 0) < 0) break;
        object.resize(object_size);
        if (BCryptCreateHash(algorithm, &hash, object.data(), object_size, nullptr, 0, 0) < 0) break;
        file = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                           nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL | FILE_FLAG_SEQUENTIAL_SCAN, nullptr);
        if (file == INVALID_HANDLE_VALUE) break;
        std::array<std::uint8_t, 1 << 16> buffer{};
        for (;;) {
            DWORD read = 0;
            if (!ReadFile(file, buffer.data(), static_cast<DWORD>(buffer.size()), &read, nullptr)) break;
            if (!read) {
                ok = BCryptFinishHash(hash, digest.data(), static_cast<ULONG>(digest.size()), 0) >= 0;
                break;
            }
            if (BCryptHashData(hash, buffer.data(), read, 0) < 0) break;
        }
    } while (false);
    if (file != INVALID_HANDLE_VALUE) CloseHandle(file);
    if (hash) BCryptDestroyHash(hash);
    if (algorithm) BCryptCloseAlgorithmProvider(algorithm, 0);
    return ok;
}

#if !defined(EID3D11_EMBEDDED)
bool signature(const std::uint8_t* address, std::initializer_list<std::uint8_t> bytes) {
    return address && std::memcmp(address, bytes.begin(), bytes.size()) == 0;
}

bool write_relative_jump(std::uint8_t* from, const void* target) {
    const auto source_after = reinterpret_cast<std::intptr_t>(from + 5);
    const auto destination = reinterpret_cast<std::intptr_t>(target);
    const auto delta = destination - source_after;
    if (delta < std::numeric_limits<std::int32_t>::min() ||
        delta > std::numeric_limits<std::int32_t>::max()) return false;
    std::uint8_t before[5];
    std::memcpy(before, from, sizeof(before));
    from[0] = 0xe9;
    const auto relative = static_cast<std::int32_t>(delta);
    std::memcpy(from + 1, &relative, sizeof(relative));
    // A jump back into game.exe is a restore (or a forwarder), not our hook.
    if (!game_image_contains(target)) bridge_note_owned_patch(from, before, sizeof(before));
    return true;
}
#endif // !EID3D11_EMBEDDED

// Forwarding code for one of our entry detours, always owned (and freed) by
// the bridge: the stock prologue copy plus a jump back, or for an addon
// hook-framework chain a single jump to the addon's dispatcher, which itself
// stays addon-owned. Returns nullptr for any other entry owner.
#if !defined(EID3D11_EMBEDDED)
std::uint8_t* make_entry_forwarder(std::uint8_t* entry, const std::uint8_t* stock,
                                   std::size_t stock_bytes,
                                   std::size_t hook_bytes) noexcept {
    const auto owner = resolve_hook_entry(entry, stock, stock_bytes, hook_bytes);
    if (owner.owner == EntryOwner::rejected) return nullptr;
    const std::size_t copied = owner.owner == EntryOwner::stock ? hook_bytes : 0;
    auto* forwarder = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, copied + 5, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE));
    if (!forwarder) return nullptr;
    if (copied) std::memcpy(forwarder, entry, copied);
    DWORD protection = 0;
    if (!write_relative_jump(forwarder + copied,
            copied ? static_cast<const void*>(entry + hook_bytes) : owner.dispatcher) ||
        !VirtualProtect(forwarder, copied + 5, PAGE_EXECUTE_READ, &protection)) {
        VirtualFree(forwarder, 0, MEM_RELEASE);
        return nullptr;
    }
    FlushInstructionCache(GetCurrentProcess(), forwarder, copied + 5);
    return forwarder;
}

bool write_relative_call(std::uint8_t* from, const void* target) {
    const auto source_after = reinterpret_cast<std::intptr_t>(from + 5);
    const auto destination = reinterpret_cast<std::intptr_t>(target);
    const auto delta = destination - source_after;
    if (delta < std::numeric_limits<std::int32_t>::min() ||
        delta > std::numeric_limits<std::int32_t>::max()) return false;
    std::uint8_t before[5];
    std::memcpy(before, from, sizeof(before));
    from[0] = 0xe8;
    const auto relative = static_cast<std::int32_t>(delta);
    std::memcpy(from + 1, &relative, sizeof(relative));
    // A call back to a game.exe function is a restore, not our hook.
    if (!game_image_contains(target)) bridge_note_owned_patch(from, before, sizeof(before));
    return true;
}

bool relative_call_addresses_fit(std::uintptr_t from,
                                 std::uintptr_t target) noexcept {
    const auto source_after = static_cast<std::int64_t>(from) + 5;
    const auto destination = static_cast<std::int64_t>(target);
    const auto delta = destination - source_after;
    return delta >= (std::numeric_limits<std::int32_t>::min)() &&
           delta <= (std::numeric_limits<std::int32_t>::max)();
}

bool relative_call_fits(const std::uint8_t* from,
                        const void* target) noexcept {
    if (!from || !target) return false;
    return relative_call_addresses_fit(
        reinterpret_cast<std::uintptr_t>(from),
        reinterpret_cast<std::uintptr_t>(target));
}

bool relative_call_targets(const std::uint8_t* call,
                           const void* target) noexcept {
    if (!call || call[0] != 0xe8) return false;
    std::int32_t relative = 0;
    std::memcpy(&relative, call + 1, sizeof(relative));
    return call + 5 + relative == static_cast<const std::uint8_t*>(target);
}

bool install_camp_input_hook(std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    if(!image)return false;
    auto* const call=image+sites.message_call;
    const auto original=reinterpret_cast<OuterWndProcFn>(image+sites.message_target);
    const auto hook=reinterpret_cast<const void*>(&hook_outer_wnd_proc);
    if(g_camp_input_image)return g_camp_input_image==image&&
        g_outer_wnd_proc==original&&relative_call_targets(call,hook);
    if(g_outer_frame_timing_hooks_installed){
        if(g_outer_frame_timing_image!=image||g_outer_wnd_proc!=original||
           !relative_call_targets(call,hook))return false;
        g_camp_input_image=image;
        return true;
    }
    // ProcessMessages calls fastcall WndProc directly, bypassing DispatchMessage
    // and the HWND subclass. Only this exact active call is owned by camp input.
    if(g_outer_wnd_proc||std::memcmp(call,sites.message_stock.data(),
                                   sites.message_stock.size())||
       !relative_call_fits(call,hook))return false;
    DWORD previous=0;
    if(!VirtualProtect(call,5,PAGE_EXECUTE_READWRITE,&previous))return false;
    g_outer_wnd_proc=original;
    const bool wrote=write_relative_call(call,hook)&&relative_call_targets(call,hook);
    if(!wrote)std::memcpy(call,sites.message_stock.data(),sites.message_stock.size());
    DWORD ignored=0;
    VirtualProtect(call,5,previous,&ignored);
    FlushInstructionCache(GetCurrentProcess(),call,5);
    if(!wrote){g_outer_wnd_proc=nullptr;return false;}
    g_camp_input_image=image;
    return true;
}

bool uninstall_camp_input_hook() noexcept {
    const auto& sites = outer_frame_contract();
    auto* const image=g_camp_input_image;
    if(!image)return true;
    auto* const call=image+sites.message_call;
    if(g_outer_wnd_proc!=reinterpret_cast<OuterWndProcFn>(image+sites.message_target)||
       !relative_call_targets(call,reinterpret_cast<const void*>(&hook_outer_wnd_proc)))return false;
    if(g_outer_frame_timing_hooks_installed){
        if(g_outer_frame_timing_image!=image)return false;
        g_camp_input_image=nullptr; // Timing keeps the wrapper and its forwarder.
        return true;
    }
    DWORD previous=0;
    if(!VirtualProtect(call,5,PAGE_EXECUTE_READWRITE,&previous))return false;
    std::memcpy(call,sites.message_stock.data(),sites.message_stock.size());
    DWORD ignored=0;
    VirtualProtect(call,5,previous,&ignored);
    FlushInstructionCache(GetCurrentProcess(),call,5);
    g_camp_input_image=nullptr;
    g_outer_wnd_proc=nullptr;
    return true;
}

bool outer_wnd_proc_restored_call_matches(const std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    if(!image)return false;
    // A timing rollback/uninstall restores its ownership, leaving camp intact.
    if(g_camp_input_image)return g_camp_input_image==image&&
        g_outer_wnd_proc==reinterpret_cast<OuterWndProcFn>(image+sites.message_target)&&
        relative_call_targets(image+sites.message_call,
                              reinterpret_cast<const void*>(&hook_outer_wnd_proc));
    return std::memcmp(image+sites.message_call,sites.message_stock.data(),
                       sites.message_stock.size())==0;
}

bool install_engine_frame_begin_hook(std::uint8_t* image) noexcept {
    // This call patch is verified on the base layout only. LiA's verified
    // boundary contract has patch_slots own both direct outer frame calls.
    if (renderer_boundary_contract().direct_outer_calls) return true;
    const auto* const hook = reinterpret_cast<const void*>(&hook_begin_frame);
    if (g_engine_frame_begin_image)
        return image == g_engine_frame_begin_image &&
            relative_call_targets(image + kOuterBeginFrameCallRva, hook);
    if (!image ||
        !relative_call_targets(image + kOuterBeginFrameCallRva,
                               image + kOuterBeginFrameRva) ||
        !signature(image + kOuterBeginFrameRva, {0x56,0x8b,0xf1}) ||
        !relative_call_fits(image + kOuterBeginFrameCallRva, hook))
        return false;

    auto* const call = image + kOuterBeginFrameCallRva;
    DWORD previous = 0;
    if (!VirtualProtect(call, 5, PAGE_EXECUTE_READWRITE, &previous))
        return false;
    // This direct call bypasses the renderer table. Its verified target is
    // also the native forwarder used when the semantic table is installed.
    g_begin_frame = reinterpret_cast<BeginEndFn>(image + kOuterBeginFrameRva);
    const bool wrote = write_relative_call(call, hook);
    DWORD ignored = 0;
    VirtualProtect(call, 5, previous, &ignored);
    FlushInstructionCache(GetCurrentProcess(), call, 5);
    if (wrote) g_engine_frame_begin_image = image;
    return wrote;
}

bool uninstall_engine_frame_begin_hook() noexcept {
    auto* const image = g_engine_frame_begin_image;
    if (!image) return true;
    auto* const call = image + kOuterBeginFrameCallRva;
    if (!relative_call_targets(call,
                               reinterpret_cast<const void*>(&hook_begin_frame)))
        return false; // Preserve a foreign owner's call and our retry state.
    DWORD previous = 0;
    if (!VirtualProtect(call, 5, PAGE_EXECUTE_READWRITE, &previous))
        return false;
    const bool restored = write_relative_call(call, image + kOuterBeginFrameRva);
    DWORD ignored = 0;
    VirtualProtect(call, 5, previous, &ignored);
    FlushInstructionCache(GetCurrentProcess(), call, 5);
    if (restored) g_engine_frame_begin_image = nullptr;
    return restored;
}
#endif // !EID3D11_EMBEDDED

bool outer_frame_gap_profile_requested() noexcept {
    static const bool requested = [] {
        char value[8]{};
        return GetEnvironmentVariableA(
                   "EI_RENDERER_OUTER_FRAME_GAP_PROFILE", value,
                   static_cast<DWORD>(sizeof(value))) != 0 &&
               value[0] == '1';
    }();
    return requested;
}

#if !defined(EID3D11_EMBEDDED)
bool outer_hook_relative_calls_fit(std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    if (!image) return false;
    return relative_call_fits(
               image + sites.count_call,
               outer_count_time_hook()) &&
           relative_call_fits(image + sites.pre_call,
                              reinterpret_cast<const void*>(&hook_outer_pre_tick)) &&
           relative_call_fits(image + sites.first_step_call,
                              reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
           relative_call_fits(image + sites.post_call,
                              reinterpret_cast<const void*>(&hook_outer_post_tick)) &&
           relative_call_fits(image + sites.second_step_call,
                              reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
           relative_call_fits(image + sites.third_step_call,
                              reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
           relative_call_fits(
               image + sites.idle_call,
               reinterpret_cast<const void*>(&hook_outer_interface_on_idle)) &&
           relative_call_fits(
               image + sites.message_call,
               reinterpret_cast<const void*>(&hook_outer_wnd_proc)) &&
           relative_call_fits(
               image + sites.short_message_call,
               reinterpret_cast<const void*>(&hook_outer_short_wnd_proc)) &&
           relative_call_fits(
               image + sites.end_call,
               reinterpret_cast<const void*>(&hook_end_frame));
}

bool write_outer_hook_call(std::uint8_t* call,
                           const void* target) noexcept {
#ifdef EID3D11_TESTING
    if (g_test_outer_hook_writes_until_failure == 0) return false;
    if (g_test_outer_hook_writes_until_failure > 0)
        --g_test_outer_hook_writes_until_failure;
#endif
    return write_relative_call(call, target);
}

bool outer_frame_timing_original_calls_match(
    const std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    return image &&
        std::memcmp(image + sites.count_call,
                    sites.count_stock.data(),
                    (sites.count_caller ? 5u : sites.count_stock.size())) == 0 &&
        relative_call_targets(image + sites.pre_call,
                              image + sites.pre_target) &&
        relative_call_targets(image + sites.first_step_call,
                              image + sites.step_target) &&
        relative_call_targets(image + sites.post_call,
                              image + sites.post_target) &&
        relative_call_targets(image + sites.second_step_call,
                              image + sites.step_target) &&
        relative_call_targets(image + sites.third_step_call,
                              image + sites.step_target) &&
        relative_call_targets(image + sites.idle_call,
                              image + sites.idle_target) &&
        outer_wnd_proc_restored_call_matches(image) &&
        relative_call_targets(image + sites.short_message_call,
                              image + sites.short_message_target) &&
        relative_call_targets(image + sites.end_call,
                              image + sites.end_target);
}

bool outer_frame_timing_hook_calls_match(
    const std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    return image &&
        relative_call_targets(
            image + sites.count_call,
            outer_count_time_hook()) &&
        (sites.count_caller || image[sites.count_call + 5u] == 0x90) &&
        relative_call_targets(image + sites.pre_call,
                              reinterpret_cast<const void*>(&hook_outer_pre_tick)) &&
        relative_call_targets(image + sites.first_step_call,
                              reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
        relative_call_targets(image + sites.post_call,
                              reinterpret_cast<const void*>(&hook_outer_post_tick)) &&
        relative_call_targets(image + sites.second_step_call,
                              reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
        relative_call_targets(image + sites.third_step_call,
                              reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
        relative_call_targets(
            image + sites.idle_call,
            reinterpret_cast<const void*>(&hook_outer_interface_on_idle)) &&
        relative_call_targets(
            image + sites.message_call,
            reinterpret_cast<const void*>(&hook_outer_wnd_proc)) &&
        relative_call_targets(
            image + sites.short_message_call,
            reinterpret_cast<const void*>(&hook_outer_short_wnd_proc)) &&
        relative_call_targets(
            image + sites.end_call,
            reinterpret_cast<const void*>(&hook_end_frame));
}

bool write_outer_frame_timing_hooks(std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    if (!write_outer_hook_call(
            image + sites.count_call,
            outer_count_time_hook()))
        return false;
    if (!sites.count_caller) image[sites.count_call + 5u] = 0x90;
    return write_outer_hook_call(image + sites.pre_call,
               reinterpret_cast<const void*>(&hook_outer_pre_tick)) &&
           write_outer_hook_call(image + sites.first_step_call,
               reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
           write_outer_hook_call(image + sites.post_call,
               reinterpret_cast<const void*>(&hook_outer_post_tick)) &&
           write_outer_hook_call(image + sites.second_step_call,
               reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
           write_outer_hook_call(image + sites.third_step_call,
               reinterpret_cast<const void*>(&hook_outer_fixed_step)) &&
           write_outer_hook_call(
               image + sites.idle_call,
               reinterpret_cast<const void*>(&hook_outer_interface_on_idle)) &&
           write_outer_hook_call(
               image + sites.message_call,
               reinterpret_cast<const void*>(&hook_outer_wnd_proc)) &&
           write_outer_hook_call(
               image + sites.short_message_call,
               reinterpret_cast<const void*>(&hook_outer_short_wnd_proc)) &&
           write_outer_hook_call(
               image + sites.end_call,
               reinterpret_cast<const void*>(&hook_end_frame));
}

bool restore_outer_frame_timing_calls(std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    if (!image) return false;
    std::memcpy(image + sites.count_call,
                sites.count_stock.data(),
                (sites.count_caller ? 5u : sites.count_stock.size()));
    bool restored = true;
    restored = write_relative_call(image + sites.pre_call,
                                   image + sites.pre_target) && restored;
    restored = write_relative_call(image + sites.first_step_call,
                                   image + sites.step_target) && restored;
    restored = write_relative_call(image + sites.post_call,
                                   image + sites.post_target) && restored;
    restored = write_relative_call(image + sites.second_step_call,
                                   image + sites.step_target) && restored;
    restored = write_relative_call(image + sites.third_step_call,
                                   image + sites.step_target) && restored;
    restored = write_relative_call(image + sites.idle_call,
                                   image + sites.idle_target) && restored;
    if(!g_camp_input_image)
        restored = write_relative_call(image + sites.message_call,
                                       image + sites.message_target) && restored;
    restored = write_relative_call(image + sites.short_message_call,
                                   image + sites.short_message_target) && restored;
    restored = write_relative_call(image + sites.end_call,
                                   image + sites.end_target) && restored;
    return restored && outer_frame_timing_original_calls_match(image);
}

bool install_outer_frame_timing_hooks(std::uint8_t* image) noexcept {
    const auto& sites = outer_frame_contract();
    if (g_outer_frame_timing_hooks_installed) return image == g_outer_frame_timing_image;
    // The recorder depends on rendering entry but never owns it. Its rollback
    // and teardown validate only its own sites, so both owners can retry alone.
    if (image != g_engine_frame_begin_image || !image ||
        !relative_call_targets(image + kOuterBeginFrameCallRva,
                               reinterpret_cast<const void*>(&hook_begin_frame)) ||
        !outer_frame_timing_original_calls_match(image) ||
        !outer_hook_relative_calls_fit(image))
        return false;

    if (sites.count_caller) {
        for (const auto& range : kLiaOuterFrameRanges)
            if (!object_suffix_live_code_matches(image,static_cast<std::uint32_t>(range[0]),
                    static_cast<std::size_t>(range[1]),range[2])) return false;
    }
    const auto time_get_time = sites.count_caller ? nullptr :
        *reinterpret_cast<OuterTimeGetTimeFn*>(image + sites.clock_iat);
    if (!sites.count_caller && !time_get_time) return false;

    auto* const first = image + sites.first_patch;
    auto* const last = image + sites.patch_end;
    DWORD previous = 0;
    if (!VirtualProtect(first, static_cast<SIZE_T>(last - first),
                        PAGE_EXECUTE_READWRITE, &previous))
        return false;

    g_outer_time_get_time = time_get_time;
    g_outer_pre_tick = reinterpret_cast<OuterPreTickFn>(
        image + sites.pre_target);
    g_outer_fixed_step = reinterpret_cast<OuterFixedStepFn>(
        image + sites.step_target);
    g_outer_count_time = sites.count_caller
        ? reinterpret_cast<OuterCountTimeFn>(image + sites.count_target) : nullptr;
    g_outer_native_post_tick = sites.count_caller
        ? reinterpret_cast<OuterNativePostTickFn>(image + sites.post_target) : nullptr;
    g_outer_post_tick = sites.count_caller ? nullptr :
        reinterpret_cast<OuterPostTickFn>(image + sites.post_target);
    g_outer_interface_on_idle = reinterpret_cast<OuterInterfaceOnIdleFn>(
        image + sites.idle_target);
    g_outer_wnd_proc = reinterpret_cast<OuterWndProcFn>(image + sites.message_target);
    g_outer_short_wnd_proc = reinterpret_cast<OuterShortWndProcFn>(
        image + sites.short_message_target);

    const bool wrote = write_outer_frame_timing_hooks(image) &&
        outer_frame_timing_hook_calls_match(image);

    if (!wrote) (void)restore_outer_frame_timing_calls(image);

    DWORD ignored = 0;
    VirtualProtect(first, static_cast<SIZE_T>(last - first), previous, &ignored);
    FlushInstructionCache(GetCurrentProcess(), first,
                          static_cast<SIZE_T>(last - first));
    if (!wrote) {
        g_outer_time_get_time = nullptr;
        g_outer_count_time = nullptr;
        g_outer_native_post_tick = nullptr;
        g_outer_pre_tick = nullptr;
        g_outer_fixed_step = nullptr;
        g_outer_post_tick = nullptr;
        g_outer_interface_on_idle = nullptr;
        if(!g_camp_input_image)g_outer_wnd_proc = nullptr;
        g_outer_short_wnd_proc = nullptr;
        return false;
    }
    g_outer_frame_timing_image = image;
    g_outer_frame_timing_hooks_installed = true;
    return true;
}

bool uninstall_outer_frame_timing_hooks() noexcept {
    const auto& sites = outer_frame_contract();
    if (!g_outer_frame_timing_hooks_installed) return true;
    auto* const image = g_outer_frame_timing_image;
    if (!image ||
        !relative_call_targets(image + sites.count_call,
                               outer_count_time_hook()) ||
        (!sites.count_caller && image[sites.count_call + 5u] != 0x90) ||
        !relative_call_targets(image + sites.pre_call,
                               reinterpret_cast<const void*>(&hook_outer_pre_tick)) ||
        !relative_call_targets(image + sites.first_step_call,
                               reinterpret_cast<const void*>(&hook_outer_fixed_step)) ||
        !relative_call_targets(image + sites.post_call,
                               reinterpret_cast<const void*>(&hook_outer_post_tick)) ||
        !relative_call_targets(image + sites.second_step_call,
                               reinterpret_cast<const void*>(&hook_outer_fixed_step)) ||
        !relative_call_targets(image + sites.third_step_call,
                               reinterpret_cast<const void*>(&hook_outer_fixed_step)) ||
        !relative_call_targets(image + sites.idle_call,
                               reinterpret_cast<const void*>(
                                   &hook_outer_interface_on_idle)) ||
        !relative_call_targets(image + sites.message_call,
                               reinterpret_cast<const void*>(
                                   &hook_outer_wnd_proc)) ||
        !relative_call_targets(image + sites.short_message_call,
                               reinterpret_cast<const void*>(
                                   &hook_outer_short_wnd_proc)) ||
        !relative_call_targets(image + sites.end_call,
                               reinterpret_cast<const void*>(
                                   &hook_end_frame)))
        return false;

    auto* const first = image + sites.first_patch;
    auto* const last = image + sites.patch_end;
    DWORD previous = 0;
    if (!VirtualProtect(first, static_cast<SIZE_T>(last - first),
                        PAGE_EXECUTE_READWRITE, &previous))
        return false;
    const bool restored = restore_outer_frame_timing_calls(image);
    DWORD ignored = 0;
    VirtualProtect(first, static_cast<SIZE_T>(last - first), previous, &ignored);
    FlushInstructionCache(GetCurrentProcess(), first,
                          static_cast<SIZE_T>(last - first));
    if (!restored) return false;
    bridge_set_outer_frame_timing_active(false);
    g_outer_time_get_time = nullptr;
    g_outer_count_time = nullptr;
    g_outer_native_post_tick = nullptr;
    g_outer_pre_tick = nullptr;
    g_outer_fixed_step = nullptr;
    g_outer_post_tick = nullptr;
    g_outer_interface_on_idle = nullptr;
    if(!g_camp_input_image)g_outer_wnd_proc = nullptr;
    g_outer_short_wnd_proc = nullptr;
    g_outer_frame_timing_image = nullptr;
    g_outer_frame_timing_hooks_installed = false;
    return true;
}

template <std::size_t Size>
bool exact_span(const std::uint8_t* image, std::uint32_t rva,
                const std::array<std::uint8_t, Size>& expected) noexcept {
    return image && std::memcmp(image + rva, expected.data(), Size) == 0;
}
#endif // !EID3D11_EMBEDDED

template <std::size_t Size>
void write_u32(std::array<std::uint8_t, Size>& bytes, std::size_t offset,
               std::uint32_t value) noexcept {
    std::memcpy(bytes.data() + offset, &value, sizeof(value));
}

#if !defined(EID3D11_EMBEDDED)
std::uint32_t loaded_address(const std::uint8_t* image,
                             std::uint32_t rva) noexcept {
    return static_cast<std::uint32_t>(
        reinterpret_cast<std::uintptr_t>(image) + rva);
}
#endif // !EID3D11_EMBEDDED

// Discovery proved that every reference to the route byte is its config
// writer or a boolean test, so only its live value needs checking here.
#if !defined(EID3D11_EMBEDDED)
bool generated_mmp_route_live_contract(std::uint8_t* addon) noexcept {
    const auto route = g_addon.layout.visual.route;
    return addon && route && addon == g_addon.image &&
        addon[route] <= kGeneratedMmpMemoryRoute;
}
#endif // !EID3D11_EMBEDDED

struct HudAtlasRelocatedBytes {
    std::array<std::uint8_t, 7> stock_entry{{
        0x6a,0xff,0x68,0x00,0x00,0x00,0x00}};
    std::array<std::uint8_t, 11> addon_texture_lock{{
        0x55,0x8b,0xec,0xff,0x75,0x08,0x68,0x00,0x00,0x00,0x00}};
    std::array<std::uint8_t, 11> stock_critical_enter{{
        0x68,0x00,0x00,0x00,0x00,0xff,0x15,0x00,0x00,0x00,0x00}};
    std::array<std::uint8_t, 11> stock_critical_leave{{
        0x68,0x00,0x00,0x00,0x00,0xff,0x15,0x00,0x00,0x00,0x00}};
    std::array<std::uint8_t, 22> stock_cleanup{{
        0x8b,0x0d,0x00,0x00,0x00,0x00,0x8b,0x11,0xff,0x52,0x58,
        0x8b,0x4c,0x24,0x14,0x33,0xc0,0x85,0xc9,0x0f,0x95,0xc0}};
    std::array<std::uint8_t, 12> texture_lock_critical_enter{{
        0x57,0x68,0x00,0x00,0x00,0x00,0xff,0x15,0x00,0x00,0x00,0x00}};
    std::array<std::uint8_t, 11> texture_unlock_critical_leave{{
        0x68,0x00,0x00,0x00,0x00,0xff,0x15,0x00,0x00,0x00,0x00}};
};

#if !defined(EID3D11_EMBEDDED)
HudAtlasRelocatedBytes hud_atlas_relocated_bytes(
    const std::uint8_t* game_image) noexcept {
    HudAtlasRelocatedBytes expected{};
    const auto critical = loaded_address(game_image, kGameCriticalSectionRva);
    const auto enter_iat = loaded_address(
        game_image, kGameEnterCriticalSectionIatRva);
    const auto leave_iat = loaded_address(
        game_image, kGameLeaveCriticalSectionIatRva);
    write_u32(expected.stock_entry, 3,
              loaded_address(game_image, kGameExceptionHandlerRva));
    write_u32(expected.addon_texture_lock, 7,
              loaded_address(game_image, kTextureLockRenderSurfaceRva));
    write_u32(expected.stock_critical_enter, 1, critical);
    write_u32(expected.stock_critical_enter, 7, enter_iat);
    write_u32(expected.stock_critical_leave, 1, critical);
    write_u32(expected.stock_critical_leave, 7, leave_iat);
    write_u32(expected.stock_cleanup, 2,
              loaded_address(game_image, resource_manager_contract().texture_slot));
    write_u32(expected.texture_lock_critical_enter, 2, critical);
    write_u32(expected.texture_lock_critical_enter, 8, enter_iat);
    write_u32(expected.texture_unlock_critical_leave, 1, critical);
    write_u32(expected.texture_unlock_critical_leave, 7, leave_iat);
    return expected;
}

bool hud_atlas_live_contract(const std::uint8_t* game_image,
                             const std::uint8_t* addon_image) noexcept {
    if (!game_image || !addon_image) return false;
    const auto relocated = hud_atlas_relocated_bytes(game_image);
    const AddonHudAtlasLayout& atlas = g_addon.layout.hud_atlas;
    return
        atlas.producer &&
        exact_span(addon_image, atlas.producer, kAddonHudAtlasEntryBytes) &&
        hook_entry_usable(game_image + kStockHudAtlasProducerRva,
                          relocated.stock_entry.data(), relocated.stock_entry.size(),
                          kStockHudAtlasProducerPatchBytes) &&
        relative_call_targets(addon_image + atlas.lock_call,
                              addon_image + atlas.texture_lock_thunk) &&
        exact_span(addon_image, atlas.texture_lock_thunk,
                   relocated.addon_texture_lock) &&
        exact_span(game_image, kStockHudAtlasCriticalEnterRva,
                   relocated.stock_critical_enter) &&
        exact_span(game_image, kStockHudAtlasLockResultRva,
                   kStockHudAtlasLockResultBytes) &&
        exact_span(game_image, kStockHudAtlasAddressingRva,
                   kStockHudAtlasAddressingBytes) &&
        exact_span(game_image, kStockHudAtlasWriteRva,
                   kStockHudAtlasWriteBytes) &&
        exact_span(game_image, kStockHudAtlasCriticalLeaveRva,
                   relocated.stock_critical_leave) &&
        exact_span(game_image, kStockHudAtlasUnlockRva,
                   kStockHudAtlasUnlockBytes) &&
        exact_span(game_image, kStockHudAtlasCleanupRva,
                   relocated.stock_cleanup) &&
        exact_span(game_image, kTextureLockRenderSurfaceRva,
                   kTextureLockEntryBytes) &&
        exact_span(game_image, kTextureLockCriticalEnterRva,
                   relocated.texture_lock_critical_enter) &&
        exact_span(game_image, kTextureLockOperationRva,
                   kTextureLockOperationBytes) &&
        exact_span(game_image, kTextureUnlockRenderSurfaceRva,
                   kTextureUnlockEntryBytes) &&
        exact_span(game_image, kTextureUnlockCriticalLeaveRva,
                   relocated.texture_unlock_critical_leave) &&
        exact_span(game_image, kTextureUnlockOperationRva,
                   kTextureUnlockOperationBytes);
}
#endif // !EID3D11_EMBEDDED

struct HudAtlasPatch {
    std::uint8_t* entry = nullptr;
    std::size_t bytes = 0;
    const void* replacement = nullptr;
    bool call = false;
};

using HudAtlasPatchSet = std::array<HudAtlasPatch, 3>;
using HudAtlasOriginalSet = std::array<const std::uint8_t*, 3>;

#if !defined(EID3D11_EMBEDDED)
bool apply_hud_atlas_patch(const HudAtlasPatch& item) noexcept {
    DWORD protection = 0;
    if (!item.entry || item.bytes < 5 || !item.replacement ||
        !VirtualProtect(item.entry, item.bytes, PAGE_EXECUTE_READWRITE,
                        &protection))
        return false;
    const bool wrote = item.call
        ? write_relative_call(item.entry, item.replacement)
        : write_relative_jump(item.entry, item.replacement);
    if (wrote && !item.call && item.bytes > 5)
        std::memset(item.entry + 5, 0x90, item.bytes - 5);
    DWORD ignored = 0;
    VirtualProtect(item.entry, item.bytes, protection, &ignored);
    FlushInstructionCache(GetCurrentProcess(), item.entry, item.bytes);
    return wrote;
}

bool owns_hud_atlas_patch(const HudAtlasPatch& item) noexcept {
    return item.call
        ? relative_call_targets(item.entry, item.replacement)
        : relative_jump_target(item.entry) == item.replacement;
}
#endif // !EID3D11_EMBEDDED

enum class HudAtlasPatchResult : std::uint8_t {
    installed,
    rejected,
    rollback_failed,
};

#if !defined(EID3D11_EMBEDDED)
HudAtlasPatchResult apply_hud_atlas_patch_transaction(
    const HudAtlasPatchSet& patches,
    const HudAtlasOriginalSet& originals) noexcept {
    std::size_t patched = 0;
    for (; patched < patches.size(); ++patched)
        if (!apply_hud_atlas_patch(patches[patched])) break;
    if (patched == patches.size()) return HudAtlasPatchResult::installed;
    bool restored = true;
    while (patched) {
        --patched;
        restored = restore_inline_entry(
                       patches[patched].entry, originals[patched],
                       patches[patched].bytes) && restored;
    }
    return restored ? HudAtlasPatchResult::rejected
                    : HudAtlasPatchResult::rollback_failed;
}

bool restore_hud_atlas_patch_transaction(
    const HudAtlasPatchSet& patches,
    const HudAtlasOriginalSet& originals) noexcept {
    for (std::size_t index = 0; index < patches.size(); ++index) {
        if (!owns_hud_atlas_patch(patches[index]) &&
            std::memcmp(patches[index].entry, originals[index],
                        patches[index].bytes) != 0)
            return false;
    }
    for (std::size_t remaining = patches.size(); remaining; --remaining) {
        const auto index = remaining - 1;
        if (owns_hud_atlas_patch(patches[index]) &&
            !restore_inline_entry(patches[index].entry, originals[index],
                                  patches[index].bytes))
            return false;
    }
    return true;
}

bool exact_loaded_module(HMODULE module, std::uint32_t expected_image_size,
                         const std::array<std::uint8_t, 32>& expected_hash)
    noexcept {
    if (!module) return false;
    __try {
        const auto* base = reinterpret_cast<const std::uint8_t*>(module);
        const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE) return false;
        const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS*>(
            base + dos->e_lfanew);
        if (nt->Signature != IMAGE_NT_SIGNATURE ||
            nt->FileHeader.Machine != IMAGE_FILE_MACHINE_I386 ||
            nt->OptionalHeader.Magic != IMAGE_NT_OPTIONAL_HDR32_MAGIC ||
            nt->OptionalHeader.SizeOfImage != expected_image_size)
            return false;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
    char path[MAX_PATH]{};
    if (!GetModuleFileNameA(module, path, static_cast<DWORD>(sizeof(path))))
        return false;
    std::array<std::uint8_t, 32> digest{};
    return sha256_file(path, digest) && digest == expected_hash;
}
#endif // !EID3D11_EMBEDDED

// How find_addon_module recognised the loaded addon.dll, for the player
// notice (bridge_addon_notice). none also covers "no addon.dll loaded".
enum class AddonRecognition : std::uint8_t { none, full, partial, rejected };
AddonRecognition g_addon_recognition = AddonRecognition::none;
char g_addon_hash[65] = "unavailable";

#if !defined(EID3D11_EMBEDDED)
void addon_module_hash(const std::uint8_t* image, char (&hash)[65]) noexcept {
    char path[MAX_PATH]{};
    std::array<std::uint8_t, 32> digest{};
    if (!GetModuleFileNameA(reinterpret_cast<HMODULE>(const_cast<std::uint8_t*>(image)), path, MAX_PATH) ||
        !sha256_file(path, digest))
        return;
    for (std::size_t index = 0; index < digest.size(); ++index)
        std::snprintf(hash + index * 2, 3, "%02x", digest[index]);
}
#endif // !EID3D11_EMBEDDED

// Selects the loaded addon.dll by its discovered content. Base and mod
// addons may share the basename; the candidate whose image yields addon
// contracts is selected, and an ambiguous choice selects nothing. The
// selected module is logged once with its hash and per-contract status.
#if !defined(EID3D11_EMBEDDED)
std::uint8_t* find_addon_module() noexcept {
    struct Candidate {
        std::uint8_t* image;
        AddonLayout layout;
        bool any;
    };
    static std::array<Candidate, 4> discovered{};
    static std::size_t discovered_count = 0;
    static const std::uint8_t* logged = nullptr;
    const HANDLE modules = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, GetCurrentProcessId());
    if (modules == INVALID_HANDLE_VALUE) return nullptr;
    MODULEENTRY32W entry{};
    entry.dwSize = sizeof(entry);
    const Candidate* selected = nullptr;
    bool ambiguous = false;
    if (Module32FirstW(modules, &entry)) do {
        if (_wcsicmp(entry.szModule, L"addon.dll") != 0) continue;
        auto* image = reinterpret_cast<std::uint8_t*>(entry.hModule);
        const Candidate* candidate = nullptr;
        for (std::size_t index = 0; index < discovered_count; ++index)
            if (discovered[index].image == image) candidate = &discovered[index];
        if (!candidate) {
            if (discovered_count == discovered.size()) { ambiguous = true; break; }
            Candidate& slot = discovered[discovered_count++];
            slot.image = image;
            slot.layout = discover_addon_layout(image);
            slot.any = !slot.layout.hud_atlas_failure || !slot.layout.pane_failure ||
                !slot.layout.res_cache_failure || !slot.layout.hud_visual_failure ||
                !slot.layout.visual_failure;
            candidate = &slot;
        }
        if (!candidate->any) continue;
        if (selected && selected->image != candidate->image) ambiguous = true;
        selected = candidate;
    } while (Module32NextW(modules, &entry));
    CloseHandle(modules);
    if (ambiguous || !selected) {
        static bool rejection_logged = false;
        if (!rejection_logged) {
            rejection_logged = true;
            // A loaded addon.dll without a usable contract is shown to the
            // player; no addon.dll at all is the supported native setup.
            if (discovered_count) {
                g_addon_recognition = AddonRecognition::rejected;
                addon_module_hash(discovered[0].image, g_addon_hash);
            }
            append_bridge_event("addon_module_rejected",
                ambiguous ? "several addon.dll images yield addon contracts" :
                            "no loaded addon.dll yields an addon contract", true);
        }
        return nullptr;
    }
    g_addon.image = selected->image;
    g_addon.layout = selected->layout;
    if (logged != selected->image) {
        logged = selected->image;
        addon_module_hash(selected->image, g_addon_hash);
        const AddonLayout& layout = selected->layout;
        g_addon_recognition = layout.hud_atlas_failure || layout.pane_failure ||
            layout.res_cache_failure || layout.hud_visual_failure || layout.visual_failure ?
            AddonRecognition::partial : AddonRecognition::full;
        const auto status = [](const char* failure) { return failure ? failure : "ok"; };
        char detail[512];
        std::snprintf(detail, sizeof(detail),
            "sha256=%s hud_atlas=%s pane=%s res_cache=%s hud_visual=%s visual=%s resolver=%s",
            g_addon_hash, status(selected->layout.hud_atlas_failure),
            status(selected->layout.pane_failure), status(selected->layout.res_cache_failure),
            status(selected->layout.hud_visual_failure), status(selected->layout.visual_failure),
            status(selected->layout.resolver_failure));
        append_bridge_event("addon_module", detail, true);
    }
    return selected->image;
}
#endif // !EID3D11_EMBEDDED

// BridgeFeatureOff bits noted by the installs (engine_bridge.h).
std::uint32_t g_features_off = 0;
char g_addon_notice[256]{};

// After every install decided: required world publication refusal is visible
// regardless of addon recognition. Keep the existing detailed feature event;
// optional addon losses use the same persistent notice when world is available.
void publish_addon_notice(bool world_available) noexcept {
    g_addon_notice[0] = '\0';
    if (!world_available)
        std::snprintf(g_addon_notice, sizeof(g_addon_notice),
                      "EID3D11: world visuals unavailable. See bridge.jsonl for the reason.");
    if (g_addon_recognition != AddonRecognition::rejected &&
        g_addon_recognition != AddonRecognition::partial) return;
    static constexpr struct { std::uint32_t bit; const char* text; } kFeatures[] = {
        {bridge_feature_off_hud_icons, "weapon/spell icons"},
        {bridge_feature_off_owned_world, "panel figures, point lights, grass, critters"},
        {bridge_feature_off_camp_grid, "wide camp inventory"},
        {bridge_feature_off_hud_layout, "HUD layout"},
    };
    char off[160]{};
    const char* other_off = nullptr;
    for (const auto& feature : kFeatures) {
        if (!(g_features_off & feature.bit)) continue;
        const std::size_t used = std::strlen(off);
        // The icon row is first; other losses form a suffix of the same log text.
        if (feature.bit != bridge_feature_off_hud_icons && !other_off)
            other_off = off + used + (used ? 2 : 0);
        std::snprintf(off + used, sizeof(off) - used, "%s%s", used ? ", " : "", feature.text);
    }
    if (!off[0]) return;
    const bool rejected = g_addon_recognition == AddonRecognition::rejected;
    if (world_available) {
        // A working native HUD leaves addon-only icon uncertainty in logs.
        const char* visible_off = g_hud_visual_hooks_installed && g_hud_visual_native
            ? other_off : off;
        if (visible_off && *visible_off)
            std::snprintf(g_addon_notice, sizeof(g_addon_notice),
                          "Addon %s (addon.dll %.8s) - off: %s (see bridge.jsonl)",
                          rejected ? "not recognised" : "partly recognised", g_addon_hash, visible_off);
    }
    char detail[320];
    std::snprintf(detail, sizeof(detail), "addon=%s sha256=%s off=%s",
                  rejected ? "rejected" : "partial", g_addon_hash, off);
    append_bridge_event("addon_features_off", detail, true);
}

#if !defined(EID3D11_EMBEDDED)
bool install_hud_atlas_hooks(std::uint8_t* game_image) noexcept {
    g_hud_atlas_install_detail = "invalid_game_or_already_installed";
    if (!game_image || g_hud_atlas_hooks_installed) return false;
    // Base and mod addons share a basename. Select by the discovered content,
    // not the loader's unspecified choice for an ambiguous basename lookup.
    std::uint8_t* addon_image = find_addon_module();
    if (!addon_image) {
        g_hud_atlas_install_detail = "addon_module_missing_or_ambiguous";
        return false;
    }
    if (g_addon.layout.hud_atlas_failure) {
        g_hud_atlas_install_detail = g_addon.layout.hud_atlas_failure;
        return false;
    }
    const AddonHudAtlasLayout& atlas = g_addon.layout.hud_atlas;
    auto* addon_entry = addon_image + atlas.producer;
    auto* stock_entry = game_image + kStockHudAtlasProducerRva;
    auto* addon_lock_call = addon_image + atlas.lock_call;
    auto* addon_texture_lock = addon_image + atlas.texture_lock_thunk;
    if (!hud_atlas_live_contract(game_image, addon_image)) {
        g_hud_atlas_install_detail = "live_producer_span_mismatch";
        return false;
    }

    const auto make_trampoline = [](std::uint8_t* entry,
                                    std::size_t bytes) -> std::uint8_t* {
        auto* trampoline = static_cast<std::uint8_t*>(VirtualAlloc(
            nullptr, bytes + 5, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE));
        if (!trampoline) return nullptr;
        std::memcpy(trampoline, entry, bytes);
        if (!write_relative_jump(trampoline + bytes, entry + bytes)) {
            VirtualFree(trampoline, 0, MEM_RELEASE);
            return nullptr;
        }
        DWORD protection = 0;
        if (!VirtualProtect(trampoline, bytes + 5, PAGE_EXECUTE_READ,
                            &protection)) {
            VirtualFree(trampoline, 0, MEM_RELEASE);
            return nullptr;
        }
        return trampoline;
    };
    auto* addon_trampoline = make_trampoline(
        addon_entry, kAddonHudAtlasProducerPatchBytes);
    const auto stock_prologue = hud_atlas_relocated_bytes(game_image).stock_entry;
    auto* stock_trampoline = make_entry_forwarder(
        stock_entry, stock_prologue.data(), stock_prologue.size(),
        kStockHudAtlasProducerPatchBytes);
    if (!addon_trampoline || !stock_trampoline) {
        if (addon_trampoline) VirtualFree(addon_trampoline, 0, MEM_RELEASE);
        if (stock_trampoline) VirtualFree(stock_trampoline, 0, MEM_RELEASE);
        g_hud_atlas_install_detail = "producer_trampoline_allocation_failed";
        return false;
    }

    std::memcpy(g_addon_hud_atlas_original.data(), addon_entry,
                kAddonHudAtlasProducerPatchBytes);
    std::memcpy(g_stock_hud_atlas_original.data(), stock_entry,
                kStockHudAtlasProducerPatchBytes);
    std::memcpy(g_addon_hud_atlas_lock_call_original.data(), addon_lock_call,
                kAddonHudAtlasLockCallBytes);
    g_addon_hud_atlas_trampoline = addon_trampoline;
    g_stock_hud_atlas_trampoline = stock_trampoline;
    g_addon_hud_atlas_producer =
        reinterpret_cast<AddonHudAtlasProducerFn>(addon_trampoline);
    g_stock_hud_atlas_producer =
        reinterpret_cast<StockHudAtlasProducerFn>(stock_trampoline);
    g_addon_texture_lock =
        reinterpret_cast<AddonTextureLockFn>(addon_texture_lock);
    g_hud_atlas_addon_image = addon_image;
    g_hud_atlas_game_image = game_image;

    const HudAtlasPatchSet patches{{
        {addon_entry, kAddonHudAtlasProducerPatchBytes,
         reinterpret_cast<const void*>(&hook_addon_hud_atlas_producer), false},
        {stock_entry, kStockHudAtlasProducerPatchBytes,
         reinterpret_cast<const void*>(&hook_stock_hud_atlas_producer), false},
        {addon_lock_call, kAddonHudAtlasLockCallBytes,
         reinterpret_cast<const void*>(&hook_addon_hud_atlas_texture_lock), true},
    }};
    const HudAtlasOriginalSet originals{{
        g_addon_hud_atlas_original.data(),
        g_stock_hud_atlas_original.data(),
        g_addon_hud_atlas_lock_call_original.data(),
    }};
    const auto patch_result =
        apply_hud_atlas_patch_transaction(patches, originals);
    if (patch_result != HudAtlasPatchResult::installed) {
        if (patch_result == HudAtlasPatchResult::rollback_failed) {
            g_hud_atlas_hooks_installed = true;
            g_hud_atlas_install_detail = "patch_transaction_rollback_failed";
            return false;
        }
        VirtualFree(addon_trampoline, 0, MEM_RELEASE);
        VirtualFree(stock_trampoline, 0, MEM_RELEASE);
        g_addon_hud_atlas_trampoline = nullptr;
        g_stock_hud_atlas_trampoline = nullptr;
        g_addon_hud_atlas_producer = nullptr;
        g_stock_hud_atlas_producer = nullptr;
        g_addon_texture_lock = nullptr;
        g_hud_atlas_addon_image = nullptr;
        g_hud_atlas_game_image = nullptr;
        g_hud_atlas_install_detail = "patch_transaction_rejected";
        return false;
    }
    g_hud_atlas_hooks_installed = true;
    g_hud_atlas_install_detail = "verified_live_producer_spans";
    return true;
}

bool uninstall_hud_atlas_hooks() noexcept {
    if (!g_hud_atlas_hooks_installed) return true;
    if (!g_hud_atlas_addon_image || !g_hud_atlas_game_image) return false;
    auto* addon_entry = g_hud_atlas_addon_image + g_addon.layout.hud_atlas.producer;
    auto* stock_entry = g_hud_atlas_game_image + kStockHudAtlasProducerRva;
    auto* addon_lock_call =
        g_hud_atlas_addon_image + g_addon.layout.hud_atlas.lock_call;
    const HudAtlasPatchSet patches{{
        {addon_entry, kAddonHudAtlasProducerPatchBytes,
         reinterpret_cast<const void*>(&hook_addon_hud_atlas_producer), false},
        {stock_entry, kStockHudAtlasProducerPatchBytes,
         reinterpret_cast<const void*>(&hook_stock_hud_atlas_producer), false},
        {addon_lock_call, kAddonHudAtlasLockCallBytes,
         reinterpret_cast<const void*>(&hook_addon_hud_atlas_texture_lock), true},
    }};
    const HudAtlasOriginalSet originals{{
        g_addon_hud_atlas_original.data(),
        g_stock_hud_atlas_original.data(),
        g_addon_hud_atlas_lock_call_original.data(),
    }};
    if (!restore_hud_atlas_patch_transaction(patches, originals))
        return false;
    if (g_addon_hud_atlas_trampoline)
        VirtualFree(g_addon_hud_atlas_trampoline, 0, MEM_RELEASE);
    if (g_stock_hud_atlas_trampoline)
        VirtualFree(g_stock_hud_atlas_trampoline, 0, MEM_RELEASE);
    g_addon_hud_atlas_producer = nullptr;
    g_stock_hud_atlas_producer = nullptr;
    g_addon_texture_lock = nullptr;
    g_addon_hud_atlas_trampoline = nullptr;
    g_stock_hud_atlas_trampoline = nullptr;
    g_hud_atlas_addon_image = nullptr;
    g_hud_atlas_game_image = nullptr;
    g_hud_atlas_hooks_installed = false;
    g_hud_atlas_producer = {};
    g_addon_hud_atlas_lock_pending = false;
    return true;
}
#endif // !EID3D11_EMBEDDED

struct HudVisualEntryPatch {
    std::uint8_t* entry = nullptr;
    std::size_t bytes = 0;
    const void* replacement = nullptr;
};

struct HudVisualCallPatch {
    std::uint8_t* call = nullptr;
    const void* expected = nullptr;
    const void* replacement = nullptr;
};

#if !defined(EID3D11_EMBEDDED)
std::array<HudVisualEntryPatch, 14> hud_visual_entry_patches(
    std::uint8_t* game, std::uint8_t* addon) noexcept {
    const auto& contract = hud_game_contract();
    // A null addon selects the stock weapon/spell/skill panel entries.
    const AddonHudVisualLayout& hud = g_addon.layout.hud_visual;
    if (addon && g_addon.layout.hud_visual_failure) return {};
    const HudVisualEntryPatch weapon = addon ?
        HudVisualEntryPatch{addon + hud.weapon_set_unit, 6,
                            reinterpret_cast<const void*>(&hook_hud_weapon_set_unit)} :
        HudVisualEntryPatch{game + contract.panels[0], kHudNativeWeaponHookBytes,
                            reinterpret_cast<const void*>(&hook_hud_native_weapon_set_unit)};
    const HudVisualEntryPatch spell = addon ?
        HudVisualEntryPatch{addon + hud.spell_set_unit, 5,
                            reinterpret_cast<const void*>(&hook_hud_spell_set_unit)} :
        HudVisualEntryPatch{game + contract.panels[1], kHudNativeSpellHookBytes,
                            reinterpret_cast<const void*>(&hook_hud_spell_set_unit)};
    const HudVisualEntryPatch skill = addon ?
        HudVisualEntryPatch{addon + hud.skill_set_unit, 7,
                            reinterpret_cast<const void*>(&hook_hud_skill_set_unit)} :
        HudVisualEntryPatch{game + contract.panels[2], kHudNativeSkillHookBytes,
                            reinterpret_cast<const void*>(&hook_hud_native_skill_set_unit)};
    return {{
        {game + contract.entries[0], contract.hook_bytes[0],
         reinterpret_cast<const void*>(&hook_hud_on_activate)},
        {game + contract.entries[1], contract.hook_bytes[1],
         reinterpret_cast<const void*>(&hook_hud_on_deactivate)},
        {game + contract.entries[2], contract.hook_bytes[2],
         reinterpret_cast<const void*>(&hook_hud_destructor)},
        {game + contract.entries[3], contract.hook_bytes[3],
         reinterpret_cast<const void*>(&hook_hud_item_set_unit)},
        weapon,
        spell,
        skill,
        {game + contract.entries[4], contract.hook_bytes[4],
         reinterpret_cast<const void*>(&hook_texture_manager_create)},
        {game + contract.entries[5], contract.hook_bytes[5],
         reinterpret_cast<const void*>(&hook_figure_manager_create)},
        {game + contract.entries[6], contract.hook_bytes[6],
         reinterpret_cast<const void*>(&hook_texture_resource_add)},
        {game + contract.entries[7], contract.hook_bytes[7],
         reinterpret_cast<const void*>(&hook_figure_resource_add)},
        {game + contract.entries[8], contract.hook_bytes[8],
         reinterpret_cast<const void*>(&hook_resource_close)},
        {game + contract.entries[9], contract.hook_bytes[9],
         reinterpret_cast<const void*>(&hook_resource_close_all)},
        {game + contract.entries[10], contract.hook_bytes[10],
         reinterpret_cast<const void*>(&hook_resource_destroy)},
    }};
}

std::vector<HudVisualCallPatch> hud_visual_call_patches(
    std::uint8_t* game, std::uint8_t* addon) noexcept {
    const auto& contract = hud_game_contract();
    // A null addon leaves only the stock lanes (no addon lanes or autocast box).
    static const AddonHudVisualLayout kNoAddonLanes{};
    const AddonHudVisualLayout& hud = addon ? g_addon.layout.hud_visual : kNoAddonLanes;
    if (addon && g_addon.layout.hud_visual_failure) return {};
    std::vector<HudVisualCallPatch> result;
    result.reserve(22);
    for (std::uint32_t rva : contract.producer_calls)
        result.push_back({game + rva, game + contract.producer,
                         reinterpret_cast<const void*>(&hook_hud_visual_stock_producer)});
    for (std::uint32_t lane = 0; lane < hud.lane_count; ++lane)
        result.push_back({addon + hud.producer_calls[lane], addon + hud.producer,
                          reinterpret_cast<const void*>(&hook_hud_visual_addon_producer)});
    for (std::uint32_t rva : contract.add_calls)
        result.push_back({game + rva, game + contract.add_figure,
                         reinterpret_cast<const void*>(&hook_hud_visual_add_figure)});
    for (std::uint32_t lane = 0; lane < hud.lane_count; ++lane)
        result.push_back({addon + hud.add_figure_calls[lane], addon + hud.add_figure,
                          reinterpret_cast<const void*>(&hook_hud_visual_add_figure)});
    if (hud.autocast_box)
        result.push_back({addon + hud.autocast_call, addon + hud.autocast_box,
                         reinterpret_cast<const void*>(&hook_hud_autocast_box)});
    for (std::uint32_t rva : contract.draw_calls) {
        // LiA folds item/spell/skill Draw into one callable body and site.
        if (std::none_of(result.begin(),result.end(),[&](const auto& patch) {
                return patch.call == game+rva;
            }))
            result.push_back({game+rva,game+contract.object_draw,
                             reinterpret_cast<const void*>(&hook_hud_lane_draw)});
    }
    result.push_back({game + contract.carrier_call, game + contract.figure_draw,
                     reinterpret_cast<const void*>(&hook_hud_carrier_draw)});
    return result;
}
#endif // !EID3D11_EMBEDDED

