    g_visual_database_select_secondary =
        reinterpret_cast<VisualDatabaseSelectFn>(g_visual_trampolines[25]);
    g_visual_idle_set = reinterpret_cast<VisualSelectionFn>(g_visual_trampolines[6]);
    g_visual_idle_append = reinterpret_cast<VisualSelectionFn>(g_visual_trampolines[7]);
    g_visual_unit_segment = reinterpret_cast<LifecycleTickFn>(g_visual_trampolines[8]);
    g_visual_load_template = reinterpret_cast<VisualLoadFiguresFn>(g_visual_trampolines[9]);
    g_visual_load_figures = reinterpret_cast<VisualLoadFiguresFn>(g_visual_trampolines[10]);
    g_visual_addon_load_figures = reinterpret_cast<VisualLoadFiguresFn>(g_visual_trampolines[11]);
    g_visual_change_weapon = reinterpret_cast<VisualChangeWeaponFn>(g_visual_trampolines[12]);
