bool bridge_camp_texture_mounts(ResourceStoreConfig& mounts) noexcept {
    mounts = {};
    void* manager = bridge_camp_texture_owner();
    if (!manager) return false;
    const auto* game = g_hud_visual_game_image;
    if (running_game_sites().report.engine==GameEngine::lia) {
        static const bool verified=[game]() noexcept {
            for (const auto& range:kLiaCampMountRanges)
                if (!lia_live_contract_range_matches(game,static_cast<std::uint32_t>(range[0]),
                        static_cast<std::size_t>(range[1]),range[2])) return false;
            return true;
        }();
        if (!verified) return false;
    } else {
    // Fingerprinted GetFile and AddNewResource establish the vector, string
    // spans and first-hit iteration. GetFile skips archives that never opened.
    const std::uint8_t resource_vector[]{0x8b,0xb5,0xb0,0,0,0,0x8b,0x85,0xb4,0,0,0};
    const std::uint8_t resource_record[]{0x8b,0x4e,0x0c,0x57,0x53,0x8b,0x01,0xff,0x50,0x14};
    const std::uint8_t resource_stride[]{0x83,0xc6,0x10,0x3b,0xf0,0x75,0xe5};
    const std::uint8_t resource_name[]{0x8b,0x32,0xf2,0xae,0x8b,0x42,0x04};
    const std::uint8_t resource_open[]{0x8b,0x45,0x14,0x85,0xc0,0x0f,0x84,0x7a,0x02,0,0,
        0x8b,0x45,0x18,0x85,0xc0,0x0f,0x84,0x6f,0x02,0,0};
    if (std::memcmp(game + 0x275446,resource_vector,sizeof(resource_vector)) ||
        std::memcmp(game + 0x27545e,resource_record,sizeof(resource_record)) ||
        std::memcmp(game + 0x275472,resource_stride,sizeof(resource_stride)) ||
        std::memcmp(game + 0x275095,resource_name,sizeof(resource_name)) ||
        std::memcmp(game + 0x271b5e,resource_open,sizeof(resource_open))) return false;
    }
    std::uintptr_t begin = 0, end = 0;
    if (!visual_read(manager,0xb0,begin) || !visual_read(manager,0xb4,end) ||
        end < begin || (end-begin)%16 || (end-begin)/16 > 4096) return false;
    try {
        for (auto record = begin; record < end; record += 16) {
            std::array<std::uintptr_t,4> value{};
            if (!safe_copy_hud_resource(reinterpret_cast<std::uint8_t*>(value.data()),
                reinterpret_cast<const std::uint8_t*>(record),sizeof(value))) return false;
            void* hash = nullptr; void* names = nullptr;
            if (!visual_read(reinterpret_cast<void*>(value[3]),0x14,hash) ||
                !visual_read(reinterpret_cast<void*>(value[3]),0x18,names)) return false;
            if (!hash || !names) continue;
            if (value[1] <= value[0] || value[1]-value[0] > 32767) return false;
            std::string path(value[1]-value[0], '\0');
            if (!safe_copy_hud_resource(reinterpret_cast<std::uint8_t*>(path.data()),
                reinterpret_cast<const std::uint8_t*>(value[0]),path.size())) return false;
            const int length = MultiByteToWideChar(CP_ACP,0,path.data(),static_cast<int>(path.size()),nullptr,0);
            if (!length) return false;
            std::wstring wide(length,L'\0');
            if (!MultiByteToWideChar(CP_ACP,0,path.data(),static_cast<int>(path.size()),wide.data(),length)) return false;
            const DWORD full_length = GetFullPathNameW(wide.c_str(),0,nullptr,nullptr);
            if (!full_length) return false;
            std::wstring full(full_length,L'\0');
            const DWORD written = GetFullPathNameW(wide.c_str(),full_length,full.data(),nullptr);
            if (!written || written >= full_length) return false;
            full.resize(written);
            mounts.archives.push_back(std::move(full));
        }
    } catch (...) { mounts = {}; return false; }
    return !mounts.archives.empty();
}
#endif // !EID3D11_EMBEDDED

namespace {
// Immutable geometry/mapping plus expiry segment identifies a game marker.
// No engine pointer is used as a mutable-state key. Records expire with the
// game list and are discarded on an authoritative world-epoch change.
using CoverMarkerKey = std::pair<std::int64_t, std::array<float,9>>;
struct CreatedCoverMarker {
    VisualResourceIncarnation creator{};
    ground_cover::FootprintSplat stamp{};
    bool captured = false;
    // Snow trails: creation tick, the maker's box half extent and whether it
    // walks (levitating races never cut snow).
    std::int32_t tick = 0;
    float half_extent = 0;
    bool walks = false;
};
std::map<CoverMarkerKey, CreatedCoverMarker> g_cover_markers;
std::uint64_t g_cover_marker_epoch = 0;

#if !defined(EID3D11_EMBEDDED)
std::uint32_t ground_cover_marker_vtable_rva() noexcept {
    return running_game_sites().report.engine == GameEngine::lia
        ? kLiaFootprintVtableRva : 0x0033f760u;
}

bool ground_cover_marker_contract() noexcept {
    if (!g_visual_game_image || !g_visual_publication_active) return false;
    if (running_game_sites().report.engine == GameEngine::lia) {
        for (const auto& range : kLiaFootprintMarkerRanges)
            if (!lia_live_contract_range_matches(g_visual_game_image,
                static_cast<std::uint32_t>(range[0]),static_cast<std::size_t>(range[1]),range[2]))
                return false;
        // The print hook changes only this PUSH operand. All other gate bytes,
        // including the opcode, remain hashed; teardown restores the native Draw.
        const auto& prints=game_print_contract();
        std::uint32_t target=0;
        if (!visual_read(g_visual_game_image,prints.pushes[1]+1,target)) return false;
        return target==loaded_address(g_visual_game_image,prints.draw) ||
            (g_game_prints_installed && g_game_print_image==g_visual_game_image &&
             target==static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(kGamePrintWrappers[1])));
    }
    return
        relative_call_targets(g_visual_game_image+0x134350,g_visual_game_image+0x134b60) &&
        signature(g_visual_game_image+0x134b99,{0x8b,0x02,0x89,0x44,0x24,0x50}) &&
        signature(g_visual_game_image+0x2cece5,{0x66,0xff,0x4a,0x1c}) &&
        signature(g_visual_game_image+0x2ceced,{0x8b,0x42,0x58}) &&
        signature(g_visual_game_image+0x2ced3a,{0xd8,0x4a,0x50,0xd9,0x5a,0x4c}) &&
        signature(g_visual_game_image+0x16d32a,{0x81,0xc6,0xbc,0x01,0x00,0x00});
}
#endif // !EID3D11_EMBEDDED

void refresh_cover_marker_epoch() noexcept {
    const auto epoch=lifecycle_observer().snapshot().positive_world_epoch;
    if(epoch!=g_cover_marker_epoch){g_cover_markers.clear();g_cover_marker_epoch=epoch;}
}

#if !defined(EID3D11_EMBEDDED)
bool read_cover_marker(const void* node, std::int32_t tick, bool just_created,
    CoverMarkerKey& key, std::uint8_t& visible, float& alpha) noexcept {
    const void* table=nullptr;
    std::int16_t life=0;
    std::array<float,4> rectangle{},mapping{};
    float rotation=0;
    if(!visual_read(node,8,table)||table!=g_visual_game_image+ground_cover_marker_vtable_rva()||
       !visual_read(node,8+5,visible)||!visual_read(node,8+8,rectangle)||
       !visual_read(node,8+0x1c,life)||!visual_read(node,8+0x30,mapping)||
       !visual_read(node,8+0x44,rotation)||!visual_read(node,8+0x4c,alpha)||
       !finite_vector(rectangle.data(),rectangle.size())||
       !finite_vector(mapping.data(),mapping.size())||!std::isfinite(rotation)||
       !std::isfinite(alpha)||rectangle[2]<=0||rectangle[3]<=0||life<=0)return false;
    key.first=std::int64_t(tick)+life-(just_created?1:0);
    std::copy(rectangle.begin(),rectangle.end(),key.second.begin());
    key.second[4]=rotation;
    std::copy(mapping.begin(),mapping.end(),key.second.begin()+5);
    return true;
}

GroundCoverFootprintAppend begin_ground_cover_footprint_append() noexcept {
    GroundCoverFootprintAppend result{};
    if(!ground_cover_marker_contract())return result;
    refresh_cover_marker_epoch();
    double time=0;
    if(!read_owned_world_time(g_visual_game_image,time))return result;
    while(!g_cover_markers.empty()&&
          !ground_cover::footprint_history_needed(double(g_cover_markers.begin()->first.first),time))
        g_cover_markers.erase(g_cover_markers.begin());
    const void* world=g_visual_game_image+world_clock_contract().client_rva;
    std::array<const void*,2> ends{};
    if(!visual_read(world,0x1bc,result.head)||!result.head||
       !visual_read(result.head,0,ends)||!ends[0]||!ends[1])return {};
    result.tail=ends[1];return result;
}

void publish_ground_cover_footprint_append(void* object, VisualResourceIncarnation resource,
    GroundCoverFootprintAppend before) noexcept try {
    if(!before.head||!before.tail)return;
    refresh_cover_marker_epoch();
    const auto after=begin_ground_cover_footprint_append();
    if(after.head!=before.head||after.tail==before.tail)return;
    VisualTickValues values{};
    std::array<float,3> centre{};std::int32_t tick=0;
    if(!retained_visual_scene().visual_tick_values(resource,values)||
       values.hidden||(values.object_flags&0x40u)||values.dead||values.invisible||
       !visual_read(object,0x1c,centre)||!finite_vector(centre.data(),centre.size())||
       !visual_read(g_visual_game_image,world_clock_contract().ticks_rva,tick))return;
    CreatedCoverMarker created{};created.creator=resource;created.tick=tick;
    created.half_extent=snow_trail_extent(values.target_half_extent);
    created.walks=ground_cover::unit_presses_cover(values.locomotion);
    created.stamp.rectangle[0]=centre[0];created.stamp.rectangle[1]=centre[1];
    const void* node=nullptr;
    if(!visual_read(before.tail,0,node))return;
    const void* previous=before.tail;
    while(node&&node!=before.head){
        std::array<const void*,2> links{};CoverMarkerKey key{};
        std::uint8_t visible=0;float alpha=0;
        if(!visual_read(node,0,links)||links[1]!=previous||
           !read_cover_marker(node,tick,true,key,visible,alpha))return;
        if(visible){
            const auto inserted=g_cover_markers.emplace(key,created);
            // Identical simultaneous marker values are ambiguous; omit instead
            // of assigning either character's stamp to the other.
            if(!inserted.second){inserted.first->second.stamp.effect[2]=0;inserted.first->second.captured=true;}
        }
        if(node==after.tail)break;
        previous=node;node=links[0];
    }
} catch(...) { append_bridge_event("ground_cover_marker_omitted","creation snapshot allocation failed",true); }
#endif // !EID3D11_EMBEDDED

// Game thread: the footprint list read (and the marker records it keeps).
#if !defined(EID3D11_EMBEDDED)
bool read_ground_cover_footprints(std::vector<ground_cover::FootprintSplat>& output,
    std::vector<FootprintTrailPoint>* trail_points) noexcept {
    output.clear();
    if(trail_points)trail_points->clear();
    const auto fail = [&](const char* reason) {
        output.clear();
        if(trail_points)trail_points->clear();
        static bool reported = false;
        if (!reported) {
            reported = true;
            append_bridge_event("ground_cover_footprints_rejected", reason, true);
        }
        return false;
    };
    // g_visual_game_image is installed only after the supported binary and
    // visual-publication contracts pass. No reads of an unverified executable.
    if (!ground_cover_marker_contract())
        return fail("supported footprint creation/fade contract unavailable; ground cover omitted");
    refresh_cover_marker_epoch();
    std::int32_t tick=0;double time=0;
    if(!read_owned_world_time(g_visual_game_image,time)||!visual_read(g_visual_game_image,world_clock_contract().ticks_rva,tick))
        return fail("footprint clock unreadable; ground cover omitted");
    std::int32_t enabled = 0;
    const auto setting_rva = running_game_sites().report.engine == GameEngine::lia
        ? kLiaFootprintEnabledRva : 0x0039bd4cu;
    if (!visual_read(g_visual_game_image, setting_rva, enabled))
        return fail("footprint setting unreadable; ground cover omitted");
    if (!enabled) { // The verified native draw gate also controls existing prints.
        while(!g_cover_markers.empty()&&g_cover_markers.begin()->first.first<=tick)
            g_cover_markers.erase(g_cover_markers.begin());
        return true;
    }

    const void* world = g_visual_game_image + world_clock_contract().client_rva;
    const void* head = nullptr;
    std::array<const void*,2> ends{};
    if (!visual_read(world, 0x1bc, head) || !head || !visual_read(head, 0, ends) || !ends[0] || !ends[1])
        return fail("footprint sentinel unreadable; ground cover omitted");
    // STLport list has no stored count: begin/end at 0056E1A0/0056E1B0,
    // insertion at 0056EED0 and inline object construction at 0056F940.
    // Count through the sentinel with backlinks checked. A cycle excluding
    // the sentinel necessarily fails a backlink when it revisits a node.
    std::size_t count = 0;
    const void* previous = head;
    const void* node = ends[0];
    while (node != head) {
        std::array<const void*,2> links{};
        if (!node || !visual_read(node, 0, links) || !links[0] || links[1] != previous)
            return fail("footprint list links inconsistent; ground cover omitted");
        if (count == output.max_size())
            return fail("footprint list exceeds addressable snapshot storage; ground cover omitted");
        ++count;
        previous = node; node = links[0];
    }
    if (previous != ends[1])
        return fail("footprint sentinel tail inconsistent; ground cover omitted");
    try { if (count > output.capacity()) output.reserve(count); }
    catch (...) { return fail("footprint snapshot allocation failed; ground cover omitted"); }

    previous = head; node = ends[0];
    for (std::size_t i = 0; i < count; ++i) {
        std::array<const void*,2> links{};
        std::uint8_t visible = 0;
        const void* table = nullptr;
        // The footprint is INLINE at node+8, not a pointer stored there.
        if (!node || node == head || !visual_read(node, 0, links) || !links[0] || links[1] != previous ||
            !visual_read(node, 8, table) || table != g_visual_game_image + ground_cover_marker_vtable_rva() ||
            !visual_read(node, 8 + 5, visible))
            return fail("footprint object or list changed during read; ground cover omitted");
        if (visible) {
            CoverMarkerKey key{};float alpha=0;
            if(!read_cover_marker(node,tick,false,key,visible,alpha))
                return fail("visible footprint geometry or lifetime invalid; ground cover omitted");
            const auto found=g_cover_markers.find(key);
            if(found!=g_cover_markers.end()) {
                auto& created=found->second;
                if(!created.captured) {
                    // Resolve body size once from the same authoritative owned
                    // sample that presses cover in this first rendered frame.
                    // Keep the creation-time body centre, never the offset foot
                    // texture centre or the owner's later position/size.
                    created.captured=true;
                    const auto& frame=g_owned_visual_world_frame;
                    if(frame.active&&frame.values)for(const auto& unit:frame.values->entities){
                        if(unit.resource.serial!=created.creator.serial||
                           unit.resource.signed_id!=created.creator.signed_id)continue;
                        if(unit.height_valid&&retained_visual_sample_shown(unit,frame.draw_undetected_units)&&
                           !unit.values.dead&&!unit.values.invisible)
                            created.stamp=ground_cover::live_unit_splat(created.stamp.rectangle[0],
                                created.stamp.rectangle[1],unit.envelope_radius);
                        break;
                    }
                }
                std::int32_t fade=0;
                if(!visual_read(node,8+0x58,fade)||fade<=0)
                    return fail("visible footprint fade duration invalid; ground cover omitted");
                const auto visibility=ground_cover::footprint_visibility(double(key.first)-time,fade);
                const auto splat=ground_cover::footprint_splat(true,created.stamp,visibility);
                // Keep a zero-alpha marker's coverage until native expiry so
                // the residual recovery floor cannot reappear at the endpoint.
                if(created.stamp.effect[2]>0)output.push_back(splat);
                if(trail_points&&created.walks&&visibility>0)try{
                    trail_points->push_back({snow_trail_key(created.creator),created.tick,
                        created.stamp.rectangle[0],created.stamp.rectangle[1],created.half_extent});
                }catch(...){trail_points->clear();trail_points=nullptr;} // trails omit hidden makers this frame
            } else {
                static bool reported=false;
                if(!reported){reported=true;append_bridge_event("ground_cover_marker_omitted",
                    "footprint has no shown creator stamp (including loaded prints); marker omitted",true);}
            }
        }
        previous = node; node = links[0];
    }
    const void* final_head = nullptr;
    std::array<const void*,2> final_ends{};
    if (node != head || previous != ends[1] || !visual_read(world, 0x1bc, final_head) || final_head != head ||
        !visual_read(head, 0, final_ends) || final_ends != ends)
        return fail("footprint list termination changed during read; ground cover omitted");
    // Native removal happens at the integer expiry. Publish the final zero
    // target once before releasing metadata, so the old GPU value cannot
    // survive the disappearance of a short-lived marker's coverage.
    try {
        while(!g_cover_markers.empty()&&g_cover_markers.begin()->first.first<=tick){
            const auto& created=g_cover_markers.begin()->second;
            if(created.captured&&created.stamp.effect[2]>0)
                output.push_back(ground_cover::footprint_splat(true,created.stamp,0));
            g_cover_markers.erase(g_cover_markers.begin());
        }
    } catch(...) {return fail("expired footprint endpoint allocation failed; ground cover omitted");}
    return true;
}
#endif // !EID3D11_EMBEDDED

} // namespace

