namespace {
void complete_hovered_shadow_capture() noexcept {
    // Present only requests this; read while the completed world still owns its borrows.
    const auto& frame=g_owned_visual_world_frame;
    const auto target=frame.observed_hover;
    char detail[768]{};
    if(!frame.active || !frame.values || !target.signed_id) {
        append_bridge_event("hovered_shadow_capture","No completed world frame or current hover target; hover the affected corpse with object highlighting enabled.",false);return;
    }
    const auto found=std::find_if(frame.values->entities.begin(),frame.values->entities.end(),[&](const auto& sample){
        return sample.resource.signed_id==target.signed_id && sample.resource.serial==target.serial;
    });
    if(found==frame.values->entities.end()) {
        std::snprintf(detail,sizeof(detail),"frame=%llu id=%d resource=%llu sample=absent",frame.serial,target.signed_id,target.serial);
        append_bridge_event("hovered_shadow_capture",detail,false);return;
    }
    const auto index=std::size_t(found-frame.values->entities.begin());const auto& sample=*found;
    const auto& prepared=frame.prepared[index];
    const bool receipt_matches=frame.observed_hover.signed_id==target.signed_id && frame.observed_hover.serial==target.serial;
    unsigned published_mask=0;
    for(unsigned slice=0;slice<frame.shadows.slices.size();++slice)
        for(const auto& caster:frame.shadows.slices[slice].validity)
            if(!caster.terrain && caster.signed_id==target.signed_id && caster.resource==target.serial)published_mask|=1u<<slice;
    std::snprintf(detail,sizeof(detail),
        "frame=%llu id=%d resource=%llu membership=%llu world=%llu status=%u reason=%s unit=%u dead=%u hidden=%u flags=0x%08x fade=%.4f effect_alpha=%.4f casts=%u claimed=%u color_submitted=%u static_reused=%u light_mask=0x%02x casting_parts=%llu published_mask=0x%02x shadows_enabled=%u attempted=%u ready=%u dirty=0x%02x retained=0x%02x scroll=0x%02x receipt_matches=%u accepted_sun_selections=%u accepted_sun_mask=0x%02x",
        frame.serial,target.signed_id,target.serial,sample.lifecycle.generation,sample.lifecycle.positive_world_epoch,
        unsigned(sample.status),sample.readiness_reason?sample.readiness_reason:"none",unsigned(sample.values.unit),unsigned(sample.values.dead),
        unsigned(sample.values.hidden),sample.values.object_flags,sample.values.fade_alpha,sample.effects.opacity,unsigned(sample.visibility.casts_shadow),
        unsigned(prepared.claimed),unsigned(prepared.submitted),unsigned(prepared.static_reused),unsigned(prepared.contribution.light_mask),prepared.casting_parts,
        published_mask,unsigned(frame.shadows_enabled),unsigned(frame.shadow_attempted),unsigned(frame.shadow_ready),unsigned(frame.shadow_source_diagnostic.dirty_mask),
        unsigned(frame.observed_retained_mask),unsigned(frame.observed_scroll_mask),unsigned(receipt_matches),
        receipt_matches?frame.observed_sun_selections:0u,receipt_matches?unsigned(frame.observed_sun_mask):0u);
    append_bridge_event("hovered_shadow_capture",detail,false);
    for(std::size_t part=0;part<prepared.parts.size();++part) {
        const auto& value=prepared.parts[part];
        const float alpha=sample.assembly && part<sample.assembly->parts.size()?retained_visual_effective_alpha(sample,sample.assembly->parts[part]):-1.f;
        std::snprintf(detail,sizeof(detail),"frame=%llu id=%d part=%zu alpha=%.4f ready=%u visible=%u casts=%u color_admitted=%u bounds_valid=%u light_mask=0x%02x depth_revision=%llu",
            frame.serial,target.signed_id,part,alpha,unsigned(value.ready_serial==frame.serial),unsigned(value.visible),unsigned(value.casts),unsigned(value.color_admitted),
            unsigned(value.bounds.valid),unsigned(value.contribution.light_mask),value.depth_revision.revision);
        append_bridge_event("hovered_shadow_part",detail,false);
    }
    for(std::size_t candidate=prepared.candidate_begin;candidate<prepared.candidate_end;++candidate) {
        const auto part=frame.candidates[candidate].part;
        std::snprintf(detail,sizeof(detail),"frame=%llu id=%d depth_candidate=%zu merged=%u",frame.serial,target.signed_id,part,unsigned(part>=kMergedPartBase));
        append_bridge_event("hovered_shadow_candidate",detail,false);
    }
}
} // namespace


