#if !defined(EID3D11_EMBEDDED)
bool bridge_consume_hud_atlas_window(
    IDirectDrawSurface7* surface, const void* lock_caller,
    HudAtlasMutationWindow& window) noexcept {
    window = {};
    if (!g_hud_atlas_hooks_installed || !surface) return false;
    const HudAtlasProducerContext context = g_hud_atlas_producer;
    bool eligible = false;
    if (g_addon_hud_atlas_lock_pending) {
        g_addon_hud_atlas_lock_pending = false;
        eligible = context.kind == HudAtlasProducerKind::addon &&
            !context.consumed;
    } else if (context.kind == HudAtlasProducerKind::stock &&
               !context.consumed &&
               g_hud_atlas_game_image &&
               reinterpret_cast<std::uintptr_t>(lock_caller) ==
                   reinterpret_cast<std::uintptr_t>(g_hud_atlas_game_image) +
                       kStockHudAtlasSurfaceLockReturnRva) {
        eligible = true;
    }
    if (eligible) g_hud_atlas_producer.consumed = true;
    if (!eligible ||
        current_texture_surface(context.destination_texture) != surface)
        return false;
    window = context.window;
    return true;
}

// Raster scale for the character pane [0] and chat lines [1]: the vertical
// scale each source's own blit composed at, read on the game thread from the
// composition that blit used (in core mode the drawing side is another
// process, and one shared value let pane and chat retune each other). Held
// while the composed scale stays within the renderer's 1:1 tolerance and
// quantised to 1/256, so hair-sized changes keep one raster size.
float g_owned_text_raster[2] = {};
void hold_owned_text_raster(int index, const Renderer& renderer, const RECT& destination,
                            const RECT* source_rect, std::uint32_t width, std::uint32_t height) noexcept {
    const RECT source = source_rect ? *source_rect : RECT{0, 0, LONG(width), LONG(height)};
    const float composed = renderer.owned_text_composed_scale(destination, source);
    float& held = g_owned_text_raster[index];
    if (!(composed > 0.f) ||
        (held > 0.f && std::fabs(composed - held) <= held * Renderer::kOwnedTextScaleTolerance * 0.5f))
        return;
    held = std::round(composed * 256.f) / 256.f;
}

bool bridge_begin_character_pane_getdc(
    IDirectDrawSurface7* surface, const void* caller,
    std::uint64_t surface_id, std::uint32_t width,
    std::uint32_t height, float raster_scale) noexcept {
    auto* invocation = current_character_pane_text_invocation();
    const bool caller_matches = g_character_pane_game_image &&
        reinterpret_cast<std::uintptr_t>(caller) ==
            reinterpret_cast<std::uintptr_t>(g_character_pane_game_image) +
                character_pane_contract().getdc_return;
#ifdef EID3D11_TESTING
    const bool admitted_caller = caller_matches ||
        g_character_pane_proxy_test_mode;
#else
    const bool admitted_caller = caller_matches;
#endif
    // A claimed card session owns the text builder until its ReleaseDC.
    if (g_item_card_session.claimed || !admitted_caller) return false;
    if (!invocation || !invocation->armed || invocation->claimed ||
        invocation->released ||
        (!invocation->chat && invocation->surface != surface) ||
        !surface || !surface_id)
        return begin_item_card_getdc(surface, surface_id, width, height,
                                     raster_scale);
    const std::uint64_t generation =
        g_character_pane_font_generation.load(std::memory_order_acquire);
    if (!generation) return false;
    g_character_pane_text.initialize_fonts(generation);
    if (invocation->chat) invocation->surface = surface;
    invocation->surface_id = surface_id;
    invocation->claimed = true;
    // The scale this source's own last blit composed at; the renderer's
    // composition guess only before its first blit.
    const float held = g_owned_text_raster[invocation->chat ? 1 : 0];
    if (held > 0.f) raster_scale = held;
    g_character_pane_text.begin_frame(width, height, raster_scale);
    return true;
}

bool bridge_finish_character_pane_releasedc(
    IDirectDrawSurface7* surface, const void* caller,
    std::uint64_t surface_id, std::uint64_t surface_generation) noexcept {
    auto* invocation = current_character_pane_text_invocation();
    const bool caller_matches = g_character_pane_game_image &&
        reinterpret_cast<std::uintptr_t>(caller) ==
            reinterpret_cast<std::uintptr_t>(g_character_pane_game_image) +
                character_pane_contract().releasedc_return;
#ifdef EID3D11_TESTING
    const bool admitted_caller = caller_matches ||
        g_character_pane_proxy_test_mode;
#else
    const bool admitted_caller = caller_matches;
#endif
    if (g_item_card_session.claimed && !g_item_card_session.released &&
        g_item_card_session.surface == surface &&
        g_item_card_session.surface_id == surface_id) {
        finish_item_card_releasedc(admitted_caller, surface_generation);
        return true;
    }
    if (!invocation || !invocation->claimed || invocation->released ||
        invocation->surface != surface ||
        invocation->surface_id != surface_id)
        return false;
    invocation->released = true;
    g_character_pane_text.finish_dc(admitted_caller);
    if (invocation->chat) {
        // Publish this line now; NewPhrase may claim the next line surface.
        const CharacterPaneTextFailure failure =
            g_character_pane_text.failure();
        CharacterPaneTextFrame frame{};
        const bool published = g_character_pane_text.take(frame) &&
            g_chat_text_frames.publish(
                surface_id, surface_generation, std::move(frame));
        g_character_pane_text.abort_frame();
        if (published && !g_chat_text_ui_epoch) {
            std::uint64_t epoch = g_character_pane_next_ui_epoch.fetch_add(
                1u, std::memory_order_acq_rel);
            if (!epoch)
                epoch = g_character_pane_next_ui_epoch.fetch_add(
                    1u, std::memory_order_acq_rel);
            g_chat_text_ui_epoch = epoch;
        }
        if (!published) {
            g_chat_text_frames.retire(surface_id);
            report_chat_text_failure(
                failure == CharacterPaneTextFailure::none
                    ? CharacterPaneTextFailure::dc_transaction : failure);
        }
        invocation->surface = nullptr;
        invocation->surface_id = 0;
        invocation->claimed = false;
        invocation->released = false;
    }
    return true;
}
#endif // !EID3D11_EMBEDDED

#if !defined(EID3D11_EMBEDDED)
void bridge_item_card_text_describe(void* panel,
                                    void (__thiscall* describe)(void*)) {
    item_card_text_describe(panel, describe);
}

#endif // !EID3D11_EMBEDDED
void bridge_retire_owned_text_surface(std::uint64_t surface_id) noexcept {
    g_chat_text_frames.retire(surface_id);
    g_item_card_text_frames.retire(surface_id);
    g_item_card_surfaces.erase(surface_id);
    if (g_item_card_session.surface_id == surface_id) {
        g_character_pane_text.abort_frame();
        g_item_card_session = {};
    }
}

#if !defined(EID3D11_EMBEDDED)
bool bridge_consume_character_pane_blt(
    IDirectDrawSurface7* source_surface, std::uint64_t source_id, const void* caller,
    const RECT& destination, const RECT* source_rect,
    Renderer& renderer, HRESULT& result,
    std::uint64_t source_generation) noexcept {
    result = DD_OK;
    if (!source_id) return false;
    const bool pane_source = g_character_pane_text_publication.valid &&
        g_character_pane_text_publication.surface_id == source_id;
    const bool card_source = !pane_source && g_item_card_text_frames.size() &&
        g_item_card_surfaces.count(source_id);
    if (!pane_source && !card_source &&
        (!g_chat_draw_depth || !g_chat_text_frames.size()))
        return false;
    const std::uintptr_t return_address =
        reinterpret_cast<std::uintptr_t>(caller);
    const std::uintptr_t image =
        reinterpret_cast<std::uintptr_t>(g_character_pane_game_image);
    const bool native_draw_source = source_surface &&
        g_character_pane_surface_draw_self &&
        interface_dd_surface(g_character_pane_surface_draw_self) == source_surface;
    const bool caller_matches = native_draw_source ||
        (g_character_pane_game_image &&
         (return_address == image + character_pane_contract().keyed_blt_return ||
          return_address == image + character_pane_contract().unkeyed_blt_return));
#ifdef EID3D11_TESTING
    const bool admitted_caller = caller_matches ||
        g_character_pane_proxy_test_mode;
#else
    const bool admitted_caller = caller_matches;
#endif
    if (!admitted_caller)
        return false;
    if (card_source) {
        // Item card presented by CI3DSurface::Draw (camp pieces included).
        const CharacterPaneTextFrame* frame = nullptr;
        const auto lookup =
            g_item_card_text_frames.find(source_id, source_generation, frame);
        if (lookup == RetainedOwnedTextFrames::Lookup::stale ||
            (lookup == RetainedOwnedTextFrames::Lookup::ready &&
             !g_item_card_text_ui_epoch)) {
            // Written outside an owned DC after publication: omit the card.
            report_item_card_text_failure(CharacterPaneTextFailure::dc_transaction);
            return true;
        }
        if (lookup == RetainedOwnedTextFrames::Lookup::ready) {
            const auto adopted = g_item_card_surfaces.find(source_id);
            // The frame records more rows than the surface has: its blit
            // shows the surface rows, and a block laid out past them is
            // placed smaller until all of it fits; no line is left out.
            const std::uint32_t rows = adopted != g_item_card_surfaces.end() && adopted->second.height
                ? adopted->second.height : frame->height / kItemCardRecordRows;
            const RECT surface_rect{0, 0, LONG(frame->width), LONG(rows)};
            CharacterPaneTextFit fit{};
            const bool fitted = fit_retained_text_frame(*frame, rows, fit);
            float composed_scale = 0.f;
            result = renderer.queue_retained_owned_text(
                *frame, g_item_card_text_ui_epoch, g_bridge_frame_serial,
                destination, source_rect ? source_rect : &surface_rect, composed_scale,
                fitted ? &fit : nullptr);
            if (FAILED(result))
                report_item_card_text_failure(CharacterPaneTextFailure::submission);
            if (composed_scale > 0.f && adopted != g_item_card_surfaces.end())
                adopted->second.scale = composed_scale * (fitted ? fit.scale : 1.f);
            return true;
        }
    }
    if (!pane_source) {
        if (!g_chat_draw_depth || !g_chat_text_frames.size()) return false;
        // Chat line presented by CI3DChat::Draw2D through CI3DSurface::Draw.
        const CharacterPaneTextFrame* frame = nullptr;
        const auto lookup =
            g_chat_text_frames.find(source_id, source_generation, frame);
        if (lookup == RetainedOwnedTextFrames::Lookup::absent) return false;
        if (lookup == RetainedOwnedTextFrames::Lookup::stale ||
            !g_chat_text_ui_epoch) {
            // Written outside the owned DC after publication: omit the line.
            report_chat_text_failure(CharacterPaneTextFailure::dc_transaction);
            return true;
        }
        hold_owned_text_raster(1, renderer, destination, source_rect, frame->width, frame->height);
        result = renderer.queue_character_pane_text(
            *frame, g_chat_text_ui_epoch, g_bridge_frame_serial,
            destination, source_rect);
        if (FAILED(result))
            report_chat_text_failure(CharacterPaneTextFailure::submission);
        return true;
    }
    CharacterPaneTextPublication publication =
        std::move(g_character_pane_text_publication);
    g_character_pane_text_publication = {};
    if (publication.ui_epoch != g_character_pane_ui_epoch ||
        publication.frame_serial != g_bridge_frame_serial ||
        !publication.complete) {
        report_character_pane_text_failure(
            publication.failure == CharacterPaneTextFailure::none
                ? CharacterPaneTextFailure::dc_transaction
                : publication.failure);
        return true;
    }
    hold_owned_text_raster(0, renderer, destination, source_rect,
                           publication.frame.width, publication.frame.height);
    result = renderer.queue_character_pane_text(
        publication.frame, publication.ui_epoch,
        publication.frame_serial, destination, source_rect);
    if (FAILED(result))
        report_character_pane_text_failure(
            CharacterPaneTextFailure::submission);
    return true;
}

bool bridge_character_pane_text_epoch_current(
    std::uint64_t ui_epoch, std::uint64_t frame_serial) noexcept {
    return g_character_pane_hooks_installed && ui_epoch &&
        (ui_epoch == g_character_pane_ui_epoch ||
         ui_epoch == g_chat_text_ui_epoch ||
         ui_epoch == g_item_card_text_ui_epoch) &&
        frame_serial == g_bridge_frame_serial;
}
#endif // !EID3D11_EMBEDDED

#if !defined(EID3D11_EMBEDDED)
// The pane's effect list: the latest pane draw's list stays current for two
// frames, as the game does not redraw the pane every frame (save "regen":
// every other frame), so an exact frame match left the list empty on the
// frames between (flicker).
bool bridge_character_pane_list_current(
    std::uint64_t ui_epoch, std::uint64_t frame_serial) noexcept {
    return g_character_pane_hooks_installed && ui_epoch && ui_epoch == g_character_pane_ui_epoch &&
        frame_serial <= g_bridge_frame_serial && g_bridge_frame_serial - frame_serial <= 2;
}

const char* figure_fallback_reason_name(FigureFallbackReason reason) noexcept {
    switch (reason) {
    case FigureFallbackReason::none: return "none";
    case FigureFallbackReason::unavailable: return "unavailable";
    case FigureFallbackReason::hidden: return "hidden";
    case FigureFallbackReason::renderer_state: return "renderer state";
    case FigureFallbackReason::transform: return "transform";
    case FigureFallbackReason::material: return "material";
    case FigureFallbackReason::light_array: return "light array";
    case FigureFallbackReason::morph_data: return "morph data";
    case FigureFallbackReason::geometry: return "geometry";
    case FigureFallbackReason::metadata: return "metadata";
    case FigureFallbackReason::state_write: return "state write";
    case FigureFallbackReason::direct_submit: return "direct submit";
    case FigureFallbackReason::exception: return "exception";
    default: return "unknown";
    }
}
#endif // !EID3D11_EMBEDDED

