bool EngineBridge::install() {
    if (installed_) return true;
    g_features_off = 0;
    g_addon_notice[0] = '\0';
    configure_startup_diagnostics();
    const bool traced = startup_begin(StartupStage::hooks);
    image_ = GetModuleHandleW(nullptr);
    // Feature gates are per-site expected bytes (game_sites.h); the exe hash
    // is logged only to identify the build in reports.
    const auto& sites = running_game_sites();
    sites_verified_ = sites.report.ok(GameSiteGroup::bridge);
    {
        char detail[512];
        int used = std::snprintf(detail, sizeof(detail), "sha256=%s layout=%s failed_sites=%zu",
                                 sites.sha256, sites.report.layout ? "ok" : "mismatch",
                                 sites.report.failed_count);
        for (std::size_t group = 0; group < kGameSiteGroupCount && used > 0 &&
                 static_cast<std::size_t>(used) < sizeof(detail); ++group)
            used += std::snprintf(detail + used, sizeof(detail) - used, " %s=%s",
                                  game_site_group_name(static_cast<GameSiteGroup>(group)),
                                  sites.report.ok(static_cast<GameSiteGroup>(group)) ? "ok" : "failed");
        for (std::size_t index = 0; index < sites.report.failed_count &&
                 index < sites.report.failed_rvas.size() && used > 0 &&
                 static_cast<std::size_t>(used) < sizeof(detail); ++index)
            used += std::snprintf(detail + used, sizeof(detail) - used, "%s%06x",
                                  index ? "," : " rvas=", sites.report.failed_rvas[index]);
        report("game_image_sites", detail);
    }
    // No budget depends on this yet; it is logged so VA reports can be read.
    report("game_image_address_space", running_image_large_address_aware() ?
               "large_address_aware_4gb" : "not_large_address_aware_2gb");
    if (!sites_verified_) {
        report("bridge_rejected", "bridge_site_bytes_mismatch");
        startup_end(StartupStage::hooks, traced, "bridge_site_bytes_mismatch");
        return false;
    }
    auto* const image = reinterpret_cast<std::uint8_t*>(image_);
    if (!install_engine_frame_begin_hook(image)) {
        report("bridge_rejected", "required_frame_call_mismatch_or_write_failure");
        startup_end(StartupStage::hooks, traced, "required_frame_call_rejected");
        return false;
    }
    installed_ = patch_slots();
    // patch_slots validates every slot before changing any of them. If it
    // rejects, undo just the required call; retain its owner only for a failed
    // restore so uninstall can retry even without installed semantic slots.
    if (!installed_ && !uninstall_engine_frame_begin_hook())
        report("engine_frame_begin_uninstall_pending", "slot_activation_failed_call_restore_failed");
    report(installed_ ? "bridge_installed" : "bridge_rejected",
           installed_ ? "verified_semantic_slots_and_required_frame_call" : "slot_signature_mismatch");
    if (installed_) {
        // Frame accounting does not request these game-loop hooks (issue
        // #161); it marks game_sim/game_loop/game_ui_idle/game_end_frame
        // only when the F11 gap profile or camp observation installs them.
        const bool outer_frame_timing_requested =
            outer_frame_gap_profile_requested() || camp_inventory_observation_enabled();
        const bool outer_frame_timing_installed =
            outer_frame_timing_requested && install_outer_frame_timing_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
        report(outer_frame_timing_installed ?
                   "outer_frame_timing_installed" :
                   "outer_frame_timing_inactive",
               !outer_frame_timing_requested ? "disabled" :
               outer_frame_timing_installed ?
                   "verified_loop_calls_and_calling_conventions" :
                   "callsite_target_or_patch_transaction_mismatch");
        const bool hud_atlas_installed = install_hud_atlas_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(hud_atlas_installed ? "hud_atlas_mutation_installed" :
                                     "hud_atlas_mutation_rejected",
               g_hud_atlas_install_detail);
        // Missed cache Releases for addon-served resource data are routed to
        // their owning instance; a contract mismatch leaves the game unchanged.
        auto* res_cache_addon = find_addon_module();
        const bool res_cache_sites = game_sites_ok(GameSiteGroup::res_cache);
        const bool res_cache_release_installed = res_cache_sites && install_res_cache_release_hooks(
            reinterpret_cast<std::uint8_t*>(image_), res_cache_addon,
            res_cache_addon && !g_addon.layout.res_cache_failure ?
                &g_addon.layout.res_cache : nullptr);
        report(res_cache_release_installed ? "res_cache_release_installed" :
                                             "res_cache_release_rejected",
               // Without an addon there is no private cache to route to
               // (vanilla and LiA): nothing to install, whatever the sites.
               !res_cache_addon ? "addon_missing" :
               res_cache_sites ? res_cache_release_status_name(res_cache_release_snapshot().status)
                               : "site_bytes_mismatch");
        const bool owned_cursor_installed = install_owned_cursor_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        const bool stats_throttle_installed = install_character_pane_stats_throttle(
            reinterpret_cast<std::uint8_t*>(image_));
        report(stats_throttle_installed ? "character_pane_stats_throttle_installed" :
               g_addon.image ? "character_pane_stats_throttle_rejected" :
                               "character_pane_stats_throttle_inactive",
               stats_throttle_installed ? "verified_stats_call_site" :
               g_addon.image ? "stats_call_site_mismatch" : "stock_stats_cadence");
        report(owned_cursor_installed ? "owned_cursor_installed" : "owned_cursor_rejected",
               owned_cursor_installed ? "verified_draw_thread_restore_entries" :
                                        "cursor_entry_bytes_mismatch_game_draws_cursor");
        const bool highlight_installed = install_highlight_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(highlight_installed ? "hover_highlight_installed" : "hover_highlight_rejected",
               highlight_installed ? "verified_cursor_decision_call_sites" :
                                     "cursor_decision_call_site_mismatch_no_hover_highlight");
        const bool modal_backdrop_installed = install_modal_backdrop_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(modal_backdrop_installed ? "modal_backdrop_installed" : "modal_backdrop_rejected",
               modal_backdrop_installed ? "verified_fade_thumbnail_and_reader_sites" :
                                          "site_mismatch_game_fades_and_stretches_on_cpu");
        const bool camera_mouse_yaw_installed = install_camera_mouse_yaw_hook(
            reinterpret_cast<std::uint8_t*>(image_));
        const bool camera_mouse_pitch_installed = camera_mouse_yaw_installed &&
            install_camera_mouse_pitch_hook(
                reinterpret_cast<std::uint8_t*>(image_));
        if (!camera_mouse_pitch_installed && camera_mouse_yaw_installed)
            uninstall_camera_mouse_yaw_hook(
                reinterpret_cast<std::uint8_t*>(image_));
        const bool camera_mouse_rotation_installed =
            camera_mouse_yaw_installed && camera_mouse_pitch_installed;
        report(camera_mouse_rotation_installed ?
                   "camera_mouse_rotation_installed" :
                   "camera_mouse_rotation_rejected",
               camera_mouse_rotation_installed ?
                   "verified_displacement_consumers_and_limits" :
                   "yaw_or_pitch_callsite_or_owner_mismatch");
        const bool hit_test_installed = install_global_map_hit_test_hook(
            reinterpret_cast<std::uint8_t*>(image_));
        report(hit_test_installed ? "zone_hit_test_installed" : "zone_hit_test_rejected",
               hit_test_installed ? "verified_generate_hit_test_call" :
                                    "hit_test_call_or_entry_mismatch_mask_is_normal_frame");
        const bool camera_mouse_normalize_installed =
            install_camera_mouse_normalize_hook(
                reinterpret_cast<std::uint8_t*>(image_));
        report(camera_mouse_normalize_installed ?
                   "camera_mouse_remainder_installed" :
                   "camera_mouse_remainder_rejected",
               camera_mouse_normalize_installed ?
                   "verified_displacement_normalization_call" :
                   "normalization_callsite_mismatch_small_moves_truncated");
        const bool game_particles_installed = install_game_particle_hook(
            reinterpret_cast<std::uint8_t*>(image_));
        report(game_particles_installed ? "game_particles_installed" : "game_particles_rejected",
               game_particles_installed ? "verified_draw_particles_slot_gpu_billboards" :
                                          "draw_particles_slot_or_entry_mismatch_game_draws_particles");
        const bool particle_source_installed = game_particles_installed &&
            install_particle_source_hook(reinterpret_cast<std::uint8_t*>(image_));
        report(particle_source_installed ? "particle_source_installed" : "particle_source_rejected",
               particle_source_installed ? "verified_particle_type_carried_to_host" :
                   "unverified_source_call_or_layout_particle_lamps_omitted");
        bool game_effect_sites=true;
        if (running_game_sites().report.engine==GameEngine::lia)
            for (const auto& range:kLiaOwnedEffectRanges)
                if (!lia_live_contract_range_matches(reinterpret_cast<const std::uint8_t*>(image_),
                        static_cast<std::uint32_t>(range[0]),static_cast<std::size_t>(range[1]),range[2])) {
                    game_effect_sites=false; break;
                }
        // Effects also witness the stock view publication body. Complete
        // that preflight before replacing its optional camera-pan call.
        const bool camera_pan_installed = install_camera_pan_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(camera_pan_installed ? "camera_pan_smoothing_installed" :
                                      "camera_pan_smoothing_rejected",
               camera_pan_installed ? "experimental_displayed_xy_only_default_off" :
                   bridge_camera_pan_smoothing_unavailable_reason());
        const bool game_lightning_installed = game_effect_sites && install_game_ribbon_hook(
            reinterpret_cast<std::uint8_t*>(image_));
        report(game_lightning_installed ? "game_lightning_installed" : "game_lightning_rejected",
               game_lightning_installed ? "verified_draw_3d_line_slot_gpu_ribbons" :
                                          "draw_3d_line_slot_or_entry_mismatch_game_draws_lightning");
        const bool game_selection_installed = game_effect_sites && install_game_selection_hook(
            reinterpret_cast<std::uint8_t*>(image_));
        report(game_selection_installed ? "game_selection_marker_installed" : "game_selection_marker_rejected",
               game_selection_installed ? "verified_draw_selection_call_gpu_marker" :
                                          "draw_selection_call_or_entry_mismatch_game_draws_marker");
        const bool game_prints_installed = game_effect_sites && install_game_print_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(game_prints_installed ? "game_prints_installed" : "game_prints_rejected",
               game_prints_installed ? "verified_print_list_pushes_and_render_call_gpu_prints" :
                                       "print_push_render_call_or_entry_mismatch_game_draws_prints");
#ifndef EID3D11_EMBEDDED
        const bool game_render_entry_installed = install_game_render_entry_hook(reinterpret_cast<std::uint8_t*>(image_));
        report(game_render_entry_installed ? "game_render_entry_installed" : "game_render_entry_rejected",
               game_render_entry_installed ? "verified_render_entry_other_modules_gpu_prints" :
                                             "render_entry_mismatch_or_no_prints_other_modules_draw_legacy");
        const bool combat_text_installed = install_combat_text_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(combat_text_installed ? "combat_text_installed" : "combat_text_rejected",
               combat_text_installed ? (g_combat_text_addon_layout ? "verified_call_addon_draw_chain_bypassed_addon_layout_game_time" :
                                        "verified_flying_hp_call_and_receive_clock_gpu_glyphs_game_time") :
                                       "flying_hp_call_entry_or_receive_clock_mismatch_game_draws_combat_text");
#endif
        const bool owned_sky_installed = install_owned_sky_hook(
            reinterpret_cast<std::uint8_t*>(image_));
        report(owned_sky_installed ? "owned_sky_installed" : "owned_sky_rejected",
               owned_sky_installed ? "verified_sky_draw_call" :
                                     g_owned_sky_gate_valid ? "sky_hook_rejected_stock_sky_omitted" :
                                     "sky_hook_and_gate_rejected_world_omitted");
        const bool owned_weather_installed = install_owned_weather_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(owned_weather_installed ? "owned_weather_installed" : "owned_weather_rejected",
               owned_weather_installed ? "verified_draw_rain_and_draw_snow_calls" : g_owned_weather_status.load());
        const bool owned_frame_selection_installed =
            install_owned_frame_selection_hook(
                reinterpret_cast<std::uint8_t*>(image_));
        report(owned_frame_selection_installed ?
                   "owned_frame_selection_installed" :
                   "owned_frame_selection_rejected",
               owned_frame_selection_installed ?
                   "verified_stock_entry_and_six_slot_epilogues" :
                   "entry_or_epilogue_mismatch_live_detour_unowned");
        bool native_installed = false;
        bool terrain_installed = false;
        bool object_lighting_installed = false;
        if (native_tl_requested()) {
            native_installed = install_native_geometry_hook(
                reinterpret_cast<std::uint8_t*>(image_));
            report(native_installed ? "native_tl_installed" : "native_tl_rejected",
                   native_installed ? "verified_object_space_entry" : "entry_signature_or_allocation");
            terrain_installed = native_installed && install_terrain_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
            report(terrain_installed ? "native_terrain_installed" : "native_terrain_rejected",
                   terrain_installed ? "verified_sector_object_space_entries" :
                       (g_terrain_set_light_cleanup_pending
                            ? "relight_call_rollback_pending"
                            : "entry_signature_or_allocation"));
        }
        if (native_installed || retained_static_runtime_requested()) {
            object_lighting_installed = install_object_lighting_hook(
                reinterpret_cast<std::uint8_t*>(image_));
            report(object_lighting_installed ?
                       "native_object_lighting_installed" :
                       "native_object_lighting_rejected",
                   object_lighting_installed ?
                       (g_object_lighting_chained ?
                            "verified_chained_live_object_scope" :
                            "verified_live_object_scope") :
                       "entry_signature_or_allocation");
        }
        const bool scene_profile_installed = install_scene_profile_hooks(
            reinterpret_cast<std::uint8_t*>(image_));
        report(scene_profile_installed ? "scene_profile_installed" :
                                         "scene_profile_rejected",
               scene_profile_installed ?
                   (g_scene_profile_chained ? "verified_world_and_chained_scene_detour" :
                                              "verified_world_and_scene_entries") :
                                         "entry_signature_or_allocation");
        const bool object_plan_prerequisites =
            native_installed && object_lighting_installed &&
            scene_profile_installed;
        bool object_plan_installed = false;
        bool object_suffix_cut_installed = false;
        if (object_plan_prerequisites) {
            auto& observer = lifecycle_observer();
            observer.reset();
            const bool draw_oracle_validated =
                world_object_draw_oracle_is_exact(
                    reinterpret_cast<std::uint8_t*>(image_));
            const LifecycleValidation lifecycle_result = install_lifecycle_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
            const bool lifecycle_installed =
                lifecycle_result == LifecycleValidation::active;
            const bool mutation_installed = lifecycle_installed &&
                install_object_plan_mutation_hooks(
                    reinterpret_cast<std::uint8_t*>(image_));
            const bool visual_loop_installed = mutation_installed &&
                draw_oracle_validated && install_object_visual_loop_hook(
                    reinterpret_cast<std::uint8_t*>(image_));
            object_plan_installed = lifecycle_installed &&
                mutation_installed && visual_loop_installed &&
                draw_oracle_validated;
            if (object_plan_installed) {
                object_suffix_cut_installed =
                    install_object_suffix_cut_hook(
                        reinterpret_cast<std::uint8_t*>(image_), true);
                observer.set_runtime_status(
                    true, true, true, true, LifecycleValidation::active);
                g_lifecycle_observing.store(true, std::memory_order_release);
                g_lifecycle_draw_oracle.store(true,
                                              std::memory_order_release);
            } else {
                g_lifecycle_draw_oracle.store(false,
                                              std::memory_order_release);
                g_lifecycle_observing.store(false,
                                            std::memory_order_release);
                if (g_object_visual_loop_installed)
                    uninstall_object_visual_loop_hook(
                        reinterpret_cast<std::uint8_t*>(image_));
                const bool mutation_removed =
                    uninstall_object_plan_mutation_hooks(
                        reinterpret_cast<std::uint8_t*>(image_));
                if (mutation_removed && g_lifecycle_hooks_installed)
                    uninstall_lifecycle_hooks(
                        reinterpret_cast<std::uint8_t*>(image_));
            }
        } else if (lifecycle_probe_requested() ||
                   retained_static_runtime_requested()) {
            auto& observer = lifecycle_observer();
            observer.reset();
            const bool draw_oracle_validated =
                world_object_draw_oracle_is_exact(
                    reinterpret_cast<std::uint8_t*>(image_));
            const LifecycleValidation lifecycle_result =
                install_lifecycle_hooks(
                    reinterpret_cast<std::uint8_t*>(image_));
            if (lifecycle_result == LifecycleValidation::active) {
                const LifecycleValidation active_status =
                    draw_oracle_validated
                        ? LifecycleValidation::active
                        : LifecycleValidation::active_without_draw_oracle;
                observer.set_runtime_status(
                    true, true, true, draw_oracle_validated, active_status);
                g_lifecycle_observing.store(true,
                                            std::memory_order_release);
                g_lifecycle_draw_oracle.store(draw_oracle_validated,
                                              std::memory_order_release);
            }
        } else {
            lifecycle_observer().reset();
            lifecycle_observer().set_runtime_status(
                false, false, false, false, LifecycleValidation::disabled);
        }
        if (retained_static_runtime_requested() &&
            !g_lifecycle_hooks_installed) {
            auto& observer = lifecycle_observer();
            observer.reset();
            const LifecycleValidation lifecycle_result = install_lifecycle_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
            if (lifecycle_result == LifecycleValidation::active) {
                observer.set_runtime_status(
                    true, true, true, false,
                    LifecycleValidation::active_without_draw_oracle);
                g_lifecycle_observing.store(true, std::memory_order_release);
            }
        }
        const bool retained_sources_installed =
            retained_static_runtime_requested() &&
            g_lifecycle_hooks_installed &&
            install_retained_source_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
        report(retained_sources_installed ?
                   "retained_mob_sources_installed" :
                   "retained_mob_sources_inactive",
               retained_sources_installed ?
                   "verified_shared_main_secondary_parser_admission_owners" :
                   "disabled_or_owner_signature_chain_mismatch");
        const bool retained_scene_installed = retained_sources_installed &&
            object_lighting_installed && scene_profile_installed &&
            install_retained_scene_seam(
                reinterpret_cast<std::uint8_t*>(image_));
        report(retained_scene_installed ?
                   "retained_static_scene_installed" :
                   "retained_static_scene_inactive",
               retained_scene_installed ?
                   "verified_preparation_bypass_and_owned_visibility_boundary" :
                   "disabled_or_prerequisite_or_seam_signature_mismatch");
        report(object_plan_installed ? "object_render_plan_installed" :
                                       "object_render_plan_rejected",
               object_plan_installed ?
                   "exact_lifecycle_oracle_mutations_and_visual_loop" :
                   "prerequisite_signature_or_transaction_failure");
        report(object_suffix_cut_installed ?
                   "object_suffix_cut_installed" :
                   "object_suffix_cut_inactive",
               object_suffix_cut_installed ?
                   "verified_route_explicit_inputs_and_common_epilogue" :
                   "route_helper_or_hook_chain_mismatch");
        const bool hud_visuals_installed = native_installed &&
            install_hud_visual_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
        report(hud_visuals_installed ?
                   "hud_visual_publication_installed" :
                   "hud_visual_publication_rejected",
               native_installed ? g_hud_visual_install_detail :
                                  "native_sink_inactive");
        const bool map_preview_installed =
            install_map_preview_hooks(reinterpret_cast<std::uint8_t*>(image_));
        report(map_preview_installed ? "world_map_preview_hooks_installed" :
            "world_map_preview_hooks_rejected",g_map_preview_hook_failure);
        const bool character_pane_text_installed =
            install_character_pane_text_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
        report(character_pane_text_installed ?
                   "character_pane_owned_text_installed" :
                   "character_pane_owned_text_rejected",
               g_character_pane_install_detail);
        const bool chat_text_installed = character_pane_text_installed &&
            install_chat_text_hooks(reinterpret_cast<std::uint8_t*>(image_));
        report(chat_text_installed ? "chat_owned_text_installed" :
                                     "chat_owned_text_rejected",
               g_chat_install_detail);
        const bool item_card_text_installed = character_pane_text_installed &&
            install_item_card_text_hooks(reinterpret_cast<std::uint8_t*>(image_));
        const bool camp_input_installed=install_camp_input_hook(reinterpret_cast<std::uint8_t*>(image_));
        const bool camp_installed = install_camp_inventory(reinterpret_cast<std::uint8_t*>(image_),camp_input_installed);
        // Combat popup input shares this exact active-call owner. Keep it
        // until bridge teardown even when the independent camp install fails.
        report(camp_input_installed?"combat_input_installed":"combat_input_rejected",
               camp_input_installed?"verified_direct_active_message_call":"active_message_call_owner_mismatch");
        report(camp_installed&&camp_input_installed?"camp_input_installed":"camp_input_rejected",
               camp_installed&&camp_input_installed?"verified_direct_active_message_call":
                                                    "camp_or_active_message_call_owner_mismatch");
        report(camp_installed ? "camp_grid_installed" : "camp_grid_rejected",
               camp_installed ? "owned_layout_enumeration_pick_scroll_native_visuals_temporary" :
                                "entry_owner_or_native_contract_mismatch");
        if (!camp_installed) bridge_note_feature_off(bridge_feature_off_camp_grid);
        // Cards are adopted by camp_inventory's DescribeItem hook; without it
        // they keep their legacy surface text (one line per session).
        report(item_card_text_installed && camp_installed ?
                   "item_card_owned_text_installed" : "item_card_owned_text_inactive",
               !item_card_text_installed ? g_item_card_install_detail :
               camp_installed ? "verified_clear_and_camp_describe_item_adoption" :
                                "camp_inventory_inactive_card_text_stays_legacy");
        const bool visual_publication_installed = retained_scene_installed &&
            hud_visuals_installed && install_visual_publication_hooks(
                reinterpret_cast<std::uint8_t*>(image_),terrain_installed);
        report(visual_publication_installed ? "owned_visual_publication_installed" :
                                             "owned_visual_publication_rejected",
               visual_publication_installed || (retained_scene_installed && hud_visuals_installed) ?
                   g_visual_install_detail : "retained_scene_or_resource_owner_inactive");
        if (!visual_publication_installed) bridge_note_feature_off(bridge_feature_off_owned_world);
        const bool window_membership_installed = visual_publication_installed &&
            g_lifecycle_hooks_installed && install_window_membership_hooks(
                reinterpret_cast<std::uint8_t*>(image_));
        report(window_membership_installed ? "static_window_retention_installed" :
                                             "static_window_retention_inactive",
               window_membership_installed ? "verified_server_window_delete_and_change_sites" :
                   "prerequisite_or_server_site_mismatch_window_exits_pop");
        const char* save_clash_failure = install_save_id_clash_check(
            reinterpret_cast<std::uint8_t*>(image_));
        report(save_clash_failure ? "save_id_clash_check_inactive" : "save_id_clash_check_installed",
               save_clash_failure ? save_clash_failure : "verified_load_dynamic_data_call");
        const char* teardown_failure = install_world_teardown_fix(
            reinterpret_cast<std::uint8_t*>(image_));
        report(teardown_failure ? "world_teardown_fix_inactive" : "world_teardown_fix_installed",
               teardown_failure ? teardown_failure : "verified_figure_manager_delete_site");
        const bool stock_shadows_suppressed = install_stock_shadow_suppression(
            reinterpret_cast<std::uint8_t*>(image_));
        report(stock_shadows_suppressed ? "stock_shadows_suppressed" :
                                          "stock_shadows_unsuppressed",
               stock_shadows_suppressed ?
                   "verified_draw_and_offscreen_branches_registry_settings_ignored" :
                   "branch_bytes_mismatch_game_shadows_follow_registry_settings");
        publish_addon_notice(visual_publication_installed);
    }
    startup_end(StartupStage::hooks, traced, installed_ ? "completed" : "rejected");
    return installed_;
}

bool EngineBridge::uninstall() {
    if (!installed_) {
        const bool restored = uninstall_engine_frame_begin_hook();
        if (!restored)
            report("engine_frame_begin_uninstall_pending", "restore_failed_or_foreign_call_owner_preserved");
        return restored;
    }
    if (!image_) return false;
    auto* const image = reinterpret_cast<std::uint8_t*>(image_);
    // The DLL unloads regardless of the result. Each independent owner is
    // restored even when another failed; a failed owner keeps only its own
    // forwarders and resources, and the bridge stays installed for a retry.
    bool restored = true;
    restored &= uninstall_camp_inventory();
    if(!uninstall_camp_input_hook()){
        report("camp_input_uninstall_pending","foreign_active_call_owner_preserved");
        restored=false;
    }
    restored &= uninstall_stock_shadow_suppression(image);
    restored &= uninstall_save_id_clash_check(image);
    restored &= uninstall_world_teardown_fix(image);
    restored &= uninstall_window_membership_hooks(image);
    restored &= uninstall_visual_publication_hooks();
    const bool camera_pan_restored = uninstall_camera_pan_hooks();
    restored &= camera_pan_restored;
    if (camera_pan_restored) restored &= uninstall_outer_frame_timing_hooks();
    else report("camera_pan_smoothing_uninstall_pending",
                "restore_failed_or_foreign_owner_preserved_timing_chain");
    // Optional timing must release its sites before the required begin call.
    const bool frame_begin_restored = uninstall_engine_frame_begin_hook();
    if (!frame_begin_restored)
        report("engine_frame_begin_uninstall_pending", "restore_failed_or_foreign_call_owner_preserved");
    restored &= frame_begin_restored;
    restored &= uninstall_item_card_text_hooks();
    restored &= uninstall_chat_text_hooks();
    restored &= uninstall_character_pane_text_hooks();
    restored &= uninstall_map_preview_hooks();
    restored &= uninstall_hud_visual_hooks();
    restored &= uninstall_hud_atlas_hooks();
    if (!uninstall_res_cache_release_hooks()) {
        report("res_cache_release_uninstall_pending",res_cache_release_status_name(res_cache_release_snapshot().status));
        restored = false;
    }
    uninstall_camera_mouse_normalize_hook(image);
    if(!uninstall_owned_sky_hook(image)) {
        report("owned_sky_uninstall_pending","restore_failed_or_foreign_hook_owner_preserved");
        restored = false;
    }
    if(!uninstall_owned_weather_hooks(image)) {
        report("owned_weather_uninstall_pending","restore_failed_or_foreign_hook_owner_preserved");
        restored = false;
    }
    restored &= uninstall_owned_frame_selection_hook(image);
    restored &= uninstall_particle_source_hook(image);
    restored &= uninstall_game_particle_hook(image);
    restored &= uninstall_game_ribbon_hook(image);
    restored &= uninstall_game_selection_hook(image);
    restored &= uninstall_game_render_entry_hook(image);
    restored &= uninstall_game_print_hooks(image);
#ifndef EID3D11_EMBEDDED
    restored &= uninstall_combat_text_hooks(image);
#endif
    uninstall_camera_mouse_pitch_hook(image);
    uninstall_camera_mouse_yaw_hook(image);
    uninstall_global_map_hit_test_hook(image);
    if (!uninstall_highlight_hooks(image)) {
        report("hover_highlight_uninstall_pending","foreign_call_site_owner_preserved");
        restored = false;
    }
    if (!uninstall_modal_backdrop_hooks(image)) {
        report("modal_backdrop_uninstall_pending","foreign_call_site_owner_preserved");
        restored = false;
    }
    uninstall_owned_cursor_hooks(image);
    uninstall_character_pane_stats_throttle(image);
    bridge_set_native_geometry_sink(nullptr, nullptr);
    g_lifecycle_draw_oracle.store(false, std::memory_order_release);
    g_lifecycle_observing.store(false, std::memory_order_release);
    // The object plan stores belong to these three hooks together.
    bool object_plans_restored = uninstall_object_suffix_cut_hook(image);
    object_plans_restored &= uninstall_object_visual_loop_hook(image);
    object_plans_restored &= uninstall_object_plan_mutation_hooks(image);
    if (object_plans_restored) {
        g_object_render_plans.clear();
        g_resolved_figure_geometry.clear();
    }
    restored &= object_plans_restored;
    restored &= uninstall_retained_scene_seam(image);
    restored &= uninstall_retained_source_hooks(image);
    uninstall_lifecycle_hooks(image);
    uninstall_object_lighting_hook(image);
    restored &= uninstall_scene_profile_hooks(image);
    if (!uninstall_terrain_hooks(image)) {
        report("native_terrain_uninstall_pending",
               "relight_call_restore_failed_owner_preserved");
        restored = false;
    }
    uninstall_native_geometry_hook(image);
    const auto& boundary = renderer_boundary_contract();
    if (g_renderer_outer_calls_installed) {
        auto* const first = image + boundary.begin_call_rva;
        auto* const last = image + boundary.end_call_rva + 5;
        DWORD previous = 0;
        bool calls_restored = VirtualProtect(first, static_cast<SIZE_T>(last-first),
                                             PAGE_EXECUTE_READWRITE, &previous) != FALSE;
        if (calls_restored) {
            const std::uint32_t calls[] = {boundary.begin_call_rva,boundary.end_call_rva};
            const void* hooks[] = {reinterpret_cast<const void*>(&hook_begin_frame),
                                   reinterpret_cast<const void*>(&hook_end_frame)};
            for (std::size_t i=0;i<2;++i) {
                auto* const call = image + calls[i];
                if (relative_call_targets(call,hooks[i]))
                    calls_restored &= write_relative_call(call,image+boundary.entries[i]);
                else if (!relative_call_targets(call,image+boundary.entries[i]))
                    calls_restored = false;
            }
            DWORD ignored = 0;
            calls_restored &= VirtualProtect(first,static_cast<SIZE_T>(last-first),
                                             previous,&ignored) != FALSE;
            FlushInstructionCache(GetCurrentProcess(),first,static_cast<SIZE_T>(last-first));
        }
        if (calls_restored) g_renderer_outer_calls_installed = false;
        restored &= calls_restored;
    }
    auto** table = reinterpret_cast<void**>(image + boundary.table_rva);
    SlotPatch slots[] = {
        {kBeginFrameSlot, 0, reinterpret_cast<void*>(&hook_begin_frame), reinterpret_cast<void**>(&g_begin_frame)},
        {kEndFrameSlot, 0, reinterpret_cast<void*>(&hook_end_frame), reinterpret_cast<void**>(&g_end_frame)},
        {kSimpleGeometrySlot, 0, reinterpret_cast<void*>(&hook_simple_geometry), reinterpret_cast<void**>(&g_simple_geometry)},
        {kFigureWithLightsSlot, 0, reinterpret_cast<void*>(&hook_figure_lights), reinterpret_cast<void**>(&g_figure_lights)},
        {kFigurePlacedSlot, 0, reinterpret_cast<void*>(&hook_figure_placed), reinterpret_cast<void**>(&g_figure_placed)},
    };
    DWORD protection = 0;
    if (VirtualProtect(table, 26 * sizeof(void*), PAGE_READWRITE, &protection)) {
        for (const auto& slot : slots) {
            if (table[slot.slot] == slot.hook && *slot.original)
                InterlockedExchangePointer(&table[slot.slot], *slot.original);
        }
        DWORD ignored = 0;
        VirtualProtect(table, 26 * sizeof(void*), protection, &ignored);
        FlushInstructionCache(GetCurrentProcess(), table, 26 * sizeof(void*));
    } else {
        restored = false;
    }
    if (restored) {
        installed_ = false;
        g_features_off = 0;
        g_addon_notice[0] = '\0';
    }
    return restored;
}
