void bridge_profile_api_entry(const char* kind, const void* caller) {
    if (!bridge_profile_enabled()) return;
    const auto now = bridge_now();
    auto caller_rva = EngineBridge::instance().image_rva(caller);
    if (!caller_rva) caller_rva = g_semantic.caller_rva;
    if (g_bridge_sample.active && g_previous_api_entry > 0 && now >= g_previous_api_entry) {
        BridgeFrameSample::ApiGap candidate{};
        candidate.ticks = now - g_previous_api_entry;
        if (!caller_rva && candidate.ticks * 1000 >= bridge_frequency() / 4) {
            void* frames[8]{};
            const USHORT count = CaptureStackBackTrace(0, static_cast<DWORD>(std::size(frames)),
                                                       frames, nullptr);
            for (USHORT index = 0; index < count && !caller_rva; ++index)
                caller_rva = EngineBridge::instance().image_rva(frames[index]);
        }
        candidate.from_kind = g_previous_api_kind;
        candidate.to_kind = kind ? kind : "unknown";
        candidate.from_rva = g_previous_api_rva;
        candidate.to_rva = caller_rva;
        auto& gaps = g_bridge_sample.largest_api_gaps;
        auto position = gaps.begin();
        while (position != gaps.end() && position->ticks >= candidate.ticks) ++position;
        if (position != gaps.end()) {
            std::move_backward(position, gaps.end() - 1, gaps.end());
            *position = candidate;
        }
    }
    g_previous_api_entry = now;
    g_previous_api_kind = kind ? kind : "unknown";
    g_previous_api_rva = caller_rva;
}

#if !defined(EID3D11_EMBEDDED)
SceneRendererTimingToken bridge_scene_renderer_timing_begin(
    SceneRendererTimingKind kind) noexcept {
    SceneRendererTimingToken token{};
    if (!g_scene_partition.active || !g_bridge_sample.active) return token;
    if (g_scene_partition.renderer_depth++) g_scene_partition.invalid = true;
    token.begin = bridge_now();
    token.context = static_cast<std::uint8_t>(
        current_scene_partition_context());
    token.kind = kind;
    token.active = token.begin > 0;
    if (!token.active) {
        if (g_scene_partition.renderer_depth)
            --g_scene_partition.renderer_depth;
        g_scene_partition.invalid = true;
    }
    return token;
}

void bridge_scene_renderer_timing_end(
    SceneRendererTimingToken& token) noexcept {
    if (!token.active) return;
    const auto end = bridge_now();
    if (!g_scene_partition.active || !g_bridge_sample.active ||
        !g_scene_partition.renderer_depth || end < token.begin ||
        token.context >= kScenePartitionContextCount) {
        invalidate_scene_partition();
        if (g_scene_partition.renderer_depth)
            --g_scene_partition.renderer_depth;
        token = {};
        return;
    }
    --g_scene_partition.renderer_depth;
    const auto context = static_cast<ScenePartitionContext>(token.context);
    if (current_scene_partition_context() != context)
        g_scene_partition.invalid = true;
    auto& values = token.kind == SceneRendererTimingKind::native_flush
        ? g_scene_partition.native_flush_ticks
        : g_scene_partition.ui_flush_ticks;
    const auto elapsed = end - token.begin;
    if (values[token.context] < 0 || elapsed < 0 ||
        values[token.context] >
            (std::numeric_limits<std::int64_t>::max)() - elapsed)
        g_scene_partition.invalid = true;
    else
        values[token.context] += elapsed;
    token = {};
}
#endif // !EID3D11_EMBEDDED

SceneQueueTimingToken bridge_scene_queue_timing_begin() noexcept {
    SceneQueueTimingToken token{};
    if (!g_scene_partition.active || !g_bridge_sample.active) return token;
    if (g_scene_partition.queue_depth) {
        g_scene_partition.invalid = true;
        return token;
    }
    token.begin = bridge_now();
    token.native_ticks_at_begin = scene_partition_renderer_total(
        SceneRendererTimingKind::native_flush);
    token.ui_ticks_at_begin = scene_partition_renderer_total(
        SceneRendererTimingKind::ui_flush);
    token.context = static_cast<std::uint8_t>(
        current_scene_partition_context());
    token.active = token.begin > 0;
    if (token.active) {
        g_scene_partition.queue_depth = 1;
    } else {
        g_scene_partition.invalid = true;
    }
    return token;
}

void bridge_scene_queue_timing_end(SceneQueueTimingToken& token) noexcept {
    if (!token.active) return;
    const auto end = bridge_now();
    const auto native_now = scene_partition_renderer_total(
        SceneRendererTimingKind::native_flush);
    const auto ui_now = scene_partition_renderer_total(
        SceneRendererTimingKind::ui_flush);
    if (!g_scene_partition.active || !g_bridge_sample.active ||
        g_scene_partition.queue_depth != 1 || end < token.begin ||
        native_now < token.native_ticks_at_begin ||
        ui_now < token.ui_ticks_at_begin ||
        token.context >= kScenePartitionContextCount) {
        invalidate_scene_partition();
        g_scene_partition.queue_depth = 0;
        token = {};
        return;
    }
    const auto native_ticks = native_now - token.native_ticks_at_begin;
    const auto ui_ticks = ui_now - token.ui_ticks_at_begin;
    const auto total_ticks = end - token.begin;
    if (total_ticks < native_ticks || total_ticks - native_ticks < ui_ticks) {
        g_scene_partition.invalid = true;
    } else {
        const auto context = static_cast<ScenePartitionContext>(token.context);
        if (current_scene_partition_context() != context)
            g_scene_partition.invalid = true;
        const auto packet_ticks = total_ticks - native_ticks - ui_ticks;
        auto& accumulated = g_scene_partition.packet_ticks[token.context];
        if (accumulated < 0 || packet_ticks < 0 || accumulated >
                (std::numeric_limits<std::int64_t>::max)() - packet_ticks) {
            g_scene_partition.invalid = true;
        } else {
            accumulated += packet_ticks;
            ++g_bridge_sample.scene_partition_queue_calls;
        }
    }
    g_scene_partition.queue_depth = 0;
    token = {};
}

