#ifdef EID3D11_EMBEDDED
namespace owned {

// The embedded counterpart of the scene seam (submit_owned_visual_scene): the
// host calls it once per world draw after its objects published appearance,
// pose and lights and the retained scene committed the tick.
// Same atlas-to-icon builder as submit_hud_visual; the embedded host supplies
// completed carrier values and a synchronous renderer sink, never retail memory.
HudVisualPublication& hud_embedded_publication() noexcept {return g_hud_visuals;}
bool hud_embedded_submit_visual(const HudPublishedVisual& visual,
    const EmbeddedHudVisualInput& input, void* context, EmbeddedHudVisualSink sink) noexcept {
    if (!visual.visible) return visual.complete;
    if (!sink) return false;
    try {
        std::vector<NativeTextureCoordinate> coordinates;
        std::vector<NativeOwnedTextureMip> mips;
        NativeGeometryView view{};
        if (!build_hud_visual_view(visual, input.u_shift, input.v_shift,
                input.default_colors ? kFigureUseDefaultColors : 0u,
                input.color_sum ? 0x10u : 0u, 255, input.object_to_clip,
                input.diffuse, false, coordinates, mips, view)) return false;
        if (input.default_colors) {
            view.default_diffuse = input.diffuse;
            view.default_specular = input.specular;
        }
        return sink(context, view);
    } catch (...) { return false; }
}
bool hud_embedded_submit_portrait(const EmbeddedHudPortraitInput& input,
    void* context, EmbeddedHudVisualSink sink) noexcept {
    if (!sink || !g_hud_visuals.owns_active_screen()) return false;
    try {
        NativeGeometryView view = input.model;
        view.object_to_clip = input.state.object_to_clip;
        view.semantic_kind = SemanticKind::ui;
        view.u_shift = input.state.u_shift; view.v_shift = input.state.v_shift;
        view.default_diffuse = input.state.diffuse;
        view.fog = 255;
        view.flags = input.state.color_sum ? 8u : 0u;
        apply_native_placed_state(view, input.model.morphs, input.model.morph_count,
            {}, NativeOrdering::preserve, !view.diffuse, input.state.diffuse, input.state.specular);
        std::vector<NativeTextureCoordinate> coordinates;
        std::vector<NativeOwnedTextureMip> mips;
        HudPublishedVisual texture;
        if (input.texture_name) {
            bool found = false;
            const auto* placement = input.whole_atlas ? nullptr : &input.placement;
            if (!g_hud_visuals.resolve_texture(input.texture_name, placement, texture, found)) return false;
            if (!found && input.base_texture_name &&
                !g_hud_visuals.resolve_texture(input.base_texture_name, placement, texture, found)) return false;
            if (!texture.texture || !texture.texture->source) return false;
            if (placement) {
                const auto& p = *placement;
                if (!p.atlas_width || !p.source_width || !p.source_height ||
                    texture.texture->width != p.source_width || texture.texture->height != p.source_height ||
                    std::uint64_t(p.destination_x)+p.copy_width>p.atlas_width ||
                    std::uint64_t(p.destination_y)+p.copy_height>p.atlas_width ||
                    std::uint64_t(p.source_x)+p.copy_width>p.source_width ||
                    std::uint64_t(p.source_y)+p.copy_height>p.source_height) return false;
                if (!remap_hud_coordinates(view.texture_coordinates,view.texture_coordinate_count,
                        p,view.u_shift,view.v_shift,coordinates)) return false;
                view.texture_coordinates = coordinates.data(); view.u_shift=view.v_shift=0;
            }
            for (const auto& mip:texture.texture->mips) {
                if (std::uint64_t(mip.byte_offset)+mip.bytes>texture.texture->source->size()) return false;
                mips.push_back({texture.texture->source->data()+mip.byte_offset,mip.width,mip.height,mip.bytes});
            }
            NativeOwnedTextureFormat format{};
            if (!hud_texture_format(texture.texture->format,format)) return false;
            view.owned_texture.identity=texture.texture_identity;
            view.owned_texture.generation=texture.texture_generation+(texture.overlay_generation<<32u);
            view.owned_texture.format=format; view.owned_texture.mips=mips.data();
            view.owned_texture.mip_count=static_cast<std::uint32_t>(mips.size());
        }
        return sink(context,view);
    } catch (...) { return false; }
}

const EmbeddedVisualFrameInputs* bridge_embedded_visual_inputs() noexcept { return g_embedded_visual_inputs; }
bool bridge_embedded_owned_visual_frame(const EmbeddedVisualFrameInputs& inputs,
                                        std::vector<std::int32_t>* drawn,
                                        std::vector<EmbeddedVisualOmission>* omitted) noexcept {
    if (drawn) drawn->clear();
    if (omitted) omitted->clear();
    struct Scope {
        bool active;
        std::uint32_t depth;
        explicit Scope(const EmbeddedVisualFrameInputs& value) noexcept
            : active(g_visual_publication_active), depth(g_world_draw_depth) {
            begin_owned_terrain_world_frame();
            g_embedded_visual_inputs = &value;
            g_visual_publication_active = true;
            g_world_draw_depth = 1;
        }
        ~Scope() {
            end_owned_terrain_world_frame();
            g_embedded_visual_inputs = nullptr;
            g_visual_publication_active = active;
            g_world_draw_depth = depth;
        }
    } scope(inputs);
    try {
        if (inputs.scene_flags & 0x100u) {
            if (!inputs.terrain_source || !inputs.terrain_frame ||
                !inputs.terrain_source->terrain || !inputs.terrain_source->geometry ||
                !inputs.terrain_material.enabled ||
                inputs.terrain_frame->status != OwnedTerrainPacketStatus::ready ||
                !inputs.terrain_frame->spatial_ready ||
                inputs.terrain_frame->source != inputs.terrain_source->terrain ||
                inputs.terrain_frame->inputs.source_generation != inputs.terrain_source->source_generation ||
                inputs.terrain_frame->inputs.source_revision != inputs.terrain_source->source_revision ||
                inputs.terrain_frame->spatial_object_to_world != inputs.terrain_to_world)
                throw "embedded_shadow_terrain_unavailable";
            auto& terrain = g_owned_terrain_frame;
            terrain.source_values = *inputs.terrain_source;
            terrain.front_end = *inputs.terrain_frame;
            terrain.object_to_world = inputs.terrain_to_world;
            terrain.world_to_clip = inputs.world_to_clip;
            terrain.world_transform_valid = true;
            terrain.world_serial = terrain.front_end.inputs.world_frame_serial;
            terrain.shadow_material = inputs.terrain_material;
            if (inputs.terrain_dynamic) {
                terrain.dynamic.resize(inputs.terrain_dynamic->size());
                for (std::size_t i=0; i<terrain.dynamic.size(); ++i)
                    if ((*inputs.terrain_dynamic)[i]) terrain.dynamic[i] = *(*inputs.terrain_dynamic)[i];
            }
            NativeStaticSubmission request;
            request.operation = NativeStaticSubmission::Operation::terrain_frame;
            request.terrain_state = &terrain.source_values.geometry->animation;
            request.layer_shifts = &terrain.source_values.geometry->layer_shifts;
            NativeGeometryView view; view.static_submission = &request;
            NativeGeometryResult result;
            if (!g_native_sink_submit || !g_native_sink_submit(g_native_sink_context, view, result))
                throw "embedded_shadow_terrain_state";
        }
        // A stable non-null token stands in for the game's scene object; the
        // embedded branches never read through it.
        static std::uint8_t scene_token = 0;
        reset_owned_visual_draw(&scene_token);
        g_native_world_lighting_frame = {};
        if (publish_native_world_lighting(nullptr) != FigureFallbackReason::none) {
            report_object_plan_failure("embedded_world_lighting");
            return false;
        }
        g_owned_visual_world_frame.camera_anchor_z = inputs.camera_anchor_z;
        if (!prepare_owned_world_shadows(&scene_token, nullptr, inputs.world_to_clip)) return false;
        auto& frame = g_owned_visual_world_frame;
        if (!frame.shadow_ready || frame.coverage.world_to_clip != inputs.world_to_clip) {
            report_object_plan_failure("embedded_shadow_frame_unavailable");
            return false;
        }
        if (frame.color_submitted) return true;
        frame.color_submitted = true;
        // Sun/point depth is complete before ground and object colour consume it.
        if ((inputs.scene_flags & 0x100u) &&
            (!inputs.draw_terrain || !inputs.draw_terrain(inputs.terrain_context)))
            throw "embedded_terrain_color";
        const bool submitted = submit_owned_visual_color(&scene_token, false, true);
        if (frame.values) {
            for (std::size_t i = 0; i < frame.prepared.size() && i < frame.values->entities.size(); ++i) {
                const auto& sample = frame.values->entities[i];
                const auto& prepared = frame.prepared[i];
                if (prepared.submitted) {
                    if (drawn) drawn->push_back(sample.resource.signed_id);
                    continue;
                }
                if (!omitted) continue;
                const char* reason = "native_submission";
                if (!prepared.claimed) reason = "mesh_unclaimed";
                else if (sample.status != RetainedVisualStatus::ready)
                    reason = retained_visual_status_name(static_cast<std::uint32_t>(sample.status));
                else if (!sample.assembly) reason = "assembly_missing";
                else if (!sample.prepared) reason = "prepared_resources_missing";
                else if (prepared.parts.empty() || std::none_of(prepared.parts.begin(), prepared.parts.end(),
                    [](const auto& part) { return part.visible; })) reason = "no_visible_parts";
                else if (!prepared.bounds.valid) reason = "world_bounds_unavailable";
                else if (!prepared.contribution.color) reason = "outside_color_coverage";
                omitted->push_back({sample.resource.signed_id, reason});
            }
        }
        return submitted;
    } catch (const char* reason) {
        report_object_plan_failure(reason);
        return false;
    } catch (...) {
        report_object_plan_failure("embedded_owned_scene_frame");
        return false;
    }
}

} // namespace owned
#endif
